import React, { Component } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  IconButton,
  Typography,
  Box,
  TextField,
  Grid,
  Paper,
  Chip
} from '@mui/material';
import { 
  Close as CloseIcon,
  Save as SaveIcon,
  Inventory as MaterialIcon
} from '@mui/icons-material';
import { MachineStateData } from '../../data/MachineStateData';
import { MaterialLibrary, MaterialType } from '../../data/Common/MaterialLibrary';
import { Material } from '../../data/Common/Material';
import { Job } from '../../data/Job';
import { MaterialEditorForm } from './MaterialEditorForm';
import { ConfigurationData } from '../../data/ConfigurationData';

interface MaterialEditorProps {
  open: boolean;
  onClose: () => void;
  machineState: MachineStateData;
}

interface MaterialEditorState {
  material: Material;
  saveDialog: boolean;
  libraryDialog: boolean;
}

export class MaterialEditor extends Component<MaterialEditorProps, MaterialEditorState> {
  constructor(props: MaterialEditorProps) {
    super(props);
    
    // Initialize with current job values if available
    const currentJob = props.machineState.currentJob;
    let material = currentJob?.material;
    
    // If no material exists, create one and assign it to the job
    if (!material) {
      material = new Material();
      material.name = 'New Material';
      material.type = MaterialType.Wood;
      material.xLength = 6;
      material.yLength = 8;
      material.height = 1.5;
      material.materialColor = ConfigurationData.Instance.defaultMaterialColor;
      
      // Create job if it doesn't exist
      if (!currentJob) {
        const newJob = new Job();
        newJob.name = 'New Job';
        newJob.material = material;
        props.machineState.currentJob = newJob;
      } else {
        currentJob.material = material;
      }
    }
    
    this.state = {
      material,
      saveDialog: false,
      libraryDialog: false,
    };
  }

  componentDidUpdate(prevProps: MaterialEditorProps) {
    // Update state when props change (new job loaded)
    // Use job name comparison to avoid issues with test job object references
    const prevJob = prevProps.machineState.currentJob;
    const currentJob = this.props.machineState.currentJob;
    
    const jobChanged = prevJob?.name !== currentJob?.name || 
                      (!prevJob && currentJob) || 
                      (prevJob && !currentJob);
    
    if (jobChanged) {
      let material = currentJob?.material;
      
      // If no material exists, create one and assign it to the job
      if (!material) {
        material = new Material();
        material.name = 'New Material';
        material.type = MaterialType.Wood;
        material.xLength = 6;
        material.yLength = 8;
        material.height = 1.5;
        material.materialColor = ConfigurationData.Instance.defaultMaterialColor;
        
        if (currentJob) {
          currentJob.material = material;
        }
      }
      
      this.setState({
        material,
        saveDialog: false,
        libraryDialog: false,
      });
    }
  }

  handleMaterialChange = (field: keyof Material, value: any) => {
    // Use setState callback to properly update the material property
    this.setState(prevState => {
      // Update the material property directly since we're working with the job's material instance
      (prevState.material as any)[field] = value;
      
      return { material: prevState.material }; // Force re-render
    });
  };

  handleSave = () => {
    this.props.onClose();
  };

  handleSaveToLibrary = () => {
    this.setState({ saveDialog: true });
  };

  handleLoadFromLibrary = () => {
    this.setState({ libraryDialog: true });
  };

  handleConfirmSaveToLibrary = () => {
    const materialLibrary = MaterialLibrary.Instance;
    const materialToSave = this.state.material.clone();
    materialToSave.name = this.state.material.name || "Custom Material";
    
    materialLibrary.materials.push(materialToSave);
    this.setState({ saveDialog: false });
  };

  handleLoadMaterialFromLibrary = (material: Material) => {
    // Clone the library material and replace the current material
    const clonedMaterial = material.clone();
    
    // Replace the job's material with the cloned one
    if (this.props.machineState.currentJob) {
      this.props.machineState.currentJob.material = clonedMaterial;
    }
    
    this.setState({ 
      material: clonedMaterial,
      libraryDialog: false 
    });
  };

  getMaterialTypeColor = (type: MaterialType) => {
    switch (type) {
      case MaterialType.Wood: return 'success';
      case MaterialType.Metal: return 'info';
      case MaterialType.Plastic: return 'warning';
      case MaterialType.Composite: return 'secondary';
      default: return 'default';
    }
  };

  handleCancel = () => {
    this.props.onClose();
  };

  render() {
    const { open } = this.props;
    const { material, saveDialog, libraryDialog } = this.state;
    const materialLibrary = MaterialLibrary.Instance;

    return (
      <>
        <Dialog 
          open={open} 
          onClose={this.handleCancel}
          maxWidth="lg"
          fullWidth
        >
          <DialogTitle>
            <Box display="flex" justifyContent="space-between" alignItems="center">
              <Typography variant="h6">Edit Material</Typography>
              <IconButton onClick={this.handleCancel} size="small">
                <CloseIcon />
              </IconButton>
            </Box>
          </DialogTitle>

          <DialogContent>
            <MaterialEditorForm
              material={material}
              onMaterialChange={this.handleMaterialChange}
              onSaveToLibrary={this.handleSaveToLibrary}
              onLoadFromLibrary={this.handleLoadFromLibrary}
            />
          </DialogContent>

          <DialogActions>
            <Button onClick={this.handleSave} variant="contained">
              Done
            </Button>
          </DialogActions>
        </Dialog>

        {/* Save to Library Dialog */}
        <Dialog open={saveDialog} onClose={() => this.setState({ saveDialog: false })} maxWidth="sm" fullWidth>
          <DialogTitle>Save Material to Library</DialogTitle>
          <DialogContent>
            <Typography variant="body2" color="text.secondary" paragraph>
              Save this material configuration to your library for future use.
            </Typography>
            
            <TextField
              fullWidth
              label="Material Name"
              value={material.name}
              onChange={(e) => this.handleMaterialChange('name', e.target.value)}
              sx={{ mt: 2 }}
              placeholder="Enter a descriptive name for this material"
            />
            
            <Box sx={{ mt: 2, p: 2, backgroundColor: 'background.default', borderRadius: 1 }}>
              <Typography variant="body2" gutterBottom>
                <strong>Material Summary:</strong>
              </Typography>
              <Typography variant="body2">
                Type: {material.type} | Size: {material.xLength}" × {material.yLength}" × {material.height}"
              </Typography>
            </Box>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => this.setState({ saveDialog: false })}>Cancel</Button>
            <Button variant="contained" onClick={this.handleConfirmSaveToLibrary} startIcon={<SaveIcon />}>
              Save to Library
            </Button>
          </DialogActions>
        </Dialog>

        {/* Load from Library Dialog */}
        <Dialog open={libraryDialog} onClose={() => this.setState({ libraryDialog: false })} maxWidth="md" fullWidth>
          <DialogTitle>Load Material from Library</DialogTitle>
          <DialogContent>
            <Typography variant="body2" color="text.secondary" paragraph>
              Select a material from your library to load its properties.
            </Typography>
            
            <Grid container spacing={2}>
              {materialLibrary.materials.map((libMaterial, index) => (
                <Grid item xs={12} sm={6} key={index}>
                  <Paper 
                    sx={{ 
                      p: 2, 
                      cursor: 'pointer',
                      '&:hover': { borderColor: 'primary.light', borderWidth: 1, borderStyle: 'solid' }
                    }}
                    onClick={() => this.handleLoadMaterialFromLibrary(libMaterial)}
                  >
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                      <MaterialIcon sx={{ color: 'text.secondary' }} />
                      <Typography variant="subtitle2">
                        {libMaterial.name}
                      </Typography>
                    </Box>
                    
                    <Chip 
                      label={libMaterial.type} 
                      size="small" 
                      color={this.getMaterialTypeColor(libMaterial.type) as any}
                      sx={{ mb: 1 }}
                    />
                    
                    <Typography variant="body2" color="text.secondary">
                      {libMaterial.xLength}" × {libMaterial.yLength}" × {libMaterial.height}"
                    </Typography>
                    
                    <Box
                      sx={{
                        width: '100%',
                        height: 8,
                        backgroundColor: libMaterial.materialColor,
                        borderRadius: 1,
                        mt: 1,
                        border: `1px solid ${ConfigurationData.Instance.secondaryBorderColor}`
                      }}
                    />
                  </Paper>
                </Grid>
              ))}

              {materialLibrary.materials.length === 0 && (
                <Grid item xs={12}>
                  <Paper sx={{ p: 4, textAlign: 'center' }}>
                    <MaterialIcon sx={{ fontSize: 48, color: 'text.secondary', mb: 2 }} />
                    <Typography variant="h6" color="text.secondary" gutterBottom>
                      No Materials in Library
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Define and save materials to build your library.
                    </Typography>
                  </Paper>
                </Grid>
              )}
            </Grid>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => this.setState({ libraryDialog: false })}>Close</Button>
          </DialogActions>
        </Dialog>
      </>
    );
  }
}