import { SwapHoriz as SwapHorizIcon } from '@mui/icons-material';
import { Box, FormControl, InputLabel, MenuItem, Select, Typography } from '@mui/material';
import React, { useState } from 'react';
import { Machine } from '../../../../machine/Machine';
import { MoveType } from '../../../../machine/MoveType';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class SetMoveTypeStep extends FlowStep {
    readonly __type = 'SetMoveTypeStep';
    readonly category = ['Machine', 'Movement'];
    readonly name = 'Set Move Type';
    readonly description = 'Sets the movement type (rapid, linear, etc.)';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(SwapHorizIcon, { sx: { color: 'primary.main' } });
    }

    // Step parameters
    public moveType: MoveType = MoveType.Absolute;

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return SetMoveTypeStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().movement.SetMoveType(this.moveType);
            return SetMoveTypeStep.DONE_PATH;
        } catch (error) {
            console.error('SetMoveType failed:', error);
            return SetMoveTypeStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [SetMoveTypeStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const moveTypeStr = this.moveType === MoveType.Absolute ? 'Absolute' : 'Relative';
        return (
            <Typography variant="caption">
                Set move type to {moveTypeStr}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const EditUI: React.FC = () => {
            const [moveType, setMoveType] = useState(this.moveType);

            // Update the instance when the local state changes
            React.useEffect(() => {
                this.moveType = moveType;
            }, [moveType]);

            return (
                <Box sx={{ p: 2, minWidth: 300 }}>
                    <FormControl fullWidth size="small" sx={{ mt: 2 }}>
                        <InputLabel>Move Type</InputLabel>
                        <Select
                            value={moveType}
                            label="Move Type"
                            onChange={(e) => setMoveType(e.target.value as MoveType)}
                        >
                            <MenuItem value={MoveType.Absolute}>Absolute</MenuItem>
                            <MenuItem value={MoveType.Relative}>Relative</MenuItem>
                        </Select>
                    </FormControl>

                    <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                        Absolute: Moves to exact coordinates. Relative: Moves relative to current position.
                    </Typography>
                </Box>
            );
        };

        return React.createElement(EditUI);
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






