import { Build as ToolIcon } from '@mui/icons-material';
import { Box, Checkbox, FormControlLabel, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowNumberValue, ValueSource } from '../../../FlowNumberValue';
import { FlowNumberValueEditor } from '../../../FlowNumberValueEditor';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class ChangeToToolStep extends FlowStep {
    readonly __type = 'ChangeToToolStep';
    readonly category = ['Machine', 'Features'];
    readonly name = 'Change Tool';
    readonly description = 'Changes to a specific tool number';

    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(ToolIcon, { sx: { color: 'primary.main' } });
    }

    // Step parameters
    public toolNumberValue: FlowNumberValue = new FlowNumberValue();
    public returnToCurrentPosition: boolean = true;

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return ChangeToToolStep.DONE_PATH;
        }

        try {
            // Get tool number from data value
            let toolNumber: number;
            if (this.toolNumberValue.valueSource === ValueSource.DataElement) {
                const value = this.getValueFromData(data, this.toolNumberValue.dataPath);
                toolNumber = Number(value) || 1;
            } else {
                toolNumber = this.toolNumberValue.numberValue;
            }

            await Machine.getInstance().features.ChangeToTool(toolNumber, this.returnToCurrentPosition);
            return ChangeToToolStep.DONE_PATH;
        } catch (error) {
            console.error('ChangeToTool failed:', error);
            return ChangeToToolStep.DONE_PATH; // Still done, just with error logged
        }
    }

    private getValueFromData(data: FlowStepData, path: string): any {
        if (!path) return undefined;

        const allData = data.getAllData();
        const pathParts = path.split('.');

        let current = allData;
        for (const part of pathParts) {
            if (current && typeof current === 'object' && part in current) {
                current = current[part];
            } else {
                return undefined;
            }
        }

        return current;
    }

    results(): string[] {
        return [ChangeToToolStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const toolNumber = this.toolNumberValue.valueSource === ValueSource.DataElement
            ? this.toolNumberValue.dataPath
            : this.toolNumberValue.numberValue;

        return (
            <Typography variant="caption">
                Change to tool {toolNumber}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void; flow: any; flowStep?: any }): React.ReactNode {
        const { flow } = props;

        return (
            <Box sx={{ p: 2, minWidth: 400 }}>
                <Typography variant="h6" gutterBottom>
                    Change Tool Configuration
                </Typography>

                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    Specify the tool number to change to.
                </Typography>

                <FlowNumberValueEditor
                    numberValue={this.toolNumberValue}
                    flow={flow}
                    flowStep={this}
                    label="Tool Number"
                />

                <Box sx={{ mt: 2 }}>
                    <ObserveState
                        key={`change-to-tool-return-position-${this.id}`}
                        listenTo={this}
                        properties={['returnToCurrentPosition']}
                        control={() => (
                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={this.returnToCurrentPosition}
                                        onChange={(e) => {
                                            this.returnToCurrentPosition = e.target.checked;
                                        }}
                                    />
                                }
                                label="Return to current position after tool change"
                            />
                        )}
                    />
                </Box>
            </Box>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon', 'toolNumberValue']) as any;
        data.__type = this.__type;
        data.toolNumberValue = this.toolNumberValue.toJSON();
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['toolNumberValue']);

        // Handle new format
        if (data.toolNumberValue) {
            this.toolNumberValue.fromJSON(data.toolNumberValue);
        }
        // Migrate from old format (toolNumber property)
        else if (data.toolNumber !== undefined) {
            this.toolNumberValue.numberValue = data.toolNumber;
            this.toolNumberValue.valueSource = ValueSource.DirectValue;
        }
    }
}





