import { Box, Typography } from '@mui/material';
import { useState } from 'react';
import { ToolLibrary } from '../../data/Common/ToolLibrary';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineStateData } from '../../data/MachineStateData';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { FixtureNameInputDialog } from './FixtureNameInputDialog';
import { FixtureSelectionDialog } from './FixtureSelectionDialog';
import { ToolSelectionDialog } from './ToolSelectionDialog';

/**
 * Props for MachineActionsPanel component
 */
interface MachineActionsPanelProps {
    /** Optional callbacks for custom material/clamp editor handling */
    onEditMaterial?: () => void;
    onEditClamps?: () => void;
    /** Minimum width of the panel (default: '200px') */
    minWidth?: string;
    /** Gap between action buttons (default: 0.5) */
    gap?: number;
    /** Show specific actions (default: all true) */
    showActions?: {
        changeFixture?: boolean;
        rememberPoint?: boolean;
        editMaterial?: boolean;
        editClamps?: boolean;
        changeTool?: boolean;
    };
}

/**
 * Reusable panel for common machine setup actions
 * Displays links for fixture, material, clamp management and shows current tool
 * Manages dialog visibility - dialogs handle their own action logic
 * 
 * @example
 * <MachineActionsPanel />
 * 
 * @example
 * // Show only specific actions
 * <MachineActionsPanel
 *   showActions={{
 *     changeFixture: true,
 *     rememberPoint: false,
 *     editMaterial: true,
 *     editClamps: false,
 *     changeTool: true
 *   }}
 * />
 */
export function MachineActionsPanel({
    onEditMaterial,
    onEditClamps,
    minWidth = '200px',
    gap = 0.5,
    showActions = {}
}: MachineActionsPanelProps) {
    const config = ConfigurationData.Instance;
    const machineState = MachineStateData.Instance;
    const toolLibrary = ToolLibrary.Instance;

    // Dialog visibility state
    const [fixtureDialogOpen, setFixtureDialogOpen] = useState(false);
    const [fixtureNameDialogOpen, setFixtureNameDialogOpen] = useState(false);
    const [toolDialogOpen, setToolDialogOpen] = useState(false);

    // Default all actions to visible
    const {
        changeFixture = true,
        rememberPoint = true,
        editMaterial = true,
        editClamps = true,
        changeTool = true
    } = showActions;

    // Shared button styles
    const linkButtonStyle = {
        width: '100%',
        padding: '4px 8px',
        backgroundColor: 'transparent',
        color: config.primaryColor,
        border: 'none',
        cursor: 'pointer',
        fontSize: '0.9rem',
        fontWeight: 'normal',
        textAlign: 'left' as const,
        textDecoration: 'underline',
        '&:hover': {
            textDecoration: 'none',
            fontWeight: 'bold'
        }
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap, minWidth }}>
            {/* Change Fixture */}
            {changeFixture && (
                <ObserveState
                    key="machine-actions-change-fixture"
                    listenTo={ConfigurationState.Instance}
                    properties={['currentFixture']}
                    control={() => {
                        const currentFixture = ConfigurationState.Instance.currentFixture;
                        const fixtureLabel = currentFixture?.fixtureNumber || 'None';

                        return (
                            <Box
                                component="button"
                                sx={linkButtonStyle}
                                onClick={() => setFixtureDialogOpen(true)}
                            >
                                Change Fixture ({fixtureLabel})
                            </Box>
                        );
                    }}
                />
            )}

            {/* Remember Point */}
            {rememberPoint && (
                <Box
                    component="button"
                    sx={linkButtonStyle}
                    onClick={() => setFixtureNameDialogOpen(true)}
                >
                    Remember Point
                </Box>
            )}

            {/* Edit Material */}
            {editMaterial && (
                <Box
                    component="button"
                    sx={linkButtonStyle}
                    onClick={onEditMaterial}
                >
                    Edit Material
                </Box>
            )}

            {/* Edit Clamps */}
            {editClamps && (
                <Box
                    component="button"
                    sx={linkButtonStyle}
                    onClick={onEditClamps}
                >
                    Edit Clamps
                </Box>
            )}

            {/* Current Tool Display with Change Link */}
            {changeTool && (
                <Box
                    sx={{
                        mt: 1,
                        p: 1.5,
                        border: 1,
                        borderColor: config.borderColor,
                        borderRadius: 1,
                        position: 'relative'
                    }}
                >
                    {/* Label on border */}
                    <Typography
                        variant="body2"
                        sx={{
                            position: 'absolute',
                            top: -8,
                            left: 8,
                            backgroundColor: 'background.paper',
                            px: 0.5,
                            color: config.mutedTextColor,
                            fontSize: '0.75rem',
                            fontWeight: 'normal'
                        }}
                    >
                        Current Tool
                    </Typography>

                    {/* Tool display and change link */}
                    <ObserveState
                        key="machine-actions-current-tool"
                        listenTo={machineState}
                        properties={['currentToolNumber']}
                        control={() => {
                            const currentToolNumber = machineState.currentToolNumber;
                            const tool = toolLibrary.tools.find(t => t.toolNumber === currentToolNumber);
                            const toolLabel = tool ? `T${tool.toolNumber.toString().padStart(2, '0')} - ${tool.displayName}` : 'None';

                            return (
                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                                    <Typography
                                        sx={{
                                            fontSize: '0.9rem',
                                            fontWeight: 'normal',
                                            color: config.darkTextColor
                                        }}
                                    >
                                        {toolLabel}
                                    </Typography>
                                    <Box
                                        component="button"
                                        sx={linkButtonStyle}
                                        onClick={() => setToolDialogOpen(true)}
                                    >
                                        Change Tool
                                    </Box>
                                </Box>
                            );
                        }}
                    />
                </Box>
            )}

            {/* Fixture Selection Dialog */}
            <FixtureSelectionDialog
                open={fixtureDialogOpen}
                onClose={() => setFixtureDialogOpen(false)}
            />

            {/* Fixture Name Input Dialog */}
            <FixtureNameInputDialog
                open={fixtureNameDialogOpen}
                onClose={() => setFixtureNameDialogOpen(false)}
            />

            {/* Tool Selection Dialog */}
            <ToolSelectionDialog
                open={toolDialogOpen}
                onClose={() => setToolDialogOpen(false)}
            />
        </Box>
    );
}
