import { Home as HomeIcon } from '@mui/icons-material';
import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class HomeMachineStep extends FlowStep {
    readonly __type = 'HomeMachineStep';
    readonly category = ['Machine', 'System'];
    readonly name = 'Home Machine';
    readonly description = 'Homes all machine axes to establish reference position';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(HomeIcon, { sx: { color: 'warning.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return HomeMachineStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().system.HomeMachine();
            return HomeMachineStep.DONE_PATH;
        } catch (error) {
            console.error('HomeMachine failed:', error);
            return HomeMachineStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [HomeMachineStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Home machine: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        return (
            <Box sx={{ p: 2, minWidth: 300 }}>
                <Typography variant="h6" gutterBottom>Home Machine</Typography>
                <Typography variant="body2" color="text.secondary">
                    This step will home the machine to establish the reference position for all axes.
                    This is typically required before performing any machining operations.
                </Typography>

                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 2 }}>
                    <Button variant="contained" onClick={props.onClose}>OK</Button>
                </Box>
            </Box>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}





