import { RemoveCircle as RemoveToolIcon } from '@mui/icons-material';
import { Box, Checkbox, FormControlLabel, Typography } from '@mui/material';
import React, { useState } from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class RemoveToolStep extends FlowStep {
    readonly __type = 'RemoveToolStep';
    readonly category = ['Machine', 'Features'];
    readonly name = 'Remove Tool';
    readonly description = 'Removes the current tool (no tool active)';

    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(RemoveToolIcon, { sx: { color: 'warning.main' } });
    }

    // Step parameters
    public returnToCurrentPosition: boolean = true;

    static readonly DONE_PATH = 'done';
    static readonly NO_TOOL_NUMBER = 0; // Special tool number for "no tool"

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return RemoveToolStep.DONE_PATH;
        }

        try {
            // Set no-tool flag in flow data
            data.noTool = true;

            // Remove tool by changing to special tool number 0
            await Machine.getInstance().features.ChangeToTool(RemoveToolStep.NO_TOOL_NUMBER, this.returnToCurrentPosition);

            return RemoveToolStep.DONE_PATH;
        } catch (error) {
            console.error('RemoveTool failed:', error);
            return RemoveToolStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [RemoveToolStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Remove tool: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const RemoveToolEditUI: React.FC = () => {
            const [returnToPosition, setReturnToPosition] = useState(this.returnToCurrentPosition);

            // Update the instance when the local state changes
            React.useEffect(() => {
                this.returnToCurrentPosition = returnToPosition;
            }, [returnToPosition]);

            return (
                <Box sx={{ p: 2, minWidth: 300 }}>
                    <Typography variant="body2" sx={{ mb: 2 }}>
                        This step will remove the current tool, leaving no tool active in the spindle.
                    </Typography>

                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={returnToPosition}
                                onChange={(e) => setReturnToPosition(e.target.checked)}
                            />
                        }
                        label="Return to current position after removing tool"
                    />
                </Box>
            );
        };

        return React.createElement(RemoveToolEditUI);
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}