import {
    Box,
    Checkbox,
    Collapse,
    FormControl,
    FormControlLabel,
    InputLabel,
    MenuItem,
    Select,
    TextField,
    ToggleButton,
    ToggleButtonGroup,
    Typography
} from '@mui/material';
import { CoordinateType } from '../../data/Common/CoordinateType';
import { Fixture, FixtureLibrary } from '../../data/Common/FixtureLibrary';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { Flow } from '../../flow/Flow';
import { FlowPositionValue, ReferencePointType, ZHandlingMode } from '../../flow/FlowPositionValue';
import { FlowStep } from '../../flow/FlowStep';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { FlowDataSelector } from './FlowDataSelector';

// Helper component to display calculated point
function CalculatedPointDisplay({ positionValue }: { positionValue: FlowPositionValue }) {
    // Calculate point directly (now synchronous)
    const calculatedPoint = positionValue.calculatePoint();

    return (
        <>
            <Typography variant="body2">
                {positionValue.referenceType === ReferencePointType.FromData ?
                    `From Data: ${positionValue.selectedDataPath || 'No data selected'}` :
                    `X: ${calculatedPoint.x.toFixed(3)}, Y: ${calculatedPoint.y.toFixed(3)}, Z: ${calculatedPoint.z.toFixed(3)}`
                }
            </Typography>
            <Typography variant="caption" color="text.secondary">
                Coordinate Type: {CoordinateType[calculatedPoint.coordinateType]}
            </Typography>
        </>
    );
}

export interface FlowPositionValueEditorProps {
    positionValue: FlowPositionValue;
    flow: Flow;
    flowStep: FlowStep;
}

export function FlowPositionValueEditor({
    positionValue,
    flow,
    flowStep
}: FlowPositionValueEditorProps) {
    // Get computed values for rendering
    const availableFixtures = FixtureLibrary.Instance.fixtures
        .filter((fixture: Fixture) => fixture.showAsSelectable && !fixture.systemControlled);

    return (
        <ObserveState
            key="flow-position-value-editor"
            listenTo={positionValue}
            properties={['referenceType', 'selectedFixture', 'selectedDataPath', 'offsetEnabled', 'xOffset', 'yOffset', 'zOffset', 'zHandlingMode']}
            control={() => (
                <Box sx={{ p: 2 }}>
                    <Typography variant="h6" gutterBottom>
                        Position Configuration
                    </Typography>

                    {/* Reference Point Type Selector */}
                    <FormControl fullWidth margin="normal">
                        <InputLabel>Reference Point</InputLabel>
                        <Select
                            value={positionValue.referenceType}
                            label="Reference Point"
                            onChange={(e) => positionValue.setReferenceType(e.target.value as ReferencePointType)}
                        >
                            <MenuItem value={ReferencePointType.WorkHome}>Work Home (default)</MenuItem>
                            <MenuItem value={ReferencePointType.MachineZero}>Machine Zero</MenuItem>
                            <MenuItem value={ReferencePointType.MachineHome}>Machine Home</MenuItem>
                            <MenuItem value={ReferencePointType.FromData}>From Data</MenuItem>
                            <MenuItem value={ReferencePointType.FromKnownPoint}>From Known Point (Fixture)</MenuItem>
                        </Select>
                    </FormControl>

                    {/* From Data Selector */}
                    {positionValue.referenceType === ReferencePointType.FromData && (
                        <Box sx={{ mt: 2 }}>
                            <FlowDataSelector
                                flow={flow}
                                flowStep={flowStep}
                                currentSelection={positionValue.selectedDataPath ? [positionValue.selectedDataPath] : []}
                                onChange={(paths, values) => {
                                    if (paths.length > 0) {
                                        positionValue.setSelectedDataPath(paths[0]);
                                    } else {
                                        positionValue.setSelectedDataPath('');
                                    }
                                }}
                                allowedTypes={positionValue.getAllowedTypes()}
                                label="Select CNC Point from Flow Data"
                                multiSelect={false}
                            />
                        </Box>
                    )}

                    {/* From Known Point (Fixture) Dropdown */}
                    {positionValue.referenceType === ReferencePointType.FromKnownPoint && (
                        <FormControl fullWidth margin="normal">
                            <InputLabel>Select Fixture</InputLabel>
                            <Select
                                value={positionValue.selectedFixture}
                                label="Select Fixture"
                                onChange={(e) => positionValue.selectedFixture = e.target.value}
                            >
                                {availableFixtures.map((fixture) => (
                                    <MenuItem key={fixture.fixtureNumber} value={fixture.fixtureNumber}>
                                        {fixture.name} ({fixture.fixtureNumber}) - ({fixture.xOffset.toFixed(3)}, {fixture.yOffset.toFixed(3)}, {fixture.zOffset.toFixed(3)})
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    )}

                    {/* Offset Controls */}
                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={positionValue.offsetEnabled}
                                onChange={(e) => positionValue.setOffsetEnabled(e.target.checked)}
                            />
                        }
                        label="Apply Offset"
                        sx={{ mt: 2 }}
                    />

                    <Collapse in={positionValue.offsetEnabled}>
                        <Box sx={{ ml: 4, mt: 1 }}>
                            <TextField
                                label="X Offset"
                                type="number"
                                value={positionValue.xOffset}
                                onChange={(e) => positionValue.setXOffset(parseFloat(e.target.value) || 0)}
                                fullWidth
                                margin="normal"
                                size="small"
                            />
                            <TextField
                                label="Y Offset"
                                type="number"
                                value={positionValue.yOffset}
                                onChange={(e) => positionValue.setYOffset(parseFloat(e.target.value) || 0)}
                                fullWidth
                                margin="normal"
                                size="small"
                            />

                            {/* Z Handling Mode Toggle */}
                            <Box sx={{ mt: 2, mb: 1 }}>
                                <Typography variant="subtitle2" gutterBottom>
                                    Z Handling
                                </Typography>
                                <ToggleButtonGroup
                                    value={positionValue.zHandlingMode}
                                    exclusive
                                    onChange={(e, newMode) => {
                                        if (newMode !== null) {
                                            positionValue.setZHandlingMode(newMode as ZHandlingMode);
                                        }
                                    }}
                                    size="small"
                                    fullWidth
                                    sx={{
                                        '& .MuiToggleButton-root': {
                                            borderColor: ConfigurationDataColors.Instance.borderColor,
                                            color: ConfigurationDataColors.Instance.darkTextColor,
                                            backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor,
                                            '&.Mui-selected': {
                                                backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                                                color: ConfigurationDataColors.Instance.lightTextColor,
                                                '&:hover': {
                                                    backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                                                    filter: 'brightness(0.9)',
                                                },
                                            },
                                            '&:hover': {
                                                backgroundColor: ConfigurationDataColors.Instance.secondaryBorderColor,
                                                color: ConfigurationDataColors.Instance.darkTextColor,
                                            },
                                        },
                                    }}
                                >
                                    <ToggleButton value={ZHandlingMode.Value}>
                                        Use Value
                                    </ToggleButton>
                                    <ToggleButton value={ZHandlingMode.ZMax}>
                                        Use Z Max
                                    </ToggleButton>
                                </ToggleButtonGroup>
                            </Box>

                            {/* Z Offset input - only show when using Value mode */}
                            {positionValue.zHandlingMode === ZHandlingMode.Value && (
                                <TextField
                                    label="Z Offset"
                                    type="number"
                                    value={positionValue.zOffset}
                                    onChange={(e) => positionValue.setZOffset(parseFloat(e.target.value) || 0)}
                                    fullWidth
                                    margin="normal"
                                    size="small"
                                />
                            )}
                        </Box>
                    </Collapse>

                    {/* Current Point Display */}
                    <Box sx={{ mt: 2, p: 2, backgroundColor: 'grey.100', borderRadius: 1 }}>
                        <Typography variant="subtitle2" gutterBottom>
                            Calculated Point:
                        </Typography>
                        <CalculatedPointDisplay positionValue={positionValue} />
                    </Box>
                </Box>
            )}
        />
    );
}
