import { PlayArrow as PlayIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class ResumeStep extends FlowStep {
    readonly __type = 'ResumeStep';
    readonly category = ['Machine', 'Program'];
    readonly name = 'Resume';
    readonly description = 'Resumes paused program execution';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(PlayIcon, { sx: { color: 'success.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, 'Prototype: Resume machine operation');
            return ResumeStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().program.Resume();
            //Logger.Instance.log(LogCategory.System, 'Machine operation resumed');
            return ResumeStep.DONE_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Resume failed:', error);
            return ResumeStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [ResumeStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Resume: {result}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}





