import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  TextField,
  ToggleButton,
  ToggleButtonGroup,
  Typography,
} from '@mui/material';
import React, { useState } from 'react';
import { Fixture, FixtureLibrary, FixtureType } from '../../data/Common/FixtureLibrary';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineStateData } from '../../data/MachineStateData';
import { UserMessageQueue } from '../../data/UserMessageQueue';

interface FixtureNameInputDialogProps {
  open: boolean;
  onClose: () => void;
}

export function FixtureNameInputDialog({
  open,
  onClose
}: FixtureNameInputDialogProps) {
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [useCurrentLocation, setUseCurrentLocation] = useState(true);

  const handleSave = () => {
    const trimmedName = name.trim();

    // Validation
    if (!trimmedName) {
      setError('Please enter a name for the fixture');
      return;
    }

    const existingNames = FixtureLibrary.Instance.fixtures.map(f => f.name);
    if (existingNames.includes(trimmedName)) {
      setError('This name is already used for this fixture number. Please choose a different name.');
      return;
    }

    // Save the fixture position
    const machineState = MachineStateData.Instance;
    const currentFixture = ConfigurationState.Instance.currentFixture;
    const toolOffsets = machineState.currentToolOffsets;

    let x: number, y: number, z: number;

    if (useCurrentLocation) {
      const currentPoint = machineState.currentMachinePoint;
      x = currentPoint.x - toolOffsets.x;
      y = currentPoint.y - toolOffsets.y;
      z = currentPoint.z - toolOffsets.z;
    } else {
      if (!currentFixture) {
        UserMessageQueue.Instance.addMessage('❌ No current fixture selected');
        return;
      }

      const currentPoint = machineState.currentMachinePoint;
      currentFixture.xOffset = currentPoint.x - toolOffsets.x;
      currentFixture.yOffset = currentPoint.y - toolOffsets.y;
      currentFixture.zOffset = currentPoint.z - toolOffsets.z;

      UserMessageQueue.Instance.addMessage(`✓ Saved ${currentFixture.name} fixture position`);
      handleClose();
      return;
    }

    const newFixture = new Fixture(
      trimmedName,
      trimmedName,
      x,
      y,
      z,
      false,
      FixtureType.SavedPoint,
      true
    );
    FixtureLibrary.Instance.addFixture(newFixture);

    UserMessageQueue.Instance.addMessage(`✓ Created known point "${trimmedName}" from current location`);
    handleClose();
  };

  const handleClose = () => {
    setName('');
    setError('');
    setUseCurrentLocation(true);
    onClose();
  };

  const handleNameChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setName(event.target.value);
    // Clear error when user starts typing
    if (error) {
      setError('');
    }
  };

  const handleKeyPress = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter') {
      handleSave();
    }
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
      <DialogTitle>Create Saved Point</DialogTitle>
      <DialogContent sx={{ pb: 2 }}>
        <Box sx={{ mb: 3 }}>
          <ToggleButtonGroup
            value={useCurrentLocation ? 'location' : 'fixture'}
            exclusive
            onChange={(_, newValue) => {
              if (newValue !== null) {
                setUseCurrentLocation(newValue === 'location');
              }
            }}
            fullWidth
            sx={{
              mb: 2,
              '& .MuiToggleButton-root': {
                color: ConfigurationData.Instance.mutedTextColor,
                backgroundColor: ConfigurationData.Instance.lightBackgroundColor,
                borderColor: ConfigurationData.Instance.borderColor,
                borderWidth: '2px',
                '&.Mui-selected': {
                  backgroundColor: ConfigurationData.Instance.primaryColor,
                  color: ConfigurationData.Instance.lightTextColor,
                  borderColor: ConfigurationData.Instance.primaryColor,
                  fontWeight: 'bold',
                  '&:hover': {
                    backgroundColor: ConfigurationData.Instance.primaryColor,
                  }
                },
                '&:hover': {
                  borderColor: ConfigurationData.Instance.primaryColor,
                  backgroundColor: ConfigurationData.Instance.lightBackgroundColor,
                }
              }
            }}
          >
            <ToggleButton value="fixture">
              Current Fixture Position
            </ToggleButton>
            <ToggleButton value="location">
              Current Machine Location
            </ToggleButton>
          </ToggleButtonGroup>

          <Typography variant="body2" color="text.secondary">
            {useCurrentLocation
              ? `Create a saved point at the current machine location.`
              : `Create a saved point using the position stored in the current fixture.`
            }
          </Typography>
        </Box>

        <TextField
          autoFocus
          margin="dense"
          label="Saved Point Name"
          fullWidth
          variant="outlined"
          value={name}
          onChange={handleNameChange}
          onKeyPress={handleKeyPress}
          error={!!error}
          helperText={error || 'Enter a unique name for this saved point'}
          placeholder="e.g., Top Left Corner, Center Position, etc."
          sx={{
            '& .MuiOutlinedInput-root': {
              backgroundColor: ConfigurationData.Instance.lightTextColor,
            }
          }}
        />
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose} variant="outlined">
          Cancel
        </Button>
        <Button
          onClick={handleSave}
          variant="contained"
          disabled={!name.trim()}
          sx={{ fontWeight: 'bold' }}
        >
          Create Saved Point
        </Button>
      </DialogActions>
    </Dialog>
  );
}
