

export class DataUtilities {
    // Prefix for date values in serialized data to ensure proper deserialization
    private static readonly DATE_PREFIX = 'DATEVALUE___';

    static spreadData(value: object, dataToSpread: object, exclude?: string[]): void {
        for (let i in dataToSpread) {
            if (exclude && exclude.length !== 0) {
                if (exclude.indexOf(i) !== -1) continue;
            }

            Reflect.set(value, i, Reflect.get(dataToSpread, i));
        }
    }

    static spreadDeepData(value: object, dataToSpread: object, exclude?: string[]): void {
        for (let i in dataToSpread) {
            if (exclude && exclude.length !== 0) {
                if (exclude.indexOf(i) !== -1) continue;
            }

            let newValue = Reflect.get(dataToSpread, i);
            if (typeof newValue === "object") {
                let copiedValue = Array.isArray(newValue) ? [] : {};
                this.spreadDeepData(copiedValue, newValue);
                Reflect.set(value, i, copiedValue);
            } else {
                Reflect.set(value, i, newValue);
            }
        }
    }

    static spreadDataWithoutFunction(value: object, dataToSpread: object, exclude?: string[]): void {
        for (let i in dataToSpread) {
            if (exclude && exclude.length !== 0) {
                if (exclude.indexOf(i) !== -1) continue;
            }

            let val = Reflect.get(dataToSpread, i);
            if (val instanceof Function) continue;

            Reflect.set(value, i, val);
        }
    }

    static generateUniqueId(): string {
        if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
            return crypto.randomUUID();
        }
        // Fallback for environments without crypto.randomUUID
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
            const r = Math.random() * 16 | 0, v = c === 'x' ? r : ((r & 0x3) | 0x8);
            return v.toString(16);
        });
    }

    /**
     * Gets storage-ready data from an object by including all properties except those in the exclude list
     * Automatically handles arrays by calling toJSON() on items that implement IStorable
     * @param obj The object to extract storage data from
     * @param exclude Array of property names to exclude from storage (includes StateManager observers automatically)
     * @returns Storage-ready object with all serializable properties
     */
    static getStorageData(obj: any, exclude: string[] = []): object {
        const result: any = {};

        // Always exclude StateManager observer properties
        const defaultExcludes = ['_____observers'];
        const allExcludes = [...defaultExcludes, ...exclude];

        // Get all property names from the object (including private properties via reflection)
        const propertyNames = Object.getOwnPropertyNames(obj);

        for (const propName of propertyNames) {
            // Skip excluded properties
            if (allExcludes.includes(propName)) continue;

            // Skip functions and static properties
            const descriptor = Object.getOwnPropertyDescriptor(obj, propName);
            if (!descriptor || typeof descriptor.value === 'function') continue;

            const value = descriptor.value;

            // Skip undefined values
            if (value === undefined) continue;

            // Handle different value types
            if (value === null) {
                result[this.getStoragePropertyName(propName)] = null;
            } else if (Array.isArray(value)) {
                // Handle arrays - recursively process each item that implements IStorable
                result[this.getStoragePropertyName(propName)] = value.map(item => {
                    if (item && typeof item === 'object' && typeof item.toJSON === 'function') {
                        return item.toJSON();
                    }
                    return item;
                });
            } else if (value instanceof Date) {
                // Handle Date objects with explicit prefix for reliable deserialization
                result[this.getStoragePropertyName(propName)] = this.DATE_PREFIX + value.toISOString();
            } else if (typeof value === 'object') {
                // For objects, don't auto-serialize - let the parent class handle complex sub-objects
                // This allows more flexibility and control
                result[this.getStoragePropertyName(propName)] = { ...value };
            } else {
                // Primitive values (string, number, boolean)
                result[this.getStoragePropertyName(propName)] = value;
            }
        }

        return result;
    }

    /**
     * Loads data into an object using property setters (if available) or direct assignment
     * Automatically handles sub-objects that implement IStorable by calling their fromJSON() method
     * @param obj The target object to load data into
     * @param data The source data object
     * @param exclude Array of property names to exclude from loading (StateManager observers excluded automatically)
     * @param factories Optional factory functions for creating typed objects from arrays
     */
    static loadStorageData(obj: any, data: any, exclude: string[] = [], factories: Record<string, () => any> = {}): void {
        if (!data) return;

        // Always exclude StateManager observer properties
        const defaultExcludes = ['_____observers'];
        const allExcludes = [...defaultExcludes, ...exclude];

        for (const [storageKey, value] of Object.entries(data)) {
            // Skip excluded properties
            if (allExcludes.includes(storageKey)) continue;

            const propertyName = this.getPropertyNameFromStorage(storageKey, obj);

            // Skip if property doesn't exist on target object
            if (!(propertyName in obj)) continue;

            // Try to use setter first (for StateManager notifications), fallback to direct assignment
            try {
                const descriptor = Object.getOwnPropertyDescriptor(obj, propertyName);
                const prototypeDescriptor = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(obj), propertyName);
                const hasSetters = (descriptor && descriptor.set) || (prototypeDescriptor && prototypeDescriptor.set);

                if (hasSetters) {
                    // Use setter
                    obj[propertyName] = this.createTypedValue(value, storageKey, propertyName, factories);
                } else {
                    // Check if current property value implements IStorable
                    const currentValue = obj[propertyName];
                    if (currentValue && typeof currentValue === 'object' && typeof currentValue.fromJSON === 'function') {
                        // Load into existing IStorable object
                        currentValue.fromJSON(value);
                    } else if (Array.isArray(value)) {
                        // Handle array properties with factory support
                        obj[propertyName] = this.createTypedArray(value, storageKey, propertyName, factories);
                    } else {
                        // Direct assignment
                        obj[propertyName] = this.createTypedValue(value, storageKey, propertyName, factories);
                    }
                }
            } catch (error) {
                console.warn(`Failed to set property ${propertyName} on object:`, error);
                // Fallback to direct assignment
                try {
                    obj[propertyName] = value;
                } catch (fallbackError) {
                    console.error(`Failed to set property ${propertyName} even with direct assignment:`, fallbackError);
                }
            }
        }
    }

    /**
     * Creates a typed value using factory functions if available
     * @param value The raw value from storage
     * @param storageKey The storage key (serialized form)
     * @param propertyName The actual property name on the object
     * @param factories Factory functions map
     * @returns Properly typed value
     */
    private static createTypedValue(value: any, storageKey: string, propertyName: string, factories: Record<string, () => any>): any {
        // Check if this value has the date prefix
        if (typeof value === 'string' && value.startsWith(this.DATE_PREFIX)) {
            // Remove prefix and parse as Date
            const dateString = value.substring(this.DATE_PREFIX.length);
            const parsedDate = new Date(dateString);
            if (!isNaN(parsedDate.getTime())) {
                return parsedDate;
            }
            // If parsing fails, log warning and return original value without prefix
            console.warn(`Failed to parse date string: ${dateString}`);
            return dateString;
        } if (value && typeof value === 'object' && !Array.isArray(value)) {
            // Try factory with both storage key and property name
            const factory = factories[storageKey] || factories[propertyName];
            if (factory) {
                const instance = factory();
                if (instance && typeof instance.fromJSON === 'function') {
                    instance.fromJSON(value);
                    return instance;
                }
            }
        }
        return value;
    }

    /**
     * Creates a typed array using factory functions if available
     * @param arrayData The array data from storage
     * @param storageKey The storage key (serialized form)
     * @param propertyName The actual property name on the object
     * @param factories Factory functions map
     * @returns Properly typed array
     */
    private static createTypedArray(arrayData: any[], storageKey: string, propertyName: string, factories: Record<string, () => any>): any[] {
        // Try factory with both storage key and property name
        const factory = factories[storageKey] || factories[propertyName];
        if (factory) {
            return arrayData.map(itemData => {
                const instance = factory();
                if (instance && typeof instance.fromJSON === 'function') {
                    instance.fromJSON(itemData);
                    return instance;
                } else {
                    return itemData;
                }
            });
        }
        return arrayData;
    }

    /**
     * Converts a property name to storage key format
     * Removes leading underscore for private properties
     */
    private static getStoragePropertyName(propertyName: string): string {
        return propertyName.startsWith('_') ? propertyName.substring(1) : propertyName;
    }

    /**
     * Converts a storage key back to property name format
     * Tries both with and without underscore prefix to support both conventions
     */
    private static getPropertyNameFromStorage(storageKey: string, obj: any): string {
        // If storage key already has underscore, use it as-is
        if (storageKey.startsWith('_')) {
            return storageKey;
        }

        // Try with underscore prefix first (common for private properties)
        const withUnderscore = '_' + storageKey;
        if (withUnderscore in obj) {
            return withUnderscore;
        }

        // Fall back to key as-is (for public properties or properties without underscore)
        return storageKey;
    }


    static getElapsedTime(startTime: Date, endTime: Date): string {
        let diff = endTime.getTime() - startTime.getTime();

        let msc = diff % 1000;

        let ss = Math.floor(diff / 1000);

        if (ss === 0) {
            return `${msc} ms`;
        }

        let mm = Math.floor(ss / 60);

        if (mm === 0) {
            return `${ss} second${ss > 1 ? "s" : ""}, ${msc} ms`;
        }

        ss = ss % 60;

        let hh = Math.floor(mm / 60);

        if (hh === 0) {
            return `${mm} minute${mm > 1 ? "s" : ""}, ${ss} second${ss > 1 ? "s" : ""}`;
        }

        mm = mm % 60;

        return `${`${hh}`.padStart(2, "0")}:${`${mm}`.padStart(2, "0")}:${`${ss}`.padStart(2, "0")}`;
    }


    // todo: add cache?

    // rules
    // - path is separated by .
    // - [] returns all items of array
    // - . on array without specifying that we want all items '[]' returns the value of the property
    // - . after [] returns new array with the items of that particular property
    // - [first] and [last] return the first and last item
    // eslint-disable-next-line
    static get(from: object, path: string, defaultvalue?: any): any {
    }

    static getString(from: object, path: string, defaultValue?: string): string | undefined {
        let val = this.get(from, path, defaultValue);

        if (typeof val === "object") {
            return JSON.stringify(val);
        } else if (val !== undefined) {
            return val + "";
        }
        return undefined;
    }

    static set(
        from: object,
        path: string,
        value: any,
        throwExceptionIfTargetIsNull: boolean = true,
        notCheckType: boolean = false,
        correctValues: boolean = false,
    ): void {
    }





}
