import { FlowStep } from "./FlowStep";
import { FlowStepRegistration } from "./FlowStepRegistration";

/**
 * @internal
 * FlowStepLibrary is internal to the flow system
 * Use FlowStepFactory for all external access to flow steps
 */
export class FlowStepLibrary {
    private static stepTypes: Map<string, new (...args: any[]) => FlowStep> = new Map();
    private static initialized = false;

    private static ensureInitialized(): void {
        if (!this.initialized) {
            // Use FlowStepRegistration to register all step types
            FlowStepRegistration.initialize();
            this.initialized = true;
        }
    }

    /**
     * @internal - Use FlowStepFactory instead
     */
    static registerStepType<T extends FlowStep>(type: string, stepClass: new (...args: any[]) => T): void {
        console.log(`[FlowStepLibrary] Registering step type: ${type}`);
        this.stepTypes.set(type, stepClass);
    }

    /**
     * @internal - Use FlowStepFactory instead
     * Unregister a step type (used for dynamic step refresh)
     */
    static unregisterStepType(type: string): void {
        console.log(`[FlowStepLibrary] Unregistering step type: ${type}`);
        this.stepTypes.delete(type);
    }

    static createStep(type: string, ...args: any[]): FlowStep {
        this.ensureInitialized();

        const StepClass = this.stepTypes.get(type);
        if (!StepClass) {
            throw new Error(`FlowStep type "${type}" not registered. Available types: ${Array.from(this.stepTypes.keys()).join(', ')}`);
        }
        return new StepClass(...args);
    }

    static getAllStepTypes(): string[] {
        this.ensureInitialized();
        return Array.from(this.stepTypes.keys());
    }

    static getStepsByCategory(categoryPath: string[]): string[] {
        this.ensureInitialized();
        const stepTypes: string[] = [];

        for (const [type, stepClass] of this.stepTypes.entries()) {
            try {
                const instance = new stepClass();
                if (this.categoryMatches(instance.category, categoryPath)) {
                    stepTypes.push(type);
                }
            } catch (error) {
                // Skip steps that can't be instantiated with default constructor
                console.warn(`Could not instantiate step type ${type} for category filtering:`, error);
            }
        }

        return stepTypes;
    }

    private static categoryMatches(stepCategory: string[], filterPath: string[]): boolean {
        if (filterPath.length === 0) return true; // Empty filter matches all
        if (stepCategory.length < filterPath.length) return false;

        for (let i = 0; i < filterPath.length; i++) {
            if (stepCategory[i] !== filterPath[i]) return false;
        }
        return true;
    }

    static getAllCategories(): string[][] {
        this.ensureInitialized();
        const categoriesSet = new Set<string>();

        for (const [, stepClass] of this.stepTypes.entries()) {
            try {
                const instance = new stepClass();
                // Add each level of the category hierarchy
                for (let i = 1; i <= instance.category.length; i++) {
                    const categoryPath = instance.category.slice(0, i).join('/');
                    categoriesSet.add(categoryPath);
                }
            } catch (error) {
                // Skip steps that can't be instantiated with default constructor
            }
        }

        return Array.from(categoriesSet).map(path => path.split('/'));
    }

    static getCategoryTree(): any {
        this.ensureInitialized();
        const tree: any = {};

        for (const [, stepClass] of this.stepTypes.entries()) {
            try {
                const instance = new stepClass();
                let current = tree;

                for (const categoryLevel of instance.category) {
                    if (!current[categoryLevel]) {
                        current[categoryLevel] = {};
                    }
                    current = current[categoryLevel];
                }
            } catch (error) {
                // Skip steps that can't be instantiated with default constructor
            }
        }

        return tree;
    }

    static isStepTypeRegistered(type: string): boolean {
        this.ensureInitialized();
        return this.stepTypes.has(type);
    }
}
