import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';
import { StateManager } from '../utils/statemanager/StateManager';
import { InputDefinitions } from './Machine/InputDefinitions';
import { OutputDefinitions } from './Machine/OutputDefinitions';

/**
 * Full input definition with number and state
 */
export class InputWithState {
    public number: number = 0;
    public centroidName: string = '';
    public name: string = '';
    public activeText: string = 'Active';
    public inactiveText: string = 'Inactive';
    public isActive: boolean = false;

    constructor() {
        // All properties have default values
    }
}

/**
 * Full output definition with number and state
 */
export class OutputWithState {
    public number: number = 0;
    public centroidName: string = '';
    public name: string = '';
    public activeText: string = 'Active';
    public inactiveText: string = 'Inactive';
    public isActive: boolean = false;
    private _M94M95Mapping?: number;

    constructor() {
        // All properties have default values
    }

    /**
     * Get M94M95 mapping number. Returns explicit mapping if set, otherwise 100 + output number
     */
    public getM94M95Mapping(): number {
        return this._M94M95Mapping ?? (100 + this.number);
    }

    /**
     * Set M94M95 mapping number. Pass undefined to use default (100 + output number)
     */
    public setM94M95Mapping(value?: number): void {
        this._M94M95Mapping = value;
    }
}

/**
 * Singleton class to manage I/O state
 * Combines API definitions, static metadata, and runtime state
 */
export class IOStateData {
    private static _instance: IOStateData;

    private _inputs: InputWithState[] = [];
    private _outputs: OutputWithState[] = [];
    private _isInitialized: boolean = false;

    private constructor() { }

    public static get Instance(): IOStateData {
        if (!IOStateData._instance) {
            IOStateData._instance = new IOStateData();
        }
        return IOStateData._instance;
    }

    public get inputs(): InputWithState[] {
        return this._inputs;
    }

    public get outputs(): OutputWithState[] {
        return this._outputs;
    }

    public get isInitialized(): boolean {
        return this._isInitialized;
    }

    /**
     * Initialize I/O state by fetching from API and combining with metadata
     */
    public async initialize(): Promise<void> {
        try {
            Logger.Instance.log(LogCategory.System, 'IOStateData: Initializing I/O state...');

            const machineInterface = MachineInterfaceManager.Instance.getMachineInterface();

            // Fetch definitions and current states from API
            const [inputDefs, outputDefs, inputStates, outputStates] = await Promise.all([
                machineInterface.io.GetInputDefinitions(),
                machineInterface.io.GetOutputDefinitions(),
                machineInterface.io.GetCurrentInputs(),
                machineInterface.io.GetCurrentOutputs()
            ]);

            // Combine API mappings with static metadata and current state
            this._inputs = InputDefinitions.createFullState(inputDefs, inputStates);
            this._outputs = OutputDefinitions.createFullState(outputDefs, outputStates);

            this._isInitialized = true;

            Logger.Instance.log(LogCategory.System, `IOStateData: Initialized with ${this._inputs.length} inputs and ${this._outputs.length} outputs`);

            StateManager.propertyChanged(this, 'inputs');
            StateManager.propertyChanged(this, 'outputs');
            StateManager.propertyChanged(this, 'isInitialized');
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'IOStateData: Failed to initialize I/O state:', error);
            throw error;
        }
    }

    /**
     * Update state of a specific input
     */
    public updateInputState(number: number, isActive: boolean): void {
        const input = this._inputs.find(i => i.number === number);
        if (input) {
            input.isActive = isActive;
            Logger.Instance.log(LogCategory.System, `IOStateData: Updated input ${number} state to ${isActive}`);
            StateManager.propertyChanged(this, 'inputs');
        }
    }

    /**
     * Update state of a specific output
     */
    public updateOutputState(number: number, isActive: boolean): void {
        const output = this._outputs.find(o => o.number === number);
        if (output) {
            output.isActive = isActive;
            Logger.Instance.log(LogCategory.System, `IOStateData: Updated output ${number} state to ${isActive}`);
            StateManager.propertyChanged(this, 'outputs');
        }
    }

    /**
     * Update all input states at once
     */
    public updateAllInputStates(states: Record<number, boolean>): void {
        this._inputs.forEach(input => {
            if (states[input.number] !== undefined) {
                input.isActive = states[input.number];
            }
        });
        Logger.Instance.log(LogCategory.System, 'IOStateData: Updated all input states');
        StateManager.propertyChanged(this, 'inputs');
    }

    /**
     * Update all output states at once
     */
    public updateAllOutputStates(states: Record<number, boolean>): void {
        this._outputs.forEach(output => {
            if (states[output.number] !== undefined) {
                output.isActive = states[output.number];
            }
        });
        Logger.Instance.log(LogCategory.System, 'IOStateData: Updated all output states');
        StateManager.propertyChanged(this, 'outputs');
    }

    /**
     * Get input by number
     */
    public getInputByNumber(number: number): InputWithState | undefined {
        return this._inputs.find(i => i.number === number);
    }

    /**
     * Get output by number
     */
    public getOutputByNumber(number: number): OutputWithState | undefined {
        return this._outputs.find(o => o.number === number);
    }

    /**
     * Get input by centroid name
     */
    public getInputByCentroidName(centroidName: string): InputWithState | undefined {
        return this._inputs.find(i => i.centroidName === centroidName);
    }

    /**
     * Get output by centroid name
     */
    public getOutputByCentroidName(centroidName: string): OutputWithState | undefined {
        return this._outputs.find(o => o.centroidName === centroidName);
    }
}
