import { IOStateData } from '../data/IOStateData';
import { UserMessageQueue } from '../data/UserMessageQueue';
import { ICNCIO, InputMapping, ISimulatorIOTesting, OutputMapping } from '../machine/ICNCIO';

export class SimulatorCNCIO implements ICNCIO, ISimulatorIOTesting {
  private vacuumOn: boolean = false;
  private dustCollectorOn: boolean = false;
  private dustBootRetracted: boolean = true;

  // Input override storage (for testing purposes only)
  private inputOverrides: Record<number, boolean> = {};

  // Output override storage (for testing purposes only)
  private outputOverrides: Record<number, boolean> = {};

  // Persistent output states (remembers manual on/off commands)
  private outputStates: Record<number, boolean> = {};

  // Input state caching for stable demo values
  private cachedInputStates: Record<number, boolean> = {};
  private lastInputCacheUpdate: number = 0;
  private readonly INPUT_CACHE_DURATION_MS = 5000; // 5 seconds

  // Cache for I/O definitions
  private inputDefinitionsCache: InputMapping[] | null = null;
  private outputDefinitionsCache: OutputMapping[] | null = null;

  async GetCurrentInputs(): Promise<Record<number, boolean>> {
    const now = Date.now();

    // Cache input states for demo stability (refresh every 5 seconds)
    if (now - this.lastInputCacheUpdate > this.INPUT_CACHE_DURATION_MS) {
      this.cachedInputStates = {};
      for (let i = 1; i <= 18; i++) {
        this.cachedInputStates[i] = Math.random() > 0.7; // 30% chance of being active
      }
      this.lastInputCacheUpdate = now;
    }

    // Apply any test overrides
    const finalStates = { ...this.cachedInputStates, ...this.inputOverrides };

    // Update IOStateData with current states for UI reactivity
    if (IOStateData.Instance.isInitialized) {
      IOStateData.Instance.updateAllInputStates(finalStates);
    }

    return finalStates;
  }

  async GetCurrentOutputs(): Promise<Record<number, boolean>> {
    // Start with persistent output states, default to false for undefined outputs
    const outputs: Record<number, boolean> = {};
    for (let i = 1; i <= 16; i++) {
      outputs[i] = this.outputStates[i] ?? false;
    }

    // Apply any test overrides
    const finalStates = { ...outputs, ...this.outputOverrides };

    // Update IOStateData with current states for UI reactivity
    if (IOStateData.Instance.isInitialized) {
      IOStateData.Instance.updateAllOutputStates(finalStates);
    }

    return finalStates;
  }

  async GetInputDefinitions(): Promise<InputMapping[]> {
    // Return cached result if available
    if (this.inputDefinitionsCache !== null) {
      return this.inputDefinitionsCache;
    }

    // Simulator subset of real inputs with stable number mappings
    const mappings: InputMapping[] = [
      { number: 1, centroidName: 'EStopOk' },
      { number: 2, centroidName: 'EStopOk2' },
      { number: 3, centroidName: 'SpindleOk' },
      { number: 4, centroidName: 'FirstAxisHomeLimitOk' },
      { number: 5, centroidName: 'SecondAxisHomeLimitOk' },
      { number: 6, centroidName: 'ProbeDetect' },
      { number: 7, centroidName: 'ProbeTripped' },
      { number: 8, centroidName: 'ToolIsUnclamped' },
      { number: 9, centroidName: 'ToolClamped_I' },
      { number: 10, centroidName: 'DrawBarReleased' },
      { number: 11, centroidName: 'Axis1DriveOk' },
      { number: 12, centroidName: 'Axis2DriveOk' },
      { number: 13, centroidName: 'Axis3DriveOk' },
      { number: 14, centroidName: 'LubeOk' },
      { number: 15, centroidName: 'AirPressureLowMessage' },
      { number: 16, centroidName: 'CycleStart2' },
      { number: 17, centroidName: 'FixedToolTouchPlate' },
      { number: 18, centroidName: 'MaterialToolTouchPlate' }
    ];

    // Cache the result to ensure consistent number mappings
    this.inputDefinitionsCache = mappings;
    return mappings;
  }

  async GetOutputDefinitions(): Promise<OutputMapping[]> {
    // Return cached result if available
    if (this.outputDefinitionsCache !== null) {
      return this.outputDefinitionsCache;
    }

    // Simulator subset of real outputs with stable number mappings
    const mappings: OutputMapping[] = [
      { number: 1, centroidName: 'NoFaultOut' },
      { number: 2, centroidName: 'SpinFWD' },
      { number: 3, centroidName: 'SpinREV' },
      { number: 4, centroidName: 'SpindleBrakeRelease' },
      { number: 5, centroidName: 'UnclampTool' },
      { number: 6, centroidName: 'Flood' },
      { number: 7, centroidName: 'Mist' },
      { number: 8, centroidName: 'LubePump' },
      { number: 9, centroidName: 'DustCollectionOn' },
      { number: 10, centroidName: 'OUTPUT1' },
      { number: 11, centroidName: 'OUTPUT2' },
      { number: 12, centroidName: 'DustFootActivate' },
      { number: 13, centroidName: 'LaserAlignActivate' },
      { number: 14, centroidName: 'PopUpPins' },
      { number: 15, centroidName: 'AirBlowNozzle' },
      { number: 16, centroidName: 'WorkLight' }
    ];

    // Cache the result to ensure consistent number mappings
    this.outputDefinitionsCache = mappings;
    return mappings;
  }

  async GetAvailableInputs(): Promise<Record<number, string>> {
    return {
      1: 'Limit Switch X+',
      2: 'Limit Switch X-',
      3: 'Limit Switch Y+',
      4: 'Limit Switch Y-',
      5: 'Limit Switch Z+',
      6: 'Limit Switch Z-',
      7: 'Tool Touch Pad',
      8: 'Material Touch Pad',
      9: 'Emergency Stop',
      10: 'Door Switch',
      11: 'Spindle Fault',
      12: 'Air Pressure',
      13: 'Coolant Level',
      14: 'Tool Changer Ready',
      15: 'Vacuum Sensor',
      16: 'Dust Boot Sensor'
    };
  }

  async GetAvailableOutputs(): Promise<Record<number, string>> {
    return {
      1: 'Spindle Enable',
      2: 'Spindle Direction',
      3: 'Coolant Flood',
      4: 'Coolant Mist',
      5: 'Tool Changer',
      6: 'Work Light',
      7: 'Vacuum Enable',
      8: 'Dust Collector',
      9: 'Dust Boot Deploy',
      10: 'Air Blast',
      11: 'Probe Deploy',
      12: 'Clamp 1',
      13: 'Clamp 2',
      14: 'Fixture Release',
      15: 'Status Light Green',
      16: 'Status Light Red'
    };
  }

  async GetIOAvailability(): Promise<Record<string, boolean>> {
    return {
      'inputs': true,
      'outputs': true,
      'analog_inputs': true,
      'analog_outputs': false,
      'pwm_outputs': true,
      'encoder_inputs': true,
      'high_speed_inputs': false
    };
  }

  async GetSystemInfo(): Promise<Record<string, any>> {
    return {
      'platform': 'HavenCNC Simulator',
      'version': '1.0.0',
      'build': 'Debug',
      'total_inputs': 16,
      'total_outputs': 16,
      'analog_inputs': 8,
      'pwm_outputs': 4,
      'encoder_inputs': 2,
      'update_rate_hz': 1000,
      'supported_features': ['inputs', 'outputs', 'pwm', 'encoders', 'overrides']
    };
  }

  async IsInputActive(inputNumber: number): Promise<boolean> {
    if (this.inputOverrides.hasOwnProperty(inputNumber)) {
      return this.inputOverrides[inputNumber];
    }

    // Simulate random input states for demo
    return Math.random() > 0.5;
  }

  async IsOutputActive(outputNumber: number): Promise<boolean> {
    if (this.outputOverrides.hasOwnProperty(outputNumber)) {
      return this.outputOverrides[outputNumber];
    }

    // Return persistent output state, default to false
    return this.outputStates[outputNumber] ?? false;
  }

  async IsInputAvailable(inputNumber: number): Promise<boolean> {
    // In simulator, inputs 1-18 are available
    return inputNumber >= 1 && inputNumber <= 18;
  }

  async IsOutputAvailable(outputNumber: number): Promise<boolean> {
    // In simulator, outputs 1-16 are available
    return outputNumber >= 1 && outputNumber <= 16;
  }

  async SetOutputState(outputNumber: number, state: boolean): Promise<void> {
    // Persist the output state
    this.outputStates[outputNumber] = state;

    // Update IOStateData for immediate UI updates
    if (IOStateData.Instance.isInitialized) {
      IOStateData.Instance.updateOutputState(outputNumber, state);
    }

    UserMessageQueue.Instance.addMessage(`✓ Set output ${outputNumber} to ${state ? 'ON' : 'OFF'}`);
  }

  async RetractDustBoot(): Promise<void> {
    this.dustBootRetracted = true;
    UserMessageQueue.Instance.addMessage('✓ Dust boot retracted');
  }

  async ExtendDustBoot(): Promise<void> {
    this.dustBootRetracted = false;
    UserMessageQueue.Instance.addMessage('✓ Dust boot extended');
  }

  async IsDustBootRetracted(): Promise<boolean> {
    return this.dustBootRetracted;
  }

  async StartVacuum(): Promise<void> {
    this.vacuumOn = true;
    UserMessageQueue.Instance.addMessage('✓ Vacuum started');
  }

  async StopVacuum(): Promise<void> {
    this.vacuumOn = false;
    UserMessageQueue.Instance.addMessage('✓ Vacuum stopped');
  }

  async IsVacuumOn(): Promise<boolean> {
    return this.vacuumOn;
  }

  async StartDustCollector(): Promise<void> {
    this.dustCollectorOn = true;
    UserMessageQueue.Instance.addMessage('✓ Dust collector started');
  }

  async StopDustCollector(): Promise<void> {
    this.dustCollectorOn = false;
    UserMessageQueue.Instance.addMessage('✓ Dust collector stopped');
  }

  async IsDustCollectorOn(): Promise<boolean> {
    return this.dustCollectorOn;
  }

  async OverrideInput(inputNumber: number, value: boolean): Promise<void> {
    this.inputOverrides[inputNumber] = value;

    // Update IOStateData for immediate UI updates
    if (IOStateData.Instance.isInitialized) {
      IOStateData.Instance.updateInputState(inputNumber, value);
    }

    UserMessageQueue.Instance.addMessage(`Override input ${inputNumber} to ${value ? 'ON' : 'OFF'} (test mode)`);
  }

  async ResetInputOverrides(): Promise<void> {
    this.inputOverrides = {};

    // Refresh all input states to remove override effects
    if (IOStateData.Instance.isInitialized) {
      const currentStates = await this.GetCurrentInputs();
      IOStateData.Instance.updateAllInputStates(currentStates);
    }

    UserMessageQueue.Instance.addMessage('Reset all input overrides (test mode)');
  }

  async OverrideOutput(outputNumber: number, value: boolean): Promise<void> {
    this.outputOverrides[outputNumber] = value;

    // Update IOStateData for immediate UI updates
    if (IOStateData.Instance.isInitialized) {
      IOStateData.Instance.updateOutputState(outputNumber, value);
    }

    UserMessageQueue.Instance.addMessage(`Override output ${outputNumber} to ${value ? 'ON' : 'OFF'} (test mode)`);
  }

  async ResetOutputOverrides(): Promise<void> {
    this.outputOverrides = {};

    // Refresh all output states to remove override effects
    if (IOStateData.Instance.isInitialized) {
      const currentStates = await this.GetCurrentOutputs();
      IOStateData.Instance.updateAllOutputStates(currentStates);
    }

    UserMessageQueue.Instance.addMessage('Reset all output overrides (test mode)');
  }
}
