import { StateManager } from '../utils/statemanager/StateManager';
import { ConfigurationData } from './ConfigurationData';
import { Fixture } from './Common/FixtureLibrary';
import { CNCPoint } from './CNCPoint';

/**
 * Configuration state for runtime data that doesn't need to be persisted
 * Used for temporary UI states, drag modes, selections, etc.
 * Implemented as singleton pattern following HavenCNC conventions
 */
export class ConfigurationState {
  private static _instance: ConfigurationState;
  
  // 3D Viewer interaction states
  private _isSpindleDragging: boolean = false;
  private _selectedObject: string | null = null;
  private _isOrbitEnabled: boolean = true;
  
  // UI interaction states
  private _isModalOpen: boolean = false;
  private _isDragging: boolean = false;
  private _isEditing: boolean = false;
  private _hoveredEdgeId: string | null = null;
  
  // Selection states
  private _selectedClampId: string | null = null;
  private _selectedToolId: string | null = null;
  
  // Proposed clamp position during dragging (similar to spindle proposed position)
  private _proposedClampPosition: CNCPoint | null = null;
  
  // Tool measurement state - tools that have been measured this session
  private _measuredToolNumbers: number[] = [];
  
  // Log viewer state - categories seen this session and excluded categories
  private _sessionLogCategories: string[] = [];
  private _excludedLogCategories: string[] = [];
  
  // Current fixture state
  private _currentFixture: Fixture | null = null;
  
  // Safe mode states
  private _delayOff: boolean = false;
  private _collisionOff: boolean = false;
  private _softLimitsOff: boolean = false;
  private _safeModeTimeoutId: number | null = null;
  private _safeModeStartTime: number | null = null;
  private _safeModeRemainingTime: number = 0;
  
  // I/O Override states (non-persistent for testing)
  private _overriddenInputs: Set<number> = new Set();
  private _overriddenOutputs: Set<number> = new Set();
  
  private constructor() {
    // Private constructor for singleton pattern
  }

  // 3D Viewer interaction state getters/setters
  public get isSpindleDragging(): boolean {
    return this._isSpindleDragging;
  }
  
  public set isSpindleDragging(value: boolean) {
    this._isSpindleDragging = value;
    StateManager.propertyChanged(this, 'isSpindleDragging');
  }

  public get selectedObject(): string | null {
    return this._selectedObject;
  }
  
  public set selectedObject(value: string | null) {
    this._selectedObject = value;
    StateManager.propertyChanged(this, 'selectedObject');
  }

  public get isOrbitEnabled(): boolean {
    return this._isOrbitEnabled;
  }
  
  public set isOrbitEnabled(value: boolean) {
    this._isOrbitEnabled = value;
    StateManager.propertyChanged(this, 'isOrbitEnabled');
  }

  // UI interaction state getters/setters
  public get isModalOpen(): boolean {
    return this._isModalOpen;
  }
  
  public set isModalOpen(value: boolean) {
    this._isModalOpen = value;
    StateManager.propertyChanged(this, 'isModalOpen');
  }

  public get isDragging(): boolean {
    return this._isDragging;
  }
  
  public set isDragging(value: boolean) {
    this._isDragging = value;
    StateManager.propertyChanged(this, 'isDragging');
  }

  public get isEditing(): boolean {
    return this._isEditing;
  }
  
  public set isEditing(value: boolean) {
    this._isEditing = value;
    StateManager.propertyChanged(this, 'isEditing');
  }

  public get hoveredEdgeId(): string | null {
    return this._hoveredEdgeId;
  }
  
  public set hoveredEdgeId(value: string | null) {
    this._hoveredEdgeId = value;
    StateManager.propertyChanged(this, 'hoveredEdgeId');
  }

  // Selection state getters/setters
  public get selectedClampId(): string | null {
    return this._selectedClampId;
  }
  
  public set selectedClampId(value: string | null) {
    this._selectedClampId = value;
    StateManager.propertyChanged(this, 'selectedClampId');
  }

  public get selectedToolId(): string | null {
    return this._selectedToolId;
  }
  
  public set selectedToolId(value: string | null) {
    this._selectedToolId = value;
    StateManager.propertyChanged(this, 'selectedToolId');
  }

  // Proposed clamp position getters/setters
  public get proposedClampPosition(): CNCPoint | null {
    return this._proposedClampPosition;
  }
  
  public set proposedClampPosition(value: CNCPoint | null) {
    this._proposedClampPosition = value;
    StateManager.propertyChanged(this, 'proposedClampPosition');
  }

  // Tool measurement state getters/setters
  public get measuredToolNumbers(): number[] {
    return this._measuredToolNumbers;
  }
  
  public set measuredToolNumbers(value: number[]) {
    this._measuredToolNumbers = value;
    StateManager.propertyChanged(this, 'measuredToolNumbers');
  }
  
  public addMeasuredTool(toolNumber: number): void {
    if (!this._measuredToolNumbers.includes(toolNumber)) {
      this._measuredToolNumbers.push(toolNumber);
      StateManager.propertyChanged(this, 'measuredToolNumbers');
    }
  }
  
  public removeMeasuredTool(toolNumber: number): void {
    const index = this._measuredToolNumbers.indexOf(toolNumber);
    if (index > -1) {
      this._measuredToolNumbers.splice(index, 1);
      StateManager.propertyChanged(this, 'measuredToolNumbers');
    }
  }
  
  public isToolMeasured(toolNumber: number): boolean {
    return this._measuredToolNumbers.includes(toolNumber);
  }

  // Log category state getters/setters
  public get sessionLogCategories(): string[] {
    return [...this._sessionLogCategories];
  }
  
  public set sessionLogCategories(value: string[]) {
    this._sessionLogCategories = [...value];
    StateManager.propertyChanged(this, 'sessionLogCategories');
  }
  
  public get excludedLogCategories(): string[] {
    return [...this._excludedLogCategories];
  }
  
  public set excludedLogCategories(value: string[]) {
    this._excludedLogCategories = [...value];
    StateManager.propertyChanged(this, 'excludedLogCategories');
  }
  
  public addSessionLogCategory(category: string): void {
    if (!this._sessionLogCategories.includes(category)) {
      this._sessionLogCategories.push(category);
      StateManager.propertyChanged(this, 'sessionLogCategories');
    }
  }
  
  public isCategoryExcluded(category: string): boolean {
    return this._excludedLogCategories.includes(category);
  }
  
  public toggleCategoryExclusion(category: string): void {
    const index = this._excludedLogCategories.indexOf(category);
    if (index >= 0) {
      this._excludedLogCategories.splice(index, 1);
    } else {
      this._excludedLogCategories.push(category);
    }
    StateManager.propertyChanged(this, 'excludedLogCategories');
  }
  
  public clearSessionLogCategories(): void {
    this._sessionLogCategories = [];
    this._excludedLogCategories = [];
    StateManager.propertyChanged(this, 'sessionLogCategories');
    StateManager.propertyChanged(this, 'excludedLogCategories');
  }

  // Current fixture state getters/setters
  public get currentFixture(): Fixture | null {
    return this._currentFixture;
  }
  
  public set currentFixture(value: Fixture | null) {
    this._currentFixture = value;
    StateManager.propertyChanged(this, 'currentFixture');
  }

  // Safe mode state getters/setters
  public get delayOff(): boolean {
    return this._delayOff;
  }
  
  public set delayOff(value: boolean) {
    this._delayOff = value;
    StateManager.propertyChanged(this, 'delayOff');
    if (value) {
      this.startSafeModeCountdown();
    } else {
      this.checkClearSafeModeCountdown();
    }
  }

  public get collisionOff(): boolean {
    return this._collisionOff;
  }
  
  public set collisionOff(value: boolean) {
    this._collisionOff = value;
    StateManager.propertyChanged(this, 'collisionOff');
    if (value) {
      this.startSafeModeCountdown();
    } else {
      this.checkClearSafeModeCountdown();
    }
  }

  public get softLimitsOff(): boolean {
    return this._softLimitsOff;
  }
  
  public set softLimitsOff(value: boolean) {
    this._softLimitsOff = value;
    StateManager.propertyChanged(this, 'softLimitsOff');
    if (value) {
      this.startSafeModeCountdown();
    } else {
      this.checkClearSafeModeCountdown();
    }
  }

  public get safeModeRemainingTime(): number {
    return this._safeModeRemainingTime;
  }

  public get isSafeModeActive(): boolean {
    return this._delayOff || this._collisionOff || this._softLimitsOff;
  }

  /**
   * Public method to restart the countdown with current timeout value
   * Used when timeout setting is changed while countdown is active
   */
  public restartSafeModeCountdown(): void {
    if (this.isSafeModeActive) {
      // Clear existing countdown if running
      if (this._safeModeTimeoutId !== null) {
        clearInterval(this._safeModeTimeoutId);
        this._safeModeTimeoutId = null;
      }
      
      // Start new countdown with current timeout setting
      this.startSafeModeCountdown();
    }
  }

  // Safe mode countdown management
  private startSafeModeCountdown(): void {
    // Get countdown duration from ConfigurationData
    const countdownDuration = ConfigurationData.Instance.safeModeTimeout;
    
    // If countdown is already running, restart it from the beginning
    if (this._safeModeTimeoutId !== null) {
      // Just reset the start time to restart the countdown
      this._safeModeStartTime = Date.now();
      this._safeModeRemainingTime = countdownDuration;
      StateManager.propertyChanged(this, 'safeModeRemainingTime');
      return;
    }

    // Start new countdown
    this._safeModeStartTime = Date.now();
    this._safeModeRemainingTime = countdownDuration;
    StateManager.propertyChanged(this, 'safeModeRemainingTime');

    // Update countdown every 100ms for smooth progress bar
    const updateInterval = setInterval(() => {
      if (this._safeModeStartTime === null) {
        clearInterval(updateInterval);
        return;
      }

      const elapsed = Date.now() - this._safeModeStartTime;
      this._safeModeRemainingTime = Math.max(0, countdownDuration - elapsed);
      
      // Use requestAnimationFrame to ensure safe DOM updates
      requestAnimationFrame(() => {
        StateManager.propertyChanged(this, 'safeModeRemainingTime');
      });

      // Check if countdown is complete
      if (this._safeModeRemainingTime <= 0) {
        clearInterval(updateInterval);
        this.resetAllSafeModes();
      }
    }, 100);

    this._safeModeTimeoutId = updateInterval as unknown as number;
  }

  private checkClearSafeModeCountdown(): void {
    // If all safe modes are turned off, clear the countdown
    if (!this._delayOff && !this._collisionOff && !this._softLimitsOff) {
      if (this._safeModeTimeoutId !== null) {
        clearTimeout(this._safeModeTimeoutId);
        clearInterval(this._safeModeTimeoutId);
        this._safeModeTimeoutId = null;
      }
      this._safeModeStartTime = null;
      this._safeModeRemainingTime = 0;
      StateManager.propertyChanged(this, 'safeModeRemainingTime');
    }
  }

  private resetAllSafeModes(): void {
    // Clear timeout first
    this._safeModeTimeoutId = null;
    this._safeModeStartTime = null;
    this._safeModeRemainingTime = 0;
    
    // Reset modes using a timeout to avoid unmounting slider during event handling
    setTimeout(() => {
      // Set the private fields directly to avoid triggering countdown restart
      const wasDelayOff = this._delayOff;
      const wasCollisionOff = this._collisionOff;
      const wasSoftLimitsOff = this._softLimitsOff;
      
      this._delayOff = false;
      this._collisionOff = false;
      this._softLimitsOff = false;
      
      // Only notify if values actually changed
      if (wasDelayOff) {
        StateManager.propertyChanged(this, 'delayOff');
      }
      if (wasCollisionOff) {
        StateManager.propertyChanged(this, 'collisionOff');
      }
      if (wasSoftLimitsOff) {
        StateManager.propertyChanged(this, 'softLimitsOff');
      }
      
      StateManager.propertyChanged(this, 'safeModeRemainingTime');
    }, 0);
  }

  // Utility methods for spindle selection behavior
  public selectSpindle(): void {
    this.selectedObject = 'spindle';
    this.isSpindleDragging = true;
    this.isOrbitEnabled = false;
  }

  public deselectSpindle(): void {
    if (this.selectedObject === 'spindle') {
      this.selectedObject = null;
    }
    this.isSpindleDragging = false;
    this.isOrbitEnabled = true;
  }

  public selectClamp(clampId: string): void {
    this.selectedClampId = clampId;
    this.selectedObject = `clamp-${clampId}`;
  }

  public deselectClamp(): void {
    this.selectedClampId = null;
    if (this.selectedObject?.startsWith('clamp-')) {
      this.selectedObject = null;
    }
  }

  // I/O Override state getters/setters
  public get overriddenInputs(): Set<number> {
    return new Set(this._overriddenInputs); // Return copy to prevent external mutation
  }

  public get overriddenOutputs(): Set<number> {
    return new Set(this._overriddenOutputs); // Return copy to prevent external mutation
  }

  public addInputOverride(inputNumber: number): void {
    this._overriddenInputs.add(inputNumber);
    StateManager.propertyChanged(this, 'overriddenInputs');
  }

  public removeInputOverride(inputNumber: number): void {
    this._overriddenInputs.delete(inputNumber);
    StateManager.propertyChanged(this, 'overriddenInputs');
  }

  public addOutputOverride(outputNumber: number): void {
    this._overriddenOutputs.add(outputNumber);
    StateManager.propertyChanged(this, 'overriddenOutputs');
  }

  public removeOutputOverride(outputNumber: number): void {
    this._overriddenOutputs.delete(outputNumber);
    StateManager.propertyChanged(this, 'overriddenOutputs');
  }

  public clearAllInputOverrides(): void {
    this._overriddenInputs.clear();
    StateManager.propertyChanged(this, 'overriddenInputs');
  }

  public clearAllOutputOverrides(): void {
    this._overriddenOutputs.clear();
    StateManager.propertyChanged(this, 'overriddenOutputs');
  }

  public clearAllSelections(): void {
    this.selectedObject = null;
    this.selectedClampId = null;
    this.selectedToolId = null;
    this.isSpindleDragging = false;
    this.isOrbitEnabled = true;
  }

  /**
   * Get the singleton instance
   */
  public static get Instance(): ConfigurationState {
    if (!ConfigurationState._instance) {
      ConfigurationState._instance = new ConfigurationState();
    }
    return ConfigurationState._instance;
  }
}
