import { CNCPoint } from '../CNCPoint';
import { CoordinateType } from './CoordinateType';
import { BoxPoints } from './BoxPoints';

/**
 * Represents a rectangular box with position and dimensions
 */
export class Box {
  public origin: CNCPoint;
  public width: number;
  public height: number;
  public length: number;  // 3D depth dimension
  public boxPoints: BoxPoints;  // 8 corner points for 3D box

  constructor(origin: CNCPoint = new CNCPoint(0, 0, 0, CoordinateType.MachineZero), width: number = 0, length: number = 0, height: number = 0, boxPoints?: BoxPoints) {
    this.origin = origin;
    this.width = width;
    this.height = height;
    this.length = length;
    
    // If boxPoints not provided, compute them from origin and dimensions
    if (boxPoints) {
      this.boxPoints = boxPoints;
    } else {
      // Import CoordinateUtil to compute box points
      const { CoordinateUtil } = require('../../utils/CoordinateUtil');
      this.boxPoints = CoordinateUtil.computeBoxPoints(origin, width, length, height);
    }
  }

  /**
   * Gets the right edge of the box
   */
  get right(): number {
    return this.origin.x + this.width;
  }

  /**
   * Gets the bottom edge of the box
   */
  get bottom(): number {
    return this.origin.y + this.height;
  }

  /**
   * Gets the center X coordinate
   */
  get centerX(): number {
    return this.origin.x + this.width / 2;
  }

  /**
   * Gets the center Y coordinate
   */
  get centerY(): number {
    return this.origin.y + this.height / 2;
  }

  /**
   * Gets the X coordinate of the origin
   */
  get x(): number {
    return this.origin.x;
  }

  /**
   * Gets the Y coordinate of the origin
   */
  get y(): number {
    return this.origin.y;
  }

  /**
   * Gets the Z coordinate of the origin
   */
  get z(): number {
    return this.origin.z;
  }

  /**
   * Check if a point is inside the box
   */
  contains(x: number, y: number): boolean {
    return x >= this.x && x <= this.right && y >= this.y && y <= this.bottom;
  }

  /**
   * Check if this box intersects with another box
   */
  intersects(other: Box): boolean {
    return !(other.x > this.right || 
             other.right < this.x || 
             other.y > this.bottom || 
             other.bottom < this.y);
  }

  /**
   * Create a copy of this box
   */
  clone(): Box {
    return new Box(this.origin, this.width, this.length, this.height, this.boxPoints);
  }

  /**
   * Returns a new Box with all points converted to MachineZero coordinates
   * This ensures consistent coordinate system for collision detection
   */
  toMachineZero(): Box {
    // Import CoordinateUtil to convert coordinates
    const { CoordinateUtil } = require('../../utils/CoordinateUtil');
    
    // Convert origin to MachineZero
    const machineZeroOrigin = CoordinateUtil.toMachineZero(this.origin);
    
    // Convert all box points to MachineZero
    const machineZeroBoxPoints: BoxPoints = {
      frontLeftLower: CoordinateUtil.toMachineZero(this.boxPoints.frontLeftLower),
      frontRightLower: CoordinateUtil.toMachineZero(this.boxPoints.frontRightLower),
      frontRightUpper: CoordinateUtil.toMachineZero(this.boxPoints.frontRightUpper),
      frontLeftUpper: CoordinateUtil.toMachineZero(this.boxPoints.frontLeftUpper),
      rearLeftLower: CoordinateUtil.toMachineZero(this.boxPoints.rearLeftLower),
      rearRightLower: CoordinateUtil.toMachineZero(this.boxPoints.rearRightLower),
      rearRightUpper: CoordinateUtil.toMachineZero(this.boxPoints.rearRightUpper),
      rearLeftUpper: CoordinateUtil.toMachineZero(this.boxPoints.rearLeftUpper)
    };
    
    return new Box(machineZeroOrigin, this.width, this.length, this.height, machineZeroBoxPoints);
  }
}
