/**
 * Base message structure from SignalR hub
 */
export interface CNCMessage {
    eventType: string;
    timestamp: string;
    data: any;
}

/**
 * DRO (Digital Read Out) event data
 * Contains real-time machine position information
 */
export interface DROEventData {
    timestamp: string;
    messageType: string;
    message: string;      // Human-readable position summary
    axis1: number;        // X axis position
    axis2: number;        // Y axis position  
    axis3: number;        // Z axis position
    axis4: number;        // A axis position (rotary)
    axis5: number;        // B axis position
    axis6: number;        // C axis position
    axis7: number;        // Additional axis
    axis8: number;        // Additional axis
}

export class DROEvent {
    public readonly messageType: string = 'DROEvent';
    public readonly timestamp: Date;
    public readonly data: DROEventData;

    constructor(message: CNCMessage) {
        this.timestamp = new Date(message.data.timestamp);
        this.data = message.data as DROEventData;
    }
}

/**
 * General message event from the CNC system
 */
export interface MessageEventData {
    timestamp: string;
    messageType: string;
    message: string;                // Error/status message text
    eventCode: number;              // Centroid error code (e.g., 306, 407)
    eventType: string;              // Classified message type
}

export class MessageEvent {
    public readonly messageType: string = 'MessageEvent';
    public readonly timestamp: Date;
    public readonly data: MessageEventData;

    constructor(message: CNCMessage) {
        this.timestamp = new Date(message.data.timestamp);
        this.data = message.data as MessageEventData;
    }
}

/**
 * Job information event
 */
export interface JobInfoEventData {
    timestamp: string;
    messageType: string;
    message: string;        // Job message text
    lineNumber: number;     // Current executing line number
    stackLevel: number;     // Stack level for nested programs
    jobName: string;        // Name of current job
}

export class JobInfoEvent {
    public readonly messageType: string = 'JobInfoEvent';
    public readonly timestamp: Date;
    public readonly data: JobInfoEventData;

    constructor(message: CNCMessage) {
        this.timestamp = new Date(message.data.timestamp);
        this.data = message.data as JobInfoEventData;
    }
}

/**
 * Job started event
 */
export interface JobStartedEventData {
    timestamp: string;
    messageType: string;
    message: string;        // Description
    jobId: string;          // Unique job identifier
    gCodeLines: string[];   // Array of G-code lines
    totalLines: number;     // Total lines in job
    isStepRunMode: boolean; // True if running step-by-step
    filePath?: string;      // File path if loaded from file
}

export class JobStartedEvent {
    public readonly messageType: string = 'JobStartedEvent';
    public readonly timestamp: Date;
    public readonly data: JobStartedEventData;

    constructor(message: CNCMessage) {
        this.timestamp = new Date(message.data.timestamp);
        this.data = message.data as JobStartedEventData;
    }
}

/**
 * Job completed event
 */
export interface JobCompletedEventData {
    timestamp: string;
    messageType: string;
    message: string;
    jobId: string;
    success: boolean;           // True if completed successfully
    errorMessage?: string;      // Error message if failed
    duration: string;           // ISO 8601 duration (e.g., "PT5M30S")
    linesExecuted: number;      // Number of lines executed
}

export class JobCompletedEvent {
    public readonly messageType: string = 'JobCompletedEvent';
    public readonly timestamp: Date;
    public readonly data: JobCompletedEventData;

    constructor(message: CNCMessage) {
        this.timestamp = new Date(message.data.timestamp);
        this.data = message.data as JobCompletedEventData;
    }
}

/**
 * Step execution event
 */
export interface StepExecutionEventData {
    timestamp: string;
    messageType: string;
    message: string;
    jobId: string;
    lineNumber: number;           // Current line (1-based)
    currentLine: string;          // G-code line text
    totalLines: number;           // Total number of lines in the job
    isLastStep: boolean;          // Whether this is the last step in the job
    status: string;               // Execution status
}

export class StepExecutionEvent {
    public readonly messageType: string = 'StepExecutionEvent';
    public readonly timestamp: Date;
    public readonly data: StepExecutionEventData;

    constructor(message: CNCMessage) {
        this.timestamp = new Date(message.data.timestamp);
        this.data = message.data as StepExecutionEventData;
    }
}

/**
 * Heartbeat event data
 * Sent periodically by server to indicate it's alive and provide status
 */
export interface HeartbeatEventData {
    timestamp: string;          // UTC timestamp (ISO 8601)
    serverTime: string;         // Local server time
    isConnected: boolean;       // True if server is connected to CNC
    status: string;             // "Connected" or "Disconnected"
    messageType: string;        // Always "Heartbeat"
    position: {
        x: number;              // X-axis position (machine units)
        y: number;              // Y-axis position (machine units)
        z: number;              // Z-axis position (machine units)
        a: number;              // A-axis rotary position (degrees)
    } | null;                   // null if disconnected or unavailable
}

export class HeartbeatEvent {
    public readonly messageType: string = 'Heartbeat';
    public readonly timestamp: Date;
    public readonly data: HeartbeatEventData;

    constructor(message: CNCMessage) {
        this.timestamp = new Date(message.data.timestamp || message.timestamp);
        this.data = message.data as HeartbeatEventData;
    }
}

/**
 * Union type for all event types
 */
export type SignalREvent =
    | DROEvent
    | MessageEvent
    | JobInfoEvent
    | JobStartedEvent
    | JobCompletedEvent
    | StepExecutionEvent
    | HeartbeatEvent;

/**
 * Type guard functions
 */
export function isDROEvent(event: SignalREvent): event is DROEvent {
    return event.messageType === 'DROEvent';
}

export function isMessageEvent(event: SignalREvent): event is MessageEvent {
    return event.messageType === 'MessageEvent';
}

export function isJobInfoEvent(event: SignalREvent): event is JobInfoEvent {
    return event.messageType === 'JobInfoEvent';
}

export function isJobStartedEvent(event: SignalREvent): event is JobStartedEvent {
    return event.messageType === 'JobStartedEvent';
}

export function isJobCompletedEvent(event: SignalREvent): event is JobCompletedEvent {
    return event.messageType === 'JobCompletedEvent';
}

export function isStepExecutionEvent(event: SignalREvent): event is StepExecutionEvent {
    return event.messageType === 'StepExecutionEvent';
}

export function isHeartbeatEvent(event: SignalREvent): event is HeartbeatEvent {
    return event.messageType === 'Heartbeat';
}
