import React, { useState } from 'react';
import { ConfigurationData } from '../../../data/ConfigurationData';
import {
  Typography,
  Box,
  Paper,
  Grid,
  TextField,
  Button,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions
} from '@mui/material';
import {
  Save as SaveIcon,
  Inventory as MaterialIcon
} from '@mui/icons-material';
import { MaterialLibrary, MaterialType, GrainDirection } from '../../../data/Common/MaterialLibrary';
import { Material } from '../../../data/Common/Material';
import { MachineStateData } from '../../../data/MachineStateData';
import { Job } from '../../../data/Job';
import { MaterialEditorForm } from '../MaterialEditorForm';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';

export interface MaterialStageProps {
  onMovingToNext?: () => void;
  getNextStepName?: () => string;
}

export const MaterialStage: React.FC<MaterialStageProps> = ({ onMovingToNext, getNextStepName } = {}) => {
  const [materialLibrary] = useState(() => MaterialLibrary.Instance);
  const machineState = MachineStateData.Instance;
  
  // Ensure machineState has a currentJob with material
  const ensureCurrentJobMaterial = () => {
    if (!machineState.currentJob) {
      machineState.currentJob = new Job();
    }
    if (!machineState.currentJob.material) {
      const defaultMaterial = new Material();
      defaultMaterial.name = "Job Material";
      defaultMaterial.type = MaterialType.Wood;
      defaultMaterial.xLength = 6;
      defaultMaterial.yLength = 8;
      defaultMaterial.height = 1.5;
      defaultMaterial.grainDirection = GrainDirection.X;
      defaultMaterial.materialColor = ConfigurationData.Instance.defaultMaterialColor;
      machineState.currentJob.material = defaultMaterial;
    }
  };
  
  // Ensure we have a material to work with
  ensureCurrentJobMaterial();

  const [saveDialog, setSaveDialog] = useState(false);
  const [libraryDialog, setLibraryDialog] = useState(false);

  const handleMaterialChange = (field: keyof Material, value: any) => {
    // Directly update the machine state material
    if (machineState.currentJob && machineState.currentJob.material) {
      // Update the material property directly
      (machineState.currentJob.material as any)[field] = value;
      
      // Notify StateManager that the machineState has changed
      StateManager.propertyChanged(machineState, 'currentJob');
    }
  };

  const handleSaveToLibrary = () => {
    if (machineState.currentJob && machineState.currentJob.material) {
      const materialToSave = machineState.currentJob.material.clone();
      materialToSave.name = machineState.currentJob.material.name || "Custom Material";
      
      materialLibrary.materials.push(materialToSave);
      setSaveDialog(false);
    }
  };

  const handleLoadFromLibrary = (material: Material) => {
    if (machineState.currentJob) {
      // Clone the library material and replace the current material
      const clonedMaterial = material.clone();
      machineState.currentJob.material = clonedMaterial;
      
      setLibraryDialog(false);
    }
  };

  const getMaterialTypeColor = (type: MaterialType) => {
    switch (type) {
      case MaterialType.Wood: return 'success';
      case MaterialType.Metal: return 'info';
      case MaterialType.Plastic: return 'warning';
      case MaterialType.Composite: return 'secondary';
      default: return 'default';
    }
  };

  return (
    <ObserveState
      listenTo={machineState}
      properties={['currentJob']}
      control={() => (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
          <Typography variant="h5" gutterBottom>
            Material Definition
          </Typography>
          
          <Typography variant="body1" color="text.secondary" paragraph>
            Define the material properties and positioning for your workpiece. You can save custom materials to your library for future use.
          </Typography>

          {/* Material Editor Form with integrated 3D viewer */}
          <MaterialEditorForm
            material={machineState.currentJob?.material || {
              name: "Default Material", 
              type: MaterialType.Wood,
              xLength: 12,
              yLength: 12,
              height: 2,
              grainDirection: GrainDirection.X,
              materialColor: ConfigurationData.Instance.defaultMaterialColor
            } as Material}
            onMaterialChange={handleMaterialChange}
            onSaveToLibrary={() => setSaveDialog(true)}
            onLoadFromLibrary={() => setLibraryDialog(true)}
          />

          {/* Save to Library Dialog */}
          <Dialog open={saveDialog} onClose={() => setSaveDialog(false)} maxWidth="sm" fullWidth>
            <DialogTitle>Save Material to Library</DialogTitle>
            <DialogContent>
              <Typography variant="body2" color="text.secondary" paragraph>
                Save this material configuration to your library for future use.
              </Typography>
              
              <TextField
                fullWidth
                label="Material Name"
                value={machineState.currentJob?.material?.name || ''}
                onChange={(e) => handleMaterialChange('name', e.target.value)}
                sx={{ mt: 2 }}
                placeholder="Enter a descriptive name for this material"
              />
              
              <Box sx={{ mt: 2, p: 2, backgroundColor: 'background.default', borderRadius: 1 }}>
                <Typography variant="body2" gutterBottom>
                  <strong>Material Summary:</strong>
                </Typography>
                <Typography variant="body2">
                  Type: {machineState.currentJob?.material?.type} | Size: {machineState.currentJob?.material?.xLength}" × {machineState.currentJob?.material?.yLength}" × {machineState.currentJob?.material?.height}"
                </Typography>
              </Box>
            </DialogContent>
            <DialogActions>
              <Button onClick={() => setSaveDialog(false)}>Cancel</Button>
              <Button variant="contained" onClick={handleSaveToLibrary} startIcon={<SaveIcon />}>
                Save to Library
              </Button>
            </DialogActions>
          </Dialog>

          {/* Load from Library Dialog */}
          <Dialog open={libraryDialog} onClose={() => setLibraryDialog(false)} maxWidth="md" fullWidth>
            <DialogTitle>Load Material from Library</DialogTitle>
            <DialogContent>
              <Typography variant="body2" color="text.secondary" paragraph>
                Select a material from your library to load its properties.
              </Typography>
              
              <Grid container spacing={2}>
                {materialLibrary.materials.map((material, index) => (
                  <Grid item xs={12} sm={6} key={index}>
                    <Paper 
                      sx={{ 
                        p: 2, 
                        cursor: 'pointer',
                        '&:hover': { borderColor: 'primary.light', borderWidth: 1, borderStyle: 'solid' }
                      }}
                      onClick={() => handleLoadFromLibrary(material)}
                    >
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                        <MaterialIcon sx={{ color: 'text.secondary' }} />
                        <Typography variant="subtitle2">
                          {material.name}
                        </Typography>
                      </Box>
                      
                      <Chip 
                        label={material.type} 
                        size="small" 
                        color={getMaterialTypeColor(material.type) as any}
                        sx={{ mb: 1 }}
                      />
                      
                      <Typography variant="body2" color="text.secondary">
                        {material.xLength}" × {material.yLength}" × {material.height}"
                      </Typography>
                      
                      <Box
                        sx={{
                          width: '100%',
                          height: 8,
                          backgroundColor: material.materialColor,
                          borderRadius: 1,
                          mt: 1,
                          border: `1px solid ${ConfigurationData.Instance.secondaryBorderColor}`
                        }}
                      />
                    </Paper>
                  </Grid>
                ))}

                {materialLibrary.materials.length === 0 && (
                  <Grid item xs={12}>
                    <Paper sx={{ p: 4, textAlign: 'center' }}>
                      <MaterialIcon sx={{ fontSize: 48, color: 'text.secondary', mb: 2 }} />
                      <Typography variant="h6" color="text.secondary" gutterBottom>
                        No Materials in Library
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Define and save materials to build your library.
                      </Typography>
                    </Paper>
                  </Grid>
                )}
              </Grid>
            </DialogContent>
            <DialogActions>
              <Button onClick={() => setLibraryDialog(false)}>Close</Button>
            </DialogActions>
          </Dialog>
        </Box>
      )}
    />
  );
};
