import { IStorable } from '../../common/IStorable';
import { Logger, LogCategory } from '../../utils/Logger';

/**
 * Abstract base class for all saveable data classes (libraries, configuration, etc.)
 * Provides common functionality for auto-save, manual save, and data persistence
 */
export abstract class SaveableDataBase implements IStorable {
  /**
   * Abstract property that must be implemented by derived classes
   * Returns the filename to use for saving/loading this data
   */
  protected abstract get filename(): string;

  /**
   * Setup auto-save functionality - listens to its own changes and schedules saves
   * Should be called by derived classes in their constructor after initialization
   */
  protected setupAutoSave(): void {
    // Use dynamic import to avoid circular dependencies
    import('../../utils/statemanager/StateManager').then(({ StateManager }) => {
      StateManager.addObserver(this, () => {
        // Use dynamic import to avoid circular dependencies
        import('../DataManager').then(({ DataManager }) => {
          const dataManager = DataManager.Instance;
          dataManager.scheduleAutoSaveForInstance(this);
        }).catch(error => {
          Logger.Instance.logError(LogCategory.System, `Failed to setup auto-save for ${this.constructor.name}:`, error);
        });
      }, [], `${this.constructor.name}-AutoSave`);
    }).catch(error => {
      Logger.Instance.logError(LogCategory.System, `Failed to setup auto-save for ${this.constructor.name}:`, error);
    });
  }

  /**
   * Manual save method that can be called from UI
   */
  public async manualSave(): Promise<void> {
    try {
      // Use dynamic import to avoid circular dependencies
      const { DataManager } = await import('../DataManager');
      await DataManager.Instance.saveDataInstance(this);
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, `Manual save failed for ${this.constructor.name}:`, error);
      throw error;
    }
  }

  /**
   * Load data from file
   */
  public async load(): Promise<void> {
    try {
      // Use dynamic import to avoid circular dependencies
      const { DataManager } = await import('../DataManager');
      await DataManager.Instance.fetch(this.filename, this);
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, `Load failed for ${this.constructor.name}:`, error);
      throw error;
    }
  }

  /**
   * Reset this instance to default values
   * Creates a new instance, exports current data to JSON, resets to defaults,
   * then triggers StateManager change notification
   */
  public async reset(): Promise<void> {
    try {
      // Use dynamic import to avoid circular dependencies
      const { StateManager } = await import('../../utils/statemanager/StateManager');
      
      // Create a new instance of the same class to get default values
      const constructor = Object.getPrototypeOf(this).constructor;
      const defaultInstance = Object.create(constructor.prototype);
      constructor.call(defaultInstance);
      
      // Get the default data from the new instance
      const defaultData = defaultInstance.toJSON();
      
      // Apply default data to this instance
      this.fromJSON(defaultData);
      
      // Notify StateManager of the reset
      StateManager.changed(this);
      
      //Logger.Instance.log(LogCategory.System, `✓ Reset ${this.constructor.name} to defaults`);
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, `Reset failed for ${this.constructor.name}:`, error);
      throw error;
    }
  }

  /**
   * Abstract methods that must be implemented by derived classes
   * These handle the specific serialization/deserialization logic for each data type
   */
  public abstract toJSON(): any;
  public abstract fromJSON(data: any): void;
}
