
export class FlowStepData {
    elements: (string | number | object)[] = [];
    private variables: Map<string, any> = new Map();

    // No-tool flag - when true, indicates no tool should be used
    public noTool: boolean = false;

    setVariable(name: string, value: any): void {
        this.variables.set(name, value);
    }

    getVariable(name: string): any {
        return this.variables.get(name);
    }

    // Get all data as a plain object for traversal
    getAllData(): any {
        const result: any = {};

        // Add elements if they exist
        if (this.elements.length > 0) {
            result.elements = this.elements;
        }

        // Add all variables
        this.variables.forEach((value, key) => {
            result[key] = value;
        });

        return result;
    }
}
