import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { IStorable } from '../../utils/storage/IStorable';

export class ExistsStepData implements IStorable {
    private _dataType: string = 'string'; // 'string', 'boolean', 'number', 'cncpoint'
    private _dataPath: string = '';

    // Data type selection
    get dataType(): string {
        return this._dataType;
    }

    set dataType(value: string) {
        this._dataType = value;
        StateManager.propertyChanged(this, 'dataType');
    }

    // Data element selection
    get dataPath(): string {
        return this._dataPath;
    }

    set dataPath(value: string) {
        this._dataPath = value;
        StateManager.propertyChanged(this, 'dataPath');
    }

    // Get allowed types for data selector
    getAllowedTypes(): string[] {
        return ['string', 'boolean', 'number', 'cncpoint'];
    }

    // Get the currently selected type as an array for the data selector
    getSelectedDataType(): string[] {
        return [this._dataType];
    }

    // IStorable implementation
    public toJSON(): any {
        return DataUtilities.getStorageData(this);
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}