import React, { useState } from 'react';
import {
  Typography,
  Box
} from '@mui/material';
import { ClampLibrary } from '../../../data/Common/ClampLibrary';
import { MachineStateData } from '../../../data/MachineStateData';
import { Job } from '../../../data/Job';
import { ClampEditorForm } from '../ClampEditorForm';
import { ObserveState } from '../../../utils/statemanager/ObserveState';

export interface ClampsStageProps {
  onMovingToNext?: () => void;
  getNextStepName?: () => string;
}

export const ClampsStage: React.FC<ClampsStageProps> = ({ onMovingToNext, getNextStepName } = {}) => {
  const [clampLibrary] = useState(() => ClampLibrary.Instance);
  const machineState = MachineStateData.Instance;

  // Ensure machineState has a currentJob
  const ensureCurrentJob = () => {
    if (!machineState.currentJob) {
      machineState.currentJob = new Job();
    }
  };

  ensureCurrentJob();

  const handleSaveToLibrary = () => {
    // Implementation for saving current clamps to library
    // //console.log('Save to library feature will be implemented');
  };

  const handleLoadFromLibrary = () => {
    // This is handled by the ClampEditorForm component
    // //console.log('Load from library handled by editor');
  };

  return (
    <ObserveState
      listenTo={[clampLibrary, machineState]}
      control={() => (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
          <Typography variant="h5" gutterBottom>
            Clamp Setup
          </Typography>
          
          <Typography variant="body1" color="text.secondary" paragraph>
            Position clamps to secure your material during machining. Use the top-view editor to place clamps precisely.
          </Typography>

          <Box sx={{ flex: 1, minHeight: 0 }}>
            <ClampEditorForm
              onSaveToLibrary={handleSaveToLibrary}
              onLoadFromLibrary={handleLoadFromLibrary}
              height="100%"
            />
          </Box>
        </Box>
      )}
    />
  );
};
