  // Default view configurations
  public defaultView: SimulatorView;
  public topWorkpieceView: SimulatorView;
  public compactView: SimulatorView;

  private constructor() {
    super();

    // Initialize default views
    this.defaultView = new SimulatorView();
    this.defaultView.workHome = true;
    this.defaultView.toolpaths = true;
    this.defaultView.softLimits = true;
    this.defaultView.gantry = ViewStyle.Show;
    this.defaultView.base = ViewStyle.Show;
    this.defaultView.spindle = ViewStyle.Show;
    this.defaultView.bed = ViewStyle.Show;
    this.defaultView.spoilBoard = ViewStyle.Show;
    this.defaultView.material = ViewStyle.Show;
    this.defaultView.tool = ViewStyle.Show;

    this.topWorkpieceView = new SimulatorView();
    this.topWorkpieceView.workHome = true;
    this.topWorkpieceView.toolpaths = true;
    this.topWorkpieceView.softLimits = true;
    this.topWorkpieceView.gantry = ViewStyle.SemiTransparent;
    this.topWorkpieceView.base = ViewStyle.Hide;
    this.topWorkpieceView.spindle = ViewStyle.Show;
    this.topWorkpieceView.bed = ViewStyle.Hide;
    this.topWorkpieceView.spoilBoard = ViewStyle.Show;
    this.topWorkpieceView.material = ViewStyle.Show;
    this.topWorkpieceView.tool = ViewStyle.Show;

    this.compactView = new SimulatorView();
    this.compactView.workHome = true;
    this.compactView.toolpaths = false;
    this.compactView.softLimits = false;
    this.compactView.gantry = ViewStyle.Hide;
    this.compactView.base = ViewStyle.Hide;
    this.compactView.spindle = ViewStyle.SemiTransparent;
    this.compactView.bed = ViewStyle.Hide;
    this.compactView.spoilBoard = ViewStyle.Show;
    this.compactView.material = ViewStyle.Show;
    this.compactView.tool = ViewStyle.Show;

    // Note: setupAutoSave() will be called after instance creation to avoid constructor issues
  }

  /**
   * IStorable implementation - serialize to JSON
   */
  public toJSON(): object {
    const baseData = DataUtilities.getStorageData(this, ['_instance', 'defaultView', 'topWorkpieceView', 'compactView', '_systemConfiguration']); // Exclude sub-objects from auto-processing

    // Handle sub-objects explicitly with proper serialization
    return {
      ...baseData,
      defaultView: this.defaultView.toJSON(),
      topWorkpieceView: this.topWorkpieceView.toJSON(),
      compactView: this.compactView.toJSON(),
      _systemConfiguration: this._systemConfiguration.toJSON()
    };
  }

  /**
   * IStorable implementation - deserialize from JSON
   */
  public fromJSON(data: any): void {
    if (!data) return;

    // Load basic properties automatically
    DataUtilities.loadStorageData(this, data, ['_instance', 'defaultView', 'topWorkpieceView', 'compactView', '_systemConfiguration']); // Exclude sub-objects from auto-processing

    // Handle sub-objects explicitly
    if (data.defaultView) {
      this.defaultView.fromJSON(data.defaultView);
    }
    if (data.topWorkpieceView) {
      this.topWorkpieceView.fromJSON(data.topWorkpieceView);
    }
    if (data.compactView) {
      this.compactView.fromJSON(data.compactView);
    }
    if (data._systemConfiguration) {
      this._systemConfiguration.fromJSON(data._systemConfiguration);
    }
  }

