import React from "react";
import { Button, Box } from "@mui/material";
import { WizardStep } from "./WizardStep";
import type { Wizard } from "./Wizard";
import { ConfigurationData } from "../../data/ConfigurationData";

export abstract class BaseWizardStep extends WizardStep {
    nextButtonText: string;
    backButtonText: string;

    constructor(
        wizard: Wizard,
        priorStep: WizardStep | null = null,
        nextButtonText: string = "Next",
        backButtonText: string = "Back"
    ) {
        super(wizard, priorStep);
        this.nextButtonText = nextButtonText;
        this.backButtonText = backButtonText;
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    abstract getTitle(): string;
    abstract nextStep(): WizardStep | null;
    abstract render(): React.ReactNode;

    handleNext(): void {
        // Handle navigation to next step - can be overridden by subclasses
        const next = this.nextStep();
        if (next === null) {
            // If next step is null, close the wizard
            this.closeWizard();
        } else {
            this.wizard.advanceToNextStep();
        }
    }

    handleBack(): void {
        // Handle navigation to previous step - can be overridden by subclasses
        this.wizard.goToPreviousStep();
    }

    closeWizard(): void {
        // Handle wizard close - can be overridden by subclasses or handled externally
        // This is called when nextStep() returns null or when close button is clicked
        this.wizard.closeWizard();
    }

    renderButtons(): React.ReactNode {
        const config = ConfigurationData.Instance;
        return (
            <Box sx={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center',
                marginTop: '20px',
                paddingTop: '20px',
                borderTop: `1px solid ${config.borderColor}`
            }}>
                {this.priorStep ? (
                    <Button
                        variant="text"
                        onClick={() => this.handleBack()}
                        sx={{ textDecoration: 'underline' }}
                    >
                        {this.backButtonText}
                    </Button>
                ) : (
                    <div />
                )}
                
                <Button
                    variant="contained"
                    color="primary"
                    onClick={() => this.handleNext()}
                >
                    {this.nextButtonText}
                </Button>
            </Box>
        );
    }

    // Default render implementation that includes content + buttons
    // Steps can override this if they need custom layout
    renderWithButtons(content: React.ReactNode): React.ReactNode {
        return (
            <div style={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
                <div style={{ 
                    flex: 1, 
                    minHeight: 0, // Important: allows flex child to shrink below content size
                    overflow: 'auto' // Enable scrolling only in content area
                }}>
                    {content}
                </div>
                <div style={{ flexShrink: 0 }}> {/* Prevent buttons from shrinking */}
                    {this.renderButtons()}
                </div>
            </div>
        );
    }
}
