import React, { useEffect, useState } from 'react';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { MachineStateData } from '../../../data/MachineStateData';
import { MachineData } from '../../../data/MachineData';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { Job } from '../../../data/Job';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import * as THREE from 'three';
import { GCodeParser } from '../../Views/Milling/gcode/GCodeParser';
import { ToolpathGeometry } from '../../Views/Milling/gcode/ToolpathGeometry';
import { SimpleColorizer } from '../../Views/Milling/gcode/SegmentColorizer';

export interface ToolpathsProps {
  simulatorView: SimulatorView;
  machineState: MachineStateData;
  machineData: MachineData;
  job?: Job; // Optional job - can be null, only use what's passed in
}

/**
 * Toolpaths component - renders G-code toolpaths in 3D space
 * Uses Three.js GCodeLoader to parse and visualize G-code
 * Renders based on current work home coordinates
 */
export function Toolpaths({
  simulatorView,
  machineState,
  machineData,
  job // Optional job override
}: ToolpathsProps) {
  const config = ConfigurationData.Instance;
  const [parsedGCode, setParsedGCode] = useState<THREE.Group | null>(null);

  // Parse G-code when job changes or toolpaths setting changes
  useEffect(() => {
    if (!job?.gcode || simulatorView.toolpaths === false) {
      setParsedGCode(null);
      return;
    }

    try {
      // Use our custom G-code parser
      const parser = new GCodeParser(new SimpleColorizer());
      const parseResult = parser.parse(job.gcode);
      
      if (parseResult.linePoints.length > 0) {
        // Create group for toolpath
        const toolpathGroup = new THREE.Group();

        // Create simple line geometry from line points
        const lineGeometry = new ToolpathGeometry();
        lineGeometry.addPoints(parseResult.linePoints);

        // Create line material with vertex colors
        const lineMaterial = new THREE.LineBasicMaterial({ 
          vertexColors: true,
          linewidth: 2
        });
        
        // Create line segments object
        const toolpathLines = new THREE.LineSegments(lineGeometry, lineMaterial);
        toolpathGroup.add(toolpathLines);

        setParsedGCode(toolpathGroup);
      } else {
        setParsedGCode(null);
      }
    } catch (error) {
      setParsedGCode(null);
    }
  }, [job?.gcode, simulatorView.toolpaths]);

  return (
    <ObserveMultiProperties
      listenTo={[
        { object: simulatorView, properties: ['toolpaths'] },
        { object: machineState, properties: ['currentWorkZero'] },
        { object: config, properties: ['primaryColor', 'secondaryColor'] }
      ]}
      control={() => {
        // Don't render if toolpaths are disabled or no G-code is available
        if (!simulatorView.toolpaths || !parsedGCode) {
          return null;
        }

        // Calculate work home offset directly - no caching
        let workHomeOffset: [number, number, number] = [0, 0, 0];
        if (machineState.currentWorkZero) {
          const workZeroSim = CoordinateUtil.toSimulator(machineState.currentWorkZero);
          workHomeOffset = [workZeroSim.x, workZeroSim.y, workZeroSim.z];
        }

        return (
          <group position={workHomeOffset}>
            <primitive 
              object={parsedGCode.clone()}
              scale={[1, 1, 1]}
            />
          </group>
        );
      }}
    />
  );
}
