import {
    Box,
    Button,
    ButtonGroup,
    Card,
    CardContent,
    Typography
} from '@mui/material';
import React from 'react';
import { FlowDataSelector } from '../../components/Common/FlowDataSelector';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { ValueSource } from '../FlowNumberValue';
import { FlowNumberValueEditor } from '../FlowNumberValueEditor';
import { FlowStep } from "../FlowStep";
import { FlowStepData } from "../FlowStepData";
import { ComparisonOperator, GreaterThanEqualToStepData } from './GreaterThanEqualToStepData';

export class GreaterThanEqualToStep extends FlowStep {
    readonly __type = 'GreaterThanEqualToStep';
    readonly category = ['Logic'];
    readonly name = 'Greater Than / Greater Than or Equal To';
    readonly description = 'Compares if left value is greater than or greater than or equal to right value';

    // StateManager-based step data
    public stepData: GreaterThanEqualToStepData = new GreaterThanEqualToStepData();

    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        const symbol = this.stepData.comparisonOperator === ComparisonOperator.GreaterThan ? '>' : '≥';
        return React.createElement('span', { style: { fontSize: '0.75rem', color: 'primary.main' } }, symbol);
    }

    // Static path constants
    static readonly YES_PATH = 'yes';
    static readonly NO_PATH = 'no';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            // Simulate comparison result for testing
            return Math.random() > 0.5 ? GreaterThanEqualToStep.YES_PATH : GreaterThanEqualToStep.NO_PATH;
        }

        try {
            // Get left value from data
            const leftValue = this.getValueFromData(data, this.stepData.leftDataPath);
            if (leftValue === undefined) {
                console.error('Left data path not found:', this.stepData.leftDataPath);
                return GreaterThanEqualToStep.NO_PATH;
            }

            // Get right value (either from data or direct value)
            let rightValue: any;
            if (this.stepData.rightValue.valueSource === ValueSource.DataElement) {
                rightValue = this.getValueFromData(data, this.stepData.rightValue.dataPath);
                if (rightValue === undefined) {
                    console.error('Right data path not found:', this.stepData.rightValue.dataPath);
                    return GreaterThanEqualToStep.NO_PATH;
                }
            } else {
                rightValue = this.stepData.rightValue.numberValue;
            }

            // Convert to numbers for comparison
            const leftNum = Number(leftValue);
            const rightNum = Number(rightValue);

            // Check if conversion was successful
            if (isNaN(leftNum) || isNaN(rightNum)) {
                console.error('GreaterThanEqualToStep: Cannot compare non-numeric values');
                return GreaterThanEqualToStep.NO_PATH;
            }

            // Perform comparison based on operator
            const result = this.stepData.comparisonOperator === ComparisonOperator.GreaterThan
                ? leftNum > rightNum
                : leftNum >= rightNum;

            const operatorSymbol = this.stepData.comparisonOperator === ComparisonOperator.GreaterThan ? '>' : '>=';
            console.log(`GreaterThanEqualToStep: ${leftNum} ${operatorSymbol} ${rightNum} = ${result}`);

            return result ? GreaterThanEqualToStep.YES_PATH : GreaterThanEqualToStep.NO_PATH;

        } catch (error) {
            console.error('GreaterThanEqualToStep execution error:', error);
            return GreaterThanEqualToStep.NO_PATH;
        }
    }

    private getValueFromData(data: FlowStepData, path: string): any {
        if (!path) return undefined;

        const allData = data.getAllData();
        const pathParts = path.split('.');

        let current = allData;
        for (const part of pathParts) {
            if (current && typeof current === 'object' && part in current) {
                current = current[part];
            } else {
                return undefined;
            }
        }

        return current;
    }

    results(): string[] {
        return [GreaterThanEqualToStep.YES_PATH, GreaterThanEqualToStep.NO_PATH];
    }

    renderResultsUI(): React.ReactNode {
        const operatorText = this.stepData.comparisonOperator === ComparisonOperator.GreaterThan ? 'greater than' : 'greater than or equal to';
        const rightDisplay = this.stepData.rightValue.valueSource === ValueSource.DataElement
            ? this.stepData.rightValue.dataPath
            : this.stepData.rightValue.numberValue;
        const result = this.stepData.leftDataPath
            ? `${this.stepData.leftDataPath} ${operatorText} ${rightDisplay}`
            : 'Not configured';

        return (
            <Typography variant="caption">
                {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void, flow: any, flowStep?: any }): React.ReactNode {
        // Extract flow from props - we'll use 'this' as the flowStep
        const { flow } = props;

        return (
            <ObserveState
                key="greater-than-equal-to-step-edit-ui"
                listenTo={this.stepData}
                properties={['leftDataPath', 'comparisonOperator']}
                control={() => (
                    <Box sx={{ minWidth: 500 }}>
                        <Box sx={{ p: 2, minWidth: 400 }}>
                            <Typography variant="h6" gutterBottom>
                                Greater Than / Greater Than or Equal To Configuration
                            </Typography>

                            {/* Left Data Element Selector */}
                            <Card variant="outlined" sx={{ mt: 3 }}>
                                <CardContent>
                                    <FlowDataSelector
                                        flow={flow}
                                        flowStep={this}
                                        allowedTypes={['number']}
                                        currentSelection={this.stepData.leftDataPath ? [this.stepData.leftDataPath] : []}
                                        onChange={(paths) => {
                                            this.stepData.leftDataPath = paths.length > 0 ? paths[0] : '';
                                        }}
                                        label="Left Value (Data Element)"
                                    />
                                </CardContent>
                            </Card>

                            {/* Visual Separator with Comparison Operator Selection */}
                            <Box sx={{
                                mt: 2,
                                mb: 2,
                                textAlign: 'center',
                                py: 2,
                                borderTop: '3px solid',
                                borderBottom: '3px solid',
                                borderColor: 'primary.main',
                                backgroundColor: 'grey.50'
                            }}>
                                <ButtonGroup fullWidth variant="outlined" sx={{ mb: 1, maxWidth: 600, mx: 'auto' }}>
                                    <Button
                                        variant={this.stepData.comparisonOperator === ComparisonOperator.GreaterThan ? 'contained' : 'outlined'}
                                        onClick={() => {
                                            this.stepData.comparisonOperator = ComparisonOperator.GreaterThan;
                                        }}
                                    >
                                        Greater Than
                                    </Button>
                                    <Button
                                        variant={this.stepData.comparisonOperator === ComparisonOperator.GreaterThanOrEqualTo ? 'contained' : 'outlined'}
                                        onClick={() => {
                                            this.stepData.comparisonOperator = ComparisonOperator.GreaterThanOrEqualTo;
                                        }}
                                    >
                                        Greater Than or Equal To
                                    </Button>
                                </ButtonGroup>
                            </Box>

                            {/* Right Value Section with FlowNumberValueEditor */}
                            <FlowNumberValueEditor
                                numberValue={this.stepData.rightValue}
                                flow={flow}
                                flowStep={this}
                                label="Right Value"
                            />
                        </Box>
                    </Box>
                )}
            />
        );
    }

    // Serialization
    public toJSON(): any {
        const baseData = DataUtilities.getStorageData(this, ['stepData']);
        return {
            ...baseData,
            __type: this.__type,
            stepData: this.stepData.toJSON()
        };
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['stepData']);
        if (data.stepData) {
            this.stepData.fromJSON(data.stepData);
        }
    }
}