import { Box, Button, LinearProgress, Typography } from '@mui/material';
import React from "react";
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { Job } from '../../../../data/Job';
import { MachineData } from '../../../../data/MachineData';
import { MachineStateData } from '../../../../data/MachineStateData';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { Machine } from '../../../../machine/Machine';
import { CoordinateUtil } from '../../../../utils/CoordinateUtil';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { CNCViewType } from '../../../MachineViewer/CNCViewer';
import { FullSizeCNCViewer } from '../../../MachineViewer/FullSizeCNCViewer';
import { BaseWizardStep } from "../../../Wizard/BaseWizardStep";
import { Wizard } from "../../../Wizard/Wizard";
import { WizardStep } from "../../../Wizard/WizardStep";
import { createCalibrationSimulatorView } from '../common/utils';

export class TouchplateProgressStep extends BaseWizardStep {
  constructor(wizard: Wizard, priorStep: WizardStep | null = null) {
    super(wizard, priorStep, "", "Stop");
    this.nextButtonText = ""; // Hide next button during progress
  }

  getTitle(): string {
    return "Touch Off In Progress";
  }

  nextStep(): WizardStep | null {
    const { ResultsStep } = require('./ResultsStep');
    return new ResultsStep(this.wizard, this);
  }

  handleBack(): void {
    // Emergency stop button - cancel touchoff operation
    this.wizard.state.isProcessing = false;

    // Call machine stop
    Machine.getInstance().program.Stop().then(() => {
      UserMessageQueue.Instance.addMessage('⏸ Touch-off operation stopped');
    }).catch((error: any) => {
      console.error('Failed to stop machine:', error);
      UserMessageQueue.Instance.addMessage('❌ Failed to stop touch-off operation');
    });

    // //console.log('Emergency stop activated - touchoff operation cancelled');
    // Stay on this step but stop processing
  }

  componentDidMount(): void {
    // Start the touchoff process
    this.performTouchOff();
  }

  private async performTouchOff(): Promise<void> {
    try {
      this.wizard.state.isProcessing = true;
      UserMessageQueue.Instance.addMessage('🔍 Starting touch-off sequence...');

      // Call the actual machine TouchOff method
      await Machine.getInstance().features.TouchOff();

      // Touch-off completed successfully
      this.wizard.state.isProcessing = false;
      this.wizard.state.finalZPosition = MachineStateData.Instance.currentMachinePoint.z;

      UserMessageQueue.Instance.addMessage('✅ Touch-off completed successfully');

      // Small delay before advancing to results
      setTimeout(() => {
        this.handleNext();
      }, 1000);

    } catch (error) {
      this.wizard.state.isProcessing = false;
      UserMessageQueue.Instance.addMessage('❌ Touch-off operation failed');
      console.error('TouchOff failed:', error);
      // Stay on this step to allow retry or cancellation
    }
  }

  render(): React.ReactNode {
    // Start the process when this step is rendered
    if (!this.wizard.state.processStarted) {
      this.wizard.state.processStarted = true;
      this.componentDidMount();
    }

    return (
      <div style={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
        <div style={{ flex: 1 }}>
          <ObserveState
            listenTo={MachineStateData.Instance}
            properties={['currentMachinePoint', 'materialTopZ']}
            control={() => {
              const machineState = MachineStateData.Instance;
              const currentZ = machineState.currentMachinePoint.z;
              const distanceToSpoilboard = CoordinateUtil.distanceToSpoilboard();
              const distanceToBed = CoordinateUtil.distanceToBed();
              const distanceToMaterial = CoordinateUtil.distanceToMaterial();
              const calibrationSimulatorView = createCalibrationSimulatorView();

              return (
                <Box sx={{ display: 'flex', height: '100%' }}>
                  <Box sx={{ flex: 1, pr: 3, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
                    <Typography variant="h6" sx={{ mb: 3 }}>
                      {this.wizard.state.isProcessing ? 'Touch-Off in Progress...' : 'Touch-Off Complete'}
                    </Typography>
                    {this.wizard.state.isProcessing && <LinearProgress sx={{ mb: 3 }} />}
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                      {this.wizard.state.isProcessing
                        ? 'The spindle is moving down in 0.1" increments until contact is detected, then moving up 2" for clearance.'
                        : 'Touch-off operation completed successfully.'
                      }
                    </Typography>

                    {/* Emergency Stop Button - only show during processing */}
                    {this.wizard.state.isProcessing && (
                      <Box sx={{ display: 'flex', justifyContent: 'center', mb: 4 }}>
                        <Button
                          variant="contained"
                          color="error"
                          onClick={() => this.handleBack()}
                          sx={{ px: 4, py: 2 }}
                        >
                          EMERGENCY STOP
                        </Button>
                      </Box>
                    )}

                    {/* Status Information */}
                    <Box sx={{ backgroundColor: ConfigurationData.Instance.lightBackgroundColor, p: 2, borderRadius: 1 }}>
                      <Typography variant="subtitle2" sx={{ mb: 1 }}>
                        Current Position:
                      </Typography>
                      <Typography variant="body2" sx={{ mb: 1 }}>
                        Z: {currentZ.toFixed(3)}" (machine coordinates)
                      </Typography>
                      <Typography variant="body2" sx={{ mb: 1 }}>
                        Distance to spoilboard: {distanceToSpoilboard.toFixed(3)}"
                      </Typography>
                      <Typography variant="body2" sx={{ mb: 1 }}>
                        Distance to bed: {distanceToBed.toFixed(3)}"
                      </Typography>
                      <Typography variant="body2">
                        Distance to material: {distanceToMaterial.toFixed(3)}"
                      </Typography>
                    </Box>
                  </Box>

                  <Box sx={{ flex: 1, minHeight: 0 }}>
                    <FullSizeCNCViewer
                      enableOrbit={false}
                      enableClampDragging={false}
                      enableSpindleDrag={false}
                      viewType={CNCViewType.ZAxisCalibration}
                      zAxisReferenceType={this.wizard.state.referenceType}
                      simulatorView={calibrationSimulatorView}
                      machineState={MachineStateData.Instance}
                      machineData={MachineData.Instance}
                      job={MachineStateData.Instance.currentJob || Job.createTestJob()}
                    />
                  </Box>
                </Box>
              );
            }}
          />
        </div>
        {this.renderButtons()}
      </div>
    );
  }
}
