
import { StateManager } from '../statemanager/StateManager';
import { ReactNode } from 'react';
import { NotificationList } from '../NotificationList';

export class ActionBus {
    // Singleton instance
    private static _instance: ActionBus;
    
    // List of pending actions
    private _actions: IAction[] = [];
    
    // singleton instance getter
    public static get Instance(): ActionBus {
        if (!ActionBus._instance) {
            ActionBus._instance = new ActionBus();
        }
        return ActionBus._instance;
    }

    /**
     * Add an action to the queue. If it can be combined with an existing action, 
     * combine them and replace the existing action.
     */
    public addAction(action: IAction): void {
        // Look for an existing action that can be combined with this one
        for (let i = 0; i < this._actions.length; i++) {
            const existingAction = this._actions[i];
            
            // Check if this action can be combined with the existing one
            if (action.canCombine(existingAction)) {
                // Combine the old action into the new one and replace the existing one
                const combinedAction = existingAction.combineWith(action);
                this._actions[i] = combinedAction;
                
                // Execute the combined action
                if ('execute' in combinedAction && typeof combinedAction.execute === 'function') {
                    (combinedAction as any).execute();
                }
                
                // Notify that actions have changed
                StateManager.propertyChanged(this, 'actions');
                // Update notification list
                this.updateNotifications();
                return; // Exit early since we've combined and replaced
            }
        }
        
        // If no combination was possible, add the new action to the list
        this._actions.push(action);
        
        // Check for single action constraint violations AFTER adding/combining
        const actionsByType = new Map<string, IAction[]>();
        for (const a of this._actions) {
            if (!actionsByType.has(a.type)) {
                actionsByType.set(a.type, []);
            }
            actionsByType.get(a.type)!.push(a);
        }
        
        // Check if any single action type has multiple instances
        for (const [type, actions] of actionsByType) {
            if (actions.length > 1 && actions.some(a => a.singleAction)) {
                throw new Error(`Multiple instances of single action type '${type}' found in queue. Only one instance is allowed at a time.`);
            }
        }
        
        // Execute the new action
        if ('execute' in action && typeof action.execute === 'function') {
            (action as any).execute();
        }
        
        // Notify that actions have changed
        StateManager.propertyChanged(this, 'actions');
        
        // Update notification list
        this.updateNotifications();
    }

    /**
     * Update the NotificationList with current action UIs
     */
    private updateNotifications(): void {
        // Clear existing action notifications (those with ordinal 0)
        const existingNotifications = NotificationList.Instance.notifications;
        existingNotifications.forEach(notification => {
            if (notification.ordinal === 0) { // Action UI uses ordinal 0
                NotificationList.Instance.remove(notification.id);
            }
        });
        
        // Add current actions as notifications
        this._actions.forEach((action) => {
            const ui = action.renderUI();
            if (ui) {
                const startTime = ('_startTime' in action) ? (action as any)._startTime : Date.now();
                const notificationId = `action_${action.id}_${startTime}`;
                
                // Add to notification list with ordinal 0 (lower than user messages)
                NotificationList.Instance.add(notificationId, ui, 0);
            }
        });
    }

    /**
     * Complete (remove) an action from the queue
     */
    public completeAction(action: IAction): boolean {
        const index = this._actions.indexOf(action);
        if (index > -1) {
            this._actions.splice(index, 1);
            // Notify that actions have changed
            StateManager.propertyChanged(this, 'actions');
            // Update notification list
            this.updateNotifications();
            return true; // Successfully removed
        }
        return false; // Action not found
    }

    /**
     * Complete (remove) the first action from the queue
     */
    public completeFirstAction(): IAction | null {
        if (this._actions.length > 0) {
            const action = this._actions.shift() || null;
            // Notify that actions have changed
            StateManager.propertyChanged(this, 'actions');
            // Update notification list
            this.updateNotifications();
            return action;
        }
        return null; // No actions to complete
    }

    /**
     * Get a copy of all pending actions
     */
    public getActions(): IAction[] {
        return [...this._actions]; // Return a copy to prevent external modification
    }

    /**
     * Clear all pending actions
     */
    public clearActions(): void {
        this._actions = [];
        // Notify that actions have changed
        StateManager.propertyChanged(this, 'actions');
    }

    /**
     * Force cleanup of completed actions (safety measure)
     */
    public forceCleanup(): void {
        // Remove any actions that might have completed but weren't properly removed
        const initialCount = this._actions.length;
        this._actions = this._actions.filter(action => {
            // Keep actions that have a timeout or are actively running
            if ('_timeoutId' in action && (action as any)._timeoutId) {
                return true;
            }
            // Remove actions without timeouts (likely completed)
            return false;
        });
        
        if (this._actions.length !== initialCount) {
            // Notify that actions have changed
            StateManager.propertyChanged(this, 'actions');
        }
    }

    /**
     * Get the number of pending actions
     */
    public get actionCount(): number {
        return this._actions.length;
    }
}

// interface for proposed actions
export interface IAction {
    type: string; // Action type
    id: string; // Unique identifier for this action instance
    singleAction?: boolean; // Whether only one instance of this action type can exist in the queue
    canCombine(other: IAction): boolean; // Whether this action can be combined with others
    combineWith(other: IAction): IAction; // Combine with another action
    renderUI(): ReactNode | null; // Render UI for this action (can be null for no UI)
    cancel?(): void; // Optional cancel method for actions that can be cancelled
}

