import React from 'react';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { MachineData } from '../../../data/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { Box } from './Box';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';

export interface GantryProps {
  simulatorView: SimulatorView;
  machineData: MachineData;
  machineState: MachineStateData;
}

export function Gantry({
  simulatorView,
  machineData,
  machineState
}: GantryProps) {
  // Get configuration colors and state
  const config = ConfigurationData.Instance;
  const configState = ConfigurationState.Instance;
  
  return (
    <ObserveMultiProperties
      listenTo={[
        { object: simulatorView, properties: ['gantry'] },
        { object: machineState, properties: ['currentMachinePoint', 'proposedSpindlePosition'] },
        { object: configState, properties: ['isSpindleDragging'] },
        { object: config, properties: ['gantryTransparency', 'gantryColor'] }
      ]}
      control={() => {
        // Calculate opacity once for reuse on all gantry elements
        const gantryOpacity = (machineState.proposedSpindlePosition || configState.isSpindleDragging)
          ? config.gantryTransparency  // Use base transparency when proposed position exists or spindle is selected
          : (simulatorView.gantry === ViewStyle.SemiTransparent ? config.gantryTransparency : 1);

        // Create unique key based on viewStyle and opacity for React re-rendering
        const baseKey = `gantry-${ViewStyle[simulatorView.gantry]}-${gantryOpacity}-${Date.now()}`;

        // Get current spindle position and convert to simulator coordinates
        // Use proposedSpindlePosition if it exists (during drag), otherwise use currentMachinePoint
        const currentPosition = machineState.proposedSpindlePosition || machineState.currentMachinePoint;
        const simulatorPosition = CoordinateUtil.toSimulator(currentPosition);
        
        // Calculate gantry Y position: spindle Y position + spindle offset (matches C# implementation)
        // The offset should position the FRONT of the gantry beam, not the center
        // So we need to add half the gantry beam width to position the center correctly
        const currentGantryPosition = simulatorPosition.y + machineData.spindleOffset + (machineData.gantryBarWidth / 2);

        const gantryHeight = machineData.gantryHeight;
        const gantryBarHeight = machineData.gantryBarHeight;
        const gantryBarWidth = machineData.gantryBarWidth;
        const bedHeight = machineData.bedHeight;
        const baseHeight = machineData.baseHeight;
        const baseWidth = machineData.baseWidth;
        const gantrySupportWidth = machineData.gantrySupportWidth;
        const railingWidth = machineData.railingWidth;
        
        // Calculate adjustment like in C# code
        const adjustment = machineData.railingOutsideBed ? 2 : 0;
        
        // Calculate gantry bar width exactly as in C# code
        const gantryBarWidthCalculated = baseWidth + (2 * gantrySupportWidth) + (2 * adjustment);

        // Position gantry components in simulator coordinates - following C# implementation exactly
        // Gantry bar position matches C# X calculation: 0 - GantrySupportWidth - adjustment
        const gantryBarPosition = CoordinateUtil.toSimulator(
          new CNCPoint(
            0 - gantrySupportWidth - adjustment + gantryBarWidthCalculated / 2, 
            currentGantryPosition, 
            baseHeight + bedHeight + gantryHeight, 
            CoordinateType.Simulator
          )
        );

        // Left support position matches C# calculation
        const leftSupportPosition = CoordinateUtil.toSimulator(
          new CNCPoint(
            0 - gantrySupportWidth - adjustment + railingWidth + gantrySupportWidth / 2, 
            currentGantryPosition, 
            baseHeight + (bedHeight + gantryHeight) / 2, 
            CoordinateType.Simulator
          )
        );

        // Right support position matches C# calculation
        const rightSupportPosition = CoordinateUtil.toSimulator(
          new CNCPoint(
            baseWidth - adjustment + gantrySupportWidth / 2, 
            currentGantryPosition, 
            baseHeight + (bedHeight + gantryHeight) / 2, 
            CoordinateType.Simulator
          )
        );

        return (
          <group key={baseKey}>
            {/* Main gantry bar (horizontal) - width calculated exactly as in C# */}
            <Box
              position={[gantryBarPosition.x, gantryBarPosition.y, gantryBarPosition.z]}
              size={[gantryBarWidthCalculated, gantryBarWidth, gantryBarHeight]}
              color={config.gantryColor}
              viewStyle={simulatorView.gantry}
              opacity={gantryOpacity}
            />
            
            {/* Left support - size matches C# GantrySupportWidth */}
            <Box
              position={[leftSupportPosition.x, leftSupportPosition.y, leftSupportPosition.z]}
              size={[gantrySupportWidth, gantryBarWidth, bedHeight + gantryHeight]}
              color={config.gantryColor}
              viewStyle={simulatorView.gantry}
              opacity={gantryOpacity}
            />
            
            {/* Right support - size matches C# GantrySupportWidth */}
            <Box
              position={[rightSupportPosition.x, rightSupportPosition.y, rightSupportPosition.z]}
              size={[gantrySupportWidth, gantryBarWidth, bedHeight + gantryHeight]}
              color={config.gantryColor}
              viewStyle={simulatorView.gantry}
              opacity={gantryOpacity}
            />
          </group>
        );
      }}
    />
  );
};
