import React from 'react';
import { GCodePreviewDialog } from '../components/Common/GCodePreviewDialog';
import { ModalManager } from './ModalManager';

/**
 * Global G-code preview dialog manager using the ModalManager system
 * Provides a consistent way to preview and save G-code before execution
 */
export class GCodePreviewManager {
    private static _instance: GCodePreviewManager;

    public static get Instance(): GCodePreviewManager {
        if (!GCodePreviewManager._instance) {
            GCodePreviewManager._instance = new GCodePreviewManager();
        }
        return GCodePreviewManager._instance;
    }

    private constructor() { }

    /**
     * Show a G-code preview dialog
     * @param title Dialog title
     * @param gcode Array of G-code lines to preview
     * @returns Promise that resolves to true if user clicked Run, false if cancelled
     */
    public showPreview(title: string, gcode: string[]): Promise<boolean> {
        return new Promise<boolean>((resolve) => {
            const modalId = `gcode-preview-${Date.now()}`;

            const handleRun = () => {
                ModalManager.Instance.closeModal(modalId);
                resolve(true);
            };

            const handleCancel = () => {
                ModalManager.Instance.closeModal(modalId);
                resolve(false);
            };

            const modal = {
                id: modalId,
                render: () => React.createElement(GCodePreviewDialog, {
                    open: true,
                    title,
                    gcode,
                    onRun: handleRun,
                    onCancel: handleCancel
                })
            };

            ModalManager.Instance.showModal(modal);
        });
    }
}
