import {
    Add as AddIcon,
    Delete as DeleteIcon,
    Download,
    Restore as RestoreIcon,
    Save as SaveIcon,
    Upload
} from '@mui/icons-material';
import {
    Box,
    Button,
    Chip,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    Paper,
    Stack,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    TextField,
    Typography
} from '@mui/material';
import React, { useEffect, useState } from 'react';
import { ClampLibrary } from '../../../data/Common/ClampLibrary';
import { FixtureHistoryLibrary } from '../../../data/Common/FixtureHistoryLibrary';
import { FixtureLibrary } from '../../../data/Common/FixtureLibrary';
import { MaterialLibrary } from '../../../data/Common/MaterialLibrary';
import { ToolLibrary } from '../../../data/Common/ToolLibrary';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { MachineData } from '../../../data/MachineData';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import type { CheckpointInfo } from '../../../machine/Machine';
import { Machine } from '../../../machine/Machine';
import { ConfirmDialogManager } from '../../../utils/ConfirmDialogManager';
import { LogCategory, Logger } from '../../../utils/Logger';

interface CheckpointDialogProps {
    open: boolean;
    onClose: () => void;
    onSave: (name: string, description: string) => void;
}

const CheckpointDialog: React.FC<CheckpointDialogProps> = ({ open, onClose, onSave }) => {
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');

    const handleSave = () => {
        if (!name.trim()) {
            UserMessageQueue.Instance.addMessage('⚠ Checkpoint name is required');
            return;
        }
        onSave(name.trim(), description.trim());
        setName('');
        setDescription('');
        onClose();
    };

    const handleClose = () => {
        setName('');
        setDescription('');
        onClose();
    };

    return (
        <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
            <DialogTitle>Create Configuration Checkpoint</DialogTitle>
            <DialogContent>
                <Box sx={{ mt: 2, display: 'flex', flexDirection: 'column', gap: 2 }}>
                    <TextField
                        fullWidth
                        label="Checkpoint Name"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        placeholder="e.g., Before Tool Change"
                        autoFocus
                    />
                    <TextField
                        fullWidth
                        label="Description (Optional)"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        placeholder="e.g., Baseline configuration with all tools calibrated"
                        multiline
                        rows={3}
                    />
                </Box>
            </DialogContent>
            <DialogActions sx={{ p: 2, pt: 1 }}>
                <Button onClick={handleClose}>Cancel</Button>
                <Button
                    variant="contained"
                    onClick={handleSave}
                    startIcon={<SaveIcon />}
                >
                    Save Checkpoint
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export function ConfigCheckpointsTab() {
    const [checkpoints, setCheckpoints] = useState<CheckpointInfo[]>([]);
    const [dialogOpen, setDialogOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const config = ConfigurationData.Instance;

    const loadCheckpoints = async () => {
        try {
            const machine = Machine.getInstance();
            const data = await machine.setup.ListCheckpoints();
            setCheckpoints(data);
        } catch (error) {
            console.error('Failed to load checkpoints:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to load checkpoints');
        }
    };

    useEffect(() => {
        loadCheckpoints();
    }, []);

    const handleDownloadConfiguration = async () => {
        try {
            // Get program storage data
            const machine = Machine.getInstance();
            let programStorageData = null;
            try {
                programStorageData = await machine.storage?.exportAllAsJson?.() || null;
            } catch (storageError) {
                Logger.Instance.logError(LogCategory.System, 'Warning: Failed to export program storage:', storageError);
                // Continue with export without program storage
            }

            // Create comprehensive configuration export including all data
            const configData = {
                machineData: MachineData.Instance.toJSON(),
                configurationData: ConfigurationData.Instance.toJSON(),
                fixtureLibrary: FixtureLibrary.Instance.toJSON(),
                fixtureHistory: FixtureHistoryLibrary.Instance.toJSON(),
                materialLibrary: MaterialLibrary.Instance.toJSON(),
                toolLibrary: ToolLibrary.Instance.toJSON(),
                clampLibrary: ClampLibrary.Instance.toJSON(),
                programStorage: programStorageData,
                exportDate: new Date().toISOString(),
                version: '1.1'
            };

            const dataStr = JSON.stringify(configData, null, 2);
            const dataBlob = new Blob([dataStr], { type: 'application/json' });
            const url = URL.createObjectURL(dataBlob);

            const link = document.createElement('a');
            link.href = url;
            link.download = `havencnc-config-${new Date().toISOString().split('T')[0]}.json`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            URL.revokeObjectURL(url);

            UserMessageQueue.Instance.addMessage('✓ Configuration exported successfully (including program storage)');
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Error exporting configuration:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to export configuration');
        }
    };

    const handleUploadConfiguration = () => {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = '.json';

        input.onchange = (event) => {
            const file = (event.target as HTMLInputElement).files?.[0];
            if (!file) return;

            const reader = new FileReader();
            reader.onload = async (e) => {
                try {
                    const configData = JSON.parse(e.target?.result as string);

                    // Restore all data using fromJSON methods
                    if (configData.machineData) {
                        MachineData.Instance.fromJSON(configData.machineData);
                    }
                    if (configData.configurationData) {
                        ConfigurationData.Instance.fromJSON(configData.configurationData);
                    }
                    if (configData.fixtureLibrary) {
                        FixtureLibrary.Instance.fromJSON(configData.fixtureLibrary);
                    }
                    if (configData.fixtureHistory) {
                        FixtureHistoryLibrary.Instance.fromJSON(configData.fixtureHistory);
                    }
                    if (configData.materialLibrary) {
                        MaterialLibrary.Instance.fromJSON(configData.materialLibrary);
                    }
                    if (configData.toolLibrary) {
                        ToolLibrary.Instance.fromJSON(configData.toolLibrary);
                    }
                    if (configData.clampLibrary) {
                        ClampLibrary.Instance.fromJSON(configData.clampLibrary);
                    }
                    if (configData.programStorage) {
                        // Import program storage data if available
                        try {
                            const machine = Machine.getInstance();
                            if (machine.storage?.importFromJson) {
                                await machine.storage.importFromJson(configData.programStorage);
                            }
                        } catch (storageError) {
                            Logger.Instance.logError(LogCategory.System, 'Warning: Failed to import program storage:', storageError);
                            // Continue with other imports
                        }
                    }

                    UserMessageQueue.Instance.addMessage('✓ Configuration imported successfully (including program storage)');
                } catch (error) {
                    Logger.Instance.logError(LogCategory.System, 'Error importing configuration:', error);
                    UserMessageQueue.Instance.addMessage('❌ Failed to import configuration - invalid file format');
                }
            };
            reader.readAsText(file);
        };

        input.click();
    };

    const handleCreateCheckpoint = async (name: string, description: string) => {
        try {
            setLoading(true);
            const machine = Machine.getInstance();
            await machine.setup.SaveCheckpoint({ checkpointName: name });
            await loadCheckpoints();
        } catch (error) {
            console.error('Failed to create checkpoint:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to create checkpoint');
        } finally {
            setLoading(false);
        }
    };

    const handleRestoreCheckpoint = async (checkpointName: string) => {
        const confirmed = await ConfirmDialogManager.Instance.showConfirm({
            title: 'Restore Checkpoint',
            message: `Are you sure you want to restore checkpoint "${checkpointName}"? This will replace all current configuration data.`,
            confirmText: 'Restore',
            severity: 'warning'
        });

        if (!confirmed) return;

        try {
            setLoading(true);
            const machine = Machine.getInstance();
            const count = await machine.setup.RestoreCheckpoint(checkpointName);
            UserMessageQueue.Instance.addMessage(`✓ Restored ${count} configuration files from "${checkpointName}"`);
            await loadCheckpoints();
        } catch (error) {
            console.error('Failed to restore checkpoint:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to restore checkpoint');
        } finally {
            setLoading(false);
        }
    };

    const handleDeleteCheckpoint = async (checkpointName: string) => {
        const confirmed = await ConfirmDialogManager.Instance.showDeleteConfirm(`checkpoint "${checkpointName}"`);

        if (!confirmed) return;

        try {
            setLoading(true);
            const machine = Machine.getInstance();
            await machine.setup.DeleteCheckpoint(checkpointName);
            await loadCheckpoints();
        } catch (error) {
            console.error('Failed to delete checkpoint:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to delete checkpoint');
        } finally {
            setLoading(false);
        }
    };

    const formatDate = (dateString?: string | null) => {
        if (!dateString) return 'Unknown';
        try {
            const date = new Date(dateString);
            return date.toLocaleString();
        } catch {
            return dateString;
        }
    };

    return (
        <Box sx={{ p: 3 }}>
            <Box sx={{ mb: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Box>
                    <Typography variant="h5" gutterBottom>
                        Configuration Checkpoints
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                        Save and restore complete configuration snapshots including all settings, tools, materials, fixtures, and clamps
                    </Typography>
                </Box>
                <Stack direction="row" spacing={2}>
                    <Button
                        variant="outlined"
                        startIcon={<Upload />}
                        onClick={handleUploadConfiguration}
                        disabled={loading}
                    >
                        Import Config
                    </Button>
                    <Button
                        variant="outlined"
                        startIcon={<Download />}
                        onClick={handleDownloadConfiguration}
                        disabled={loading}
                        sx={{
                            borderColor: config.primaryColor,
                            color: config.primaryColor,
                            '&:hover': {
                                borderColor: config.primaryColor,
                                backgroundColor: `${config.primaryColor}10`
                            }
                        }}
                    >
                        Export Config
                    </Button>
                    <Button
                        variant="contained"
                        startIcon={<AddIcon />}
                        onClick={() => setDialogOpen(true)}
                        disabled={loading}
                    >
                        Create Checkpoint
                    </Button>
                </Stack>
            </Box>

            <TableContainer component={Paper}>
                <Table>
                    <TableHead>
                        <TableRow sx={{ backgroundColor: config.darkBackgroundColor }}>
                            <TableCell>
                                <Typography variant="subtitle2" fontWeight="bold">Name</Typography>
                            </TableCell>
                            <TableCell>
                                <Typography variant="subtitle2" fontWeight="bold">Created</Typography>
                            </TableCell>
                            <TableCell>
                                <Typography variant="subtitle2" fontWeight="bold">Files</Typography>
                            </TableCell>
                            <TableCell align="right">
                                <Typography variant="subtitle2" fontWeight="bold">Actions</Typography>
                            </TableCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {checkpoints.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={4} align="center" sx={{ py: 4 }}>
                                    <Typography color="text.secondary">
                                        No checkpoints found. Create your first checkpoint to save your current configuration.
                                    </Typography>
                                </TableCell>
                            </TableRow>
                        ) : (
                            checkpoints.map((checkpoint) => (
                                <TableRow key={checkpoint.name} hover>
                                    <TableCell>
                                        <Typography variant="body2" fontWeight="medium">
                                            {checkpoint.name}
                                        </Typography>
                                    </TableCell>
                                    <TableCell>
                                        <Typography variant="body2" color="text.secondary">
                                            {formatDate(checkpoint.created)}
                                        </Typography>
                                    </TableCell>
                                    <TableCell>
                                        <Chip
                                            label={`${checkpoint.fileCount || 0} files`}
                                            size="small"
                                            color="primary"
                                            variant="outlined"
                                        />
                                    </TableCell>
                                    <TableCell align="right">
                                        <IconButton
                                            size="small"
                                            onClick={() => handleRestoreCheckpoint(checkpoint.name || '')}
                                            disabled={loading}
                                            title="Restore Checkpoint"
                                            sx={{ color: config.primaryColor }}
                                        >
                                            <RestoreIcon />
                                        </IconButton>
                                        <IconButton
                                            size="small"
                                            onClick={() => handleDeleteCheckpoint(checkpoint.name || '')}
                                            disabled={loading}
                                            title="Delete Checkpoint"
                                            sx={{ color: 'error.main', ml: 1 }}
                                        >
                                            <DeleteIcon />
                                        </IconButton>
                                    </TableCell>
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </TableContainer>

            <CheckpointDialog
                open={dialogOpen}
                onClose={() => setDialogOpen(false)}
                onSave={handleCreateCheckpoint}
            />
        </Box>
    );
}
