import { Box, Typography } from '@mui/material';
import { ConfigurationData } from '../../data/ConfigurationData';
import { MachineStateData } from '../../data/MachineStateData';
import { ActionBus } from '../../utils/actions/ActionBus';
import { MoveAction, MoveType } from '../../utils/actions/MoveAction';
import { CoordinateOperations } from '../../utils/CoordinateOperations';
import { CoordinateUtil } from '../../utils/CoordinateUtil';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { NumberInput } from './NumberInput';

/**
 * Props for AxisCoordinateDisplay component
 */
interface AxisCoordinateDisplayProps {
    /** Array of axis names to display (e.g., ['X', 'Y', 'Z', 'A']) */
    axes?: string[];
    /** Whether to show Set/Go buttons (default: true) */
    showButtons?: boolean;
    /** Width of the coordinate input (default: '200px') */
    inputWidth?: string;
    /** Font size for axis label (default: '1.5rem') */
    labelFontSize?: string;
    /** Font size for coordinate value (default: '2.5rem') */
    valueFontSize?: string;
    /** Button width (default: '80px') */
    buttonWidth?: string;
    /** Button height (default: '56px') */
    buttonHeight?: string;
    /** Gap between elements (default: 2) */
    gap?: number;
    /** Vertical gap between axes (default: 2) */
    axisGap?: number;
    /** Custom label prefix (default: axis name + ':') */
    getLabelText?: (axis: string) => string;
    /** Callback when coordinate changes (optional - uses CoordinateOperations by default) */
    onCoordinateChange?: (axis: string, value: number) => void;
    /** Callback when Set button clicked (optional - uses CoordinateOperations by default) */
    onSetWorkZero?: (axis: string) => void;
    /** Callback when Go button clicked (optional - uses CoordinateOperations by default) */
    onGoToPosition?: (axis: string) => void;
}

/**
 * Reusable component for displaying and editing axis coordinates
 * Shows work coordinates with NumberInput controls and Set/Go buttons
 * 
 * Set button: Appears when work coordinate is not at zero - sets work zero to current position
 * Go button: Appears when user has entered a proposed position - moves to that position
 * 
 * @example
 * // Basic usage with X, Y, Z axes
 * <AxisCoordinateDisplay axes={['X', 'Y', 'Z']} />
 * 
 * @example
 * // Custom styling without buttons
 * <AxisCoordinateDisplay 
 *   axes={['X', 'Y']} 
 *   showButtons={false}
 *   inputWidth="150px"
 *   valueFontSize="2rem"
 * />
 */
export function AxisCoordinateDisplay({
    axes = ['X', 'Y', 'Z', 'A'],
    showButtons = true,
    inputWidth = '200px',
    labelFontSize = '1.5rem',
    valueFontSize = '2.5rem',
    buttonWidth = '80px',
    buttonHeight = '56px',
    gap = 2,
    axisGap = 2,
    getLabelText = (axis: string) => `${axis}:`,
    onCoordinateChange,
    onSetWorkZero,
    onGoToPosition,
}: AxisCoordinateDisplayProps) {
    const config = ConfigurationData.Instance;
    const machineState = MachineStateData.Instance;

    const handleCoordinateChange = (axis: string, value: number) => {
        if (onCoordinateChange) {
            onCoordinateChange(axis, value);
        } else {
            CoordinateOperations.setProposedCoordinate(axis, value);
        }
    };

    const getButtonType = (axis: string): string | null => {
        if (!showButtons) return null;

        // Show Go button if this specific axis has a proposed position that differs
        if (CoordinateOperations.hasProposedPositionForAxis(axis)) {
            return 'go';
        }

        // Check if we should show Set button based on work coordinate value
        const currentMachinePos = machineState.currentMachinePoint;
        const workCoordinates = CoordinateUtil.toWorkZero(currentMachinePos);

        // Get the work coordinate for the axis
        let workCoordinate: number;
        switch (axis.toUpperCase()) {
            case 'X':
                workCoordinate = workCoordinates.x;
                break;
            case 'Y':
                workCoordinate = workCoordinates.y;
                break;
            case 'Z':
                workCoordinate = workCoordinates.z;
                break;
            case 'A':
                workCoordinate = 0; // A-axis placeholder - treat as always at zero for now
                break;
            default:
                return null;
        }

        // If work coordinate is close to 0, don't show Set button
        const tolerance = 0.001;
        const isAtWorkZero = Math.abs(workCoordinate) < tolerance;

        if (isAtWorkZero) {
            return null; // No button when work coordinate is 0
        }

        return 'set'; // Show Set button when work coordinate is not 0
    };

    const handleSetWorkZero = (axis: string) => {
        if (onSetWorkZero) {
            onSetWorkZero(axis);
        } else {
            CoordinateOperations.setWorkZero(axis);
        }
    };

    const handleGoToPosition = (axis: string) => {
        if (onGoToPosition) {
            onGoToPosition(axis);
        } else {
            const proposedPosition = machineState.proposedSpindlePosition;
            if (!proposedPosition) return;

            // Create move action with the proposed position
            const moveAction = MoveAction.fromCNCPoint(proposedPosition, MoveType.Coordinates);
            ActionBus.Instance.addAction(moveAction);

            // Note: proposedSpindlePosition is cleared by MoveAction when canceled or completed
        }
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: axisGap }}>
            <ObserveState
                key="axis-coordinate-display"
                listenTo={machineState}
                properties={['currentMachinePoint', 'currentWorkZero', 'currentToolOffsets', 'currentToolNumber', 'proposedSpindlePosition']}
                control={() => {
                    return (
                        <>
                            {axes.map((axis) => {
                                const displayValue = CoordinateOperations.getDisplayCoordinate(axis);
                                const buttonType = getButtonType(axis);
                                const hasProposedForAxis = CoordinateOperations.hasProposedPositionForAxis(axis);

                                return (
                                    <Box key={axis} sx={{ display: 'flex', alignItems: 'center', gap }}>
                                        <Typography sx={{ minWidth: '40px', fontSize: labelFontSize, fontWeight: 'bold' }}>
                                            {getLabelText(axis)}
                                        </Typography>
                                        <NumberInput
                                            value={displayValue}
                                            onChange={(value) => handleCoordinateChange(axis, value)}
                                            precision={3}
                                            allowNegative={true}
                                            allowPositive={true}
                                            allowFractions={true}
                                            showHelperText={false}
                                            beforeText={`Work coordinate ${axis} - position relative to work zero`}
                                            afterText="Press Enter/Tab to move, or use Set button to set work zero to current position."
                                            disabled={false}
                                            size="medium"
                                            variant="outlined"
                                            textColor={hasProposedForAxis ? config.successColor : undefined}
                                            sx={{
                                                width: inputWidth,
                                                '& .MuiOutlinedInput-input': {
                                                    fontFamily: 'monospace',
                                                    fontSize: valueFontSize,
                                                    fontWeight: 'bold',
                                                    padding: '12px 16px',
                                                    textAlign: 'right'
                                                },
                                                '& .MuiOutlinedInput-root': {
                                                    backgroundColor: config.lightTextColor,
                                                    borderWidth: '2px',
                                                    borderColor: config.borderColor,
                                                }
                                            }}
                                        />
                                        {buttonType && (
                                            <Box
                                                sx={{
                                                    width: buttonWidth,
                                                    height: buttonHeight,
                                                    backgroundColor: config.primaryColor,
                                                    color: config.lightTextColor,
                                                    border: 'none',
                                                    borderRadius: '4px',
                                                    cursor: 'pointer',
                                                    fontSize: '1rem',
                                                    fontWeight: 'bold',
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    justifyContent: 'center',
                                                    '&:hover': {
                                                        opacity: 0.9
                                                    }
                                                }}
                                                component="button"
                                                onClick={() => buttonType === 'set' ? handleSetWorkZero(axis) : handleGoToPosition(axis)}
                                            >
                                                {buttonType === 'set' ? 'Set' : 'Go'}
                                            </Box>
                                        )}
                                    </Box>
                                );
                            })}
                        </>
                    );
                }}
            />
        </Box>
    );
}
