import { Search as SearchIcon } from '@mui/icons-material';
import {
    Box,
    Card,
    CardContent,
    FormControl,
    InputLabel,
    MenuItem,
    Select,
    Typography
} from '@mui/material';
import React from 'react';
import { FlowDataSelector } from '../../components/Common/FlowDataSelector';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { FlowStep } from "../FlowStep";
import { FlowStepData } from "../FlowStepData";
import { ExistsStepData } from './ExistsStepData';

export class ExistsStep extends FlowStep {
    readonly __type = 'ExistsStep';
    readonly category = ['Logic'];
    readonly name = 'Exists';
    readonly description = 'Checks if a value exists or is defined';

    // StateManager-based step data
    public stepData: ExistsStepData = new ExistsStepData();

    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(SearchIcon, { sx: { color: 'info.main' } });
    }

    // Static path constants
    static readonly YES_PATH = 'yes';
    static readonly NO_PATH = 'no';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            // Simulate existence check for testing
            return Math.random() > 0.3 ? ExistsStep.YES_PATH : ExistsStep.NO_PATH;
        }

        try {
            // Get value from data path
            const value = this.getValueFromData(data, this.stepData.dataPath);
            
            // Check if value exists and is defined
            const exists = value !== undefined && value !== null;
            console.log(`ExistsStep: Checking if '${this.stepData.dataPath}' exists = ${exists}`);

            return exists ? ExistsStep.YES_PATH : ExistsStep.NO_PATH;

        } catch (error) {
            console.error('ExistsStep execution error:', error);
            return ExistsStep.NO_PATH;
        }
    }

    private getValueFromData(data: FlowStepData, path: string): any {
        if (!path) return undefined;

        const allData = data.getAllData();
        const pathParts = path.split('.');

        let current = allData;
        for (const part of pathParts) {
            if (current && typeof current === 'object' && part in current) {
                current = current[part];
            } else {
                return undefined;
            }
        }

        return current;
    }

    results(): string[] {
        return [ExistsStep.YES_PATH, ExistsStep.NO_PATH];
    }

    renderResultsUI(): React.ReactNode {
        const result = this.stepData.dataPath
            ? `Check if '${this.stepData.dataPath}' exists`
            : 'Not configured';

        return (
            <Typography variant="caption">
                {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void, flow: any, flowStep?: any }): React.ReactNode {
        // Extract flow from props - we'll use 'this' as the flowStep
        const { flow } = props;

        return (
            <ObserveState
                key="exists-step-edit-ui"
                listenTo={this.stepData}
                properties={['dataType', 'dataPath']}
                control={() => (
                    <Box sx={{ minWidth: 500 }}>
                        <Box sx={{ p: 2, minWidth: 400 }}>
                            <Typography variant="h6" gutterBottom>
                                Exists Check Configuration
                            </Typography>

                            {/* Data Type Selection */}
                            <FormControl fullWidth margin="normal">
                                <InputLabel>Data Type</InputLabel>
                                <Select
                                    value={this.stepData.dataType}
                                    label="Data Type"
                                    onChange={(e) => {
                                        this.stepData.dataType = e.target.value;
                                        // Clear data path when type changes
                                        this.stepData.dataPath = '';
                                    }}
                                >
                                    <MenuItem value="string">String</MenuItem>
                                    <MenuItem value="number">Number</MenuItem>
                                    <MenuItem value="boolean">Boolean</MenuItem>
                                    <MenuItem value="cncpoint">CNC Point</MenuItem>
                                </Select>
                            </FormControl>

                            {/* Visual Separator */}
                            <Box sx={{ 
                                mt: 2, 
                                mb: 2, 
                                textAlign: 'center',
                                py: 2,
                                borderTop: '3px solid',
                                borderBottom: '3px solid',
                                borderColor: 'info.main',
                                backgroundColor: 'grey.50'
                            }}>
                                <Typography variant="h5" sx={{ 
                                    fontWeight: 'bold', 
                                    letterSpacing: 2,
                                    color: 'info.main'
                                }}>
                                    EXISTS?
                                </Typography>
                            </Box>

                            {/* Data Element Selector */}
                            <Card variant="outlined" sx={{ mt: 2 }}>
                                <CardContent>
                                    <FlowDataSelector
                                        flow={flow}
                                        flowStep={this}
                                        allowedTypes={[this.stepData.dataType]}
                                        currentSelection={this.stepData.dataPath ? [this.stepData.dataPath] : []}
                                        onChange={(paths) => {
                                            this.stepData.dataPath = paths.length > 0 ? paths[0] : '';
                                        }}
                                        label="Select Data Element to Check"
                                    />
                                </CardContent>
                            </Card>
                        </Box>
                    </Box>
                )}
            />
        );
    }

    // Serialization
    public toJSON(): any {
        const baseData = DataUtilities.getStorageData(this, ['stepData']);
        return {
            ...baseData,
            __type: this.__type,
            stepData: this.stepData.toJSON()
        };
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['stepData']);
        if (data.stepData) {
            this.stepData.fromJSON(data.stepData);
        }
    }
}
