import { CoordinateType } from './Common/CoordinateType';
import { IStorable } from '../common/IStorable';
import { DataUtilities } from '../utils/storage/DataUtilities';

/**
 * 3D Point with coordinate type information
 * Direct conversion from C# Point3DWithType class (now renamed to CNCPoint)
 */
export class CNCPoint implements IStorable {
  public x: number;
  public y: number;
  public z: number;
  public coordinateType: CoordinateType;

  constructor(x: number, y: number, z: number, coordinateType: CoordinateType) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.coordinateType = coordinateType;
  }

  /**
   * IStorable implementation - serialize to JSON using generic DataUtilities approach
   */
  public toJSON(): object {
    // Simple object with no sub-objects, StateManager observers automatically excluded
    return DataUtilities.getStorageData(this);
  }

  /**
   * IStorable implementation - deserialize from JSON using generic DataUtilities approach
   */
  public fromJSON(data: any): void {
    if (!data) return;
    
    // Load data directly since CNCPoint has no setters with StateManager notifications
    DataUtilities.loadStorageData(this, data);
  }
}
