import {
  Box,
  Button,
  Checkbox,
  Divider,
  FormControlLabel,
  FormGroup,
  Paper,
  Typography
} from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { DataManager } from '../../data/DataManager';
import { Job } from '../../data/Job';
import { MachineData } from '../../data/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { ConfirmDialogManager } from '../../utils/ConfirmDialogManager';
import { ObserveMultiState } from '../../utils/statemanager/ObserveMultiState';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { CNCViewer } from '../MachineViewer/CNCViewer';
import { ApiTestingTab } from '../Views/Settings/ApiTesting';
import { CoordinateSystemTab } from '../Views/Settings/CoordinateSystemTab';
import { IconInventoryTab } from '../Views/Settings/IconInventoryTab';
import { LogViewerTab } from '../Views/Settings/LogViewerTab';
import { MachineDataTab } from '../Views/Settings/MachineDataTab';

interface SystemSetupTabButtonProps {
  label: string;
  isActive: boolean;
  onClick: () => void;
}

const SystemSetupTabButton: React.FC<SystemSetupTabButtonProps> = ({ label, isActive, onClick }) => (
  <Button
    variant={isActive ? 'contained' : 'text'}
    onClick={onClick}
    sx={{
      mx: 1,
      minWidth: '120px',
      textTransform: 'none',
      fontSize: '14px'
    }}
  >
    {label}
  </Button>
);

type SystemSetupTab = 'machine' | 'coordinates' | 'logs' | 'icons' | 'api' | 'reset';

export function SystemSetupPanel() {
  // Default to 'machine' tab
  const defaultTab: SystemSetupTab = 'machine';
  const [activeTab, setActiveTab] = useState<SystemSetupTab>(defaultTab);

  // Reset checkboxes state
  const [selectedResets, setSelectedResets] = useState({
    configuration: false,
    machineData: false,
    machineState: false,
    toolLibrary: false,
    materialLibrary: false,
    fixtureLibrary: false,
    clampLibrary: false,
    userActionData: false
  });

  const handleResetCheckboxChange = (resetType: keyof typeof selectedResets) => {
    setSelectedResets(prev => ({
      ...prev,
      [resetType]: !prev[resetType]
    }));
  };

  const handleSelectAll = () => {
    const allSelected = Object.values(selectedResets).every(Boolean);
    const newState = !allSelected;
    setSelectedResets({
      configuration: newState,
      machineData: newState,
      machineState: newState,
      toolLibrary: newState,
      materialLibrary: newState,
      fixtureLibrary: newState,
      clampLibrary: newState,
      userActionData: newState
    });
  };

  const resetItems = [
    { key: 'configuration' as const, label: 'Configuration Data', action: () => DataManager.Instance.resetConfigurationDataOnly() },
    { key: 'machineData' as const, label: 'Machine Data', action: () => DataManager.Instance.resetMachineDataOnly() },
    { key: 'machineState' as const, label: 'Machine State', action: () => DataManager.Instance.resetMachineStateDataOnly() },
    { key: 'toolLibrary' as const, label: 'Tool Library', action: () => DataManager.Instance.resetToolLibraryOnly() },
    { key: 'materialLibrary' as const, label: 'Material Library', action: () => DataManager.Instance.resetMaterialLibraryOnly() },
    { key: 'fixtureLibrary' as const, label: 'Fixture Library', action: () => DataManager.Instance.resetFixtureLibraryOnly() },
    { key: 'clampLibrary' as const, label: 'Clamp Library', action: () => DataManager.Instance.resetClampLibraryOnly() },
    { key: 'userActionData' as const, label: 'User Action Data', action: () => DataManager.Instance.resetUserActionDataOnly() }
  ];

  const handleReset = async () => {
    const selectedItems = resetItems.filter(item => selectedResets[item.key]);

    if (selectedItems.length === 0) {
      UserMessageQueue.Instance.addMessage('⚠️ No items selected for reset');
      return;
    }

    const itemNames = selectedItems.map(item => item.label).join(', ');

    const confirmed = await ConfirmDialogManager.Instance.showResetConfirm(itemNames);

    if (confirmed) {

      selectedItems.forEach(item => {
        item.action();
        UserMessageQueue.Instance.addMessage(`✓ ${item.label} reset to defaults`);
      });


      // Clear selections after reset
      setSelectedResets({
        configuration: false,
        machineData: false,
        machineState: false,
        toolLibrary: false,
        materialLibrary: false,
        fixtureLibrary: false,
        clampLibrary: false,
        userActionData: false
      });
    }
  };

  const renderActiveTab = () => {
    switch (activeTab) {
      case 'machine':
        return <MachineDataTab />;
      case 'coordinates':
        return <CoordinateSystemTab />;
      case 'logs':
        return <LogViewerTab />;
      case 'icons':
        return <IconInventoryTab />;
      case 'api':
        return <ApiTestingTab />;
      case 'reset':
        return (
          <Box sx={{ p: 3 }}>
            <Typography variant="h6" gutterBottom>
              System Reset Options
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
              Select the data components you want to reset and click the Reset button. These actions cannot be undone.
            </Typography>

            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
              {/* Individual Reset Checkboxes */}
              <Paper sx={{ p: 2 }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                  <Typography variant="subtitle1">Select Data to Reset</Typography>
                  <Button
                    variant="text"
                    size="small"
                    onClick={handleSelectAll}
                  >
                    {Object.values(selectedResets).every(Boolean) ? 'Deselect All' : 'Select All'}
                  </Button>
                </Box>

                <FormGroup>
                  {resetItems.map((item) => (
                    <FormControlLabel
                      key={item.key}
                      control={
                        <Checkbox
                          checked={selectedResets[item.key]}
                          onChange={() => handleResetCheckboxChange(item.key)}
                          color="warning"
                        />
                      }
                      label={item.label}
                    />
                  ))}
                </FormGroup>

                <Box sx={{ mt: 2, display: 'flex', gap: 2 }}>
                  <Button
                    variant="contained"
                    color="warning"
                    onClick={handleReset}
                    disabled={!Object.values(selectedResets).some(Boolean)}
                  >
                    Reset Selected ({Object.values(selectedResets).filter(Boolean).length})
                  </Button>
                </Box>
              </Paper>

              {/* Reset All Button */}
              <Paper sx={{ p: 2, backgroundColor: 'error.light', color: 'error.contrastText' }}>
                <Typography variant="subtitle1" gutterBottom>
                  Complete System Reset
                </Typography>
                <Typography variant="body2" sx={{ mb: 2 }}>
                  ⚠️ This will reset ALL system data including configuration, machine settings, and all libraries. This action cannot be undone.
                </Typography>
                <Button
                  variant="contained"
                  color="error"
                  size="large"
                  onClick={async () => {
                    const confirmed = await ConfirmDialogManager.Instance.showResetConfirm('ALL system data');
                    if (confirmed) {
                      DataManager.Instance.resetAllData();
                      UserMessageQueue.Instance.addMessage('⚠️ All system data reset to defaults');
                      // Clear checkbox selections after complete reset
                      setSelectedResets({
                        configuration: false,
                        machineData: false,
                        machineState: false,
                        toolLibrary: false,
                        materialLibrary: false,
                        fixtureLibrary: false,
                        clampLibrary: false,
                        userActionData: false
                      });
                    }
                  }}
                >
                  Reset All System Data
                </Button>
              </Paper>
            </Box>
          </Box>
        );
      default:
        return <MachineDataTab />;
    }
  };

  return (
    <ObserveState
      listenTo={ConfigurationData.Instance}
      properties={['systemConfigurationUnlocked']}
      control={() => {
        const config = ConfigurationData.Instance;

        // Only show when unlocked
        if (!config.systemConfigurationUnlocked) {
          return null;
        }

        return (
          <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            {/* Header */}
            <Paper sx={{ p: 2, borderBottom: 1, borderColor: 'divider', borderRadius: 0 }}>
              <Box sx={{ display: 'flex', alignItems: 'center' }}>

                {/* Tab Navigation */}
                {ConfigurationData.Instance.showCentroidConfigurationTabs && (
                  <>
                    <SystemSetupTabButton
                      label="Coordinates"
                      isActive={activeTab === 'coordinates'}
                      onClick={() => setActiveTab('coordinates')}
                    />

                    <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />
                  </>
                )}

                <SystemSetupTabButton
                  label="Machine Data"
                  isActive={activeTab === 'machine'}
                  onClick={() => setActiveTab('machine')}
                />

                <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

                <SystemSetupTabButton
                  label="Logs"
                  isActive={activeTab === 'logs'}
                  onClick={() => setActiveTab('logs')}
                />

                <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

                <SystemSetupTabButton
                  label="Icon Inventory"
                  isActive={activeTab === 'icons'}
                  onClick={() => setActiveTab('icons')}
                />

                <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

                <SystemSetupTabButton
                  label="API Testing"
                  isActive={activeTab === 'api'}
                  onClick={() => setActiveTab('api')}
                />

                <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />

                <SystemSetupTabButton
                  label="Reset"
                  isActive={activeTab === 'reset'}
                  onClick={() => setActiveTab('reset')}
                />
              </Box>
            </Paper>

            {/* Content - Conditional Layout */}
            <Box sx={{ flex: 1, display: 'flex', overflow: 'hidden' }}>
              {/* System Setup Panel */}
              <Box sx={{
                width: '60%',
                overflow: 'auto'
              }}>
                {renderActiveTab()}
              </Box>

              {/* 3D Viewer Panel */}
              {(
                <Box sx={{
                  width: '40%',
                  borderLeft: 1,
                  borderColor: 'divider',
                  position: 'relative',
                  overflow: 'hidden'
                }}>
                  <Box sx={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    backgroundColor: config.lightBackgroundColor
                  }}>
                    <ObserveMultiState
                      listenTo={[ConfigurationData.Instance, MachineData.Instance]}
                      control={() => (
                        <CNCViewer
                          simulatorView={config.defaultView}
                          machineState={MachineStateData.Instance}
                          machineData={MachineData.Instance}
                          job={MachineStateData.Instance.currentJob || Job.createTestJob()}
                          isHardcodedSettings={true}
                        />
                      )}
                    />
                  </Box>
                </Box>
              )}
            </Box>
          </Box>
        );
      }}
    />
  );
}
