import { IStorable } from '../../common/IStorable';
import { CoordinateUtil } from '../../utils/CoordinateUtil';
import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { CNCPoint } from '../CNCPoint';
import { CoordinateType } from './CoordinateType';
import { SaveableDataBase } from './SaveableDataBase';

/**
 * Constants for computed known point names
 */
export const COMPUTED_POINT_MACHINE_ZERO = 'Machine Zero';
export const COMPUTED_POINT_MACHINE_HOME = 'Machine Home';
export const COMPUTED_POINT_CURRENT_FIXTURE = 'Current Fixture Home';
export const COMPUTED_POINT_SPOILBOARD_CORNER = 'Spoilboard Corner (Top, Front, Left)';
export const COMPUTED_POINT_BED_CORNER = 'Bed Corner (Top, Front, Left)';

/**
 * Fixture type enumeration
 */
export enum FixtureType {
  SavedPoint = 0,
  SpoilboardCorner = 1,
  BedCorner = 2,
  System = 3,
  Fixture = 4
}

/**
 * Fixture definition for coordinate offsets
 * Direct conversion from C# Fixture class
 */
export class Fixture implements IStorable {
  private _name: string;
  private _fixtureNumber: string;
  private _offset: CNCPoint; // Use CNCPoint internally for stable object reference
  private _used: boolean;
  private _fixtureType: FixtureType;
  private _userDefined: boolean;
  private _isComputed: boolean;

  constructor(name: string, fixtureNumber: string, xOffset: number, yOffset: number, zOffset: number, used: boolean = false, type: FixtureType = FixtureType.SavedPoint, userDefined: boolean = false, isComputed: boolean = false) {
    this._name = name;
    this._fixtureNumber = fixtureNumber;
    this._offset = new CNCPoint(xOffset, yOffset, zOffset, CoordinateType.MachineZero);
    this._used = used;
    this._fixtureType = type;
    this._userDefined = userDefined;
    this._isComputed = isComputed;
  }

  public get name(): string {
    return this._name;
  }

  public set name(value: string) {
    this._name = value;
    StateManager.propertyChanged(this, 'name');
  }

  public get fixtureNumber(): string {
    return this._fixtureNumber;
  }

  public set fixtureNumber(value: string) {
    this._fixtureNumber = value;
    StateManager.propertyChanged(this, 'fixtureNumber');
  }

  public get isComputed(): boolean {
    return this._isComputed;
  }

  public get xOffset(): number {
    if (this._isComputed) {
      return this.getComputedPoint().x;
    }
    return this._offset.x;
  }

  public set xOffset(value: number) {
    this._offset.x = value;
    StateManager.propertyChanged(this, 'xOffset');
    // Also notify about the CNCPoint change to trigger useMemo dependencies
    StateManager.propertyChanged(this._offset, 'x');

    // If this is the current fixture, notify that currentWorkZero has changed
    this.notifyCurrentWorkZeroIfCurrent();

    // If this is the current fixture, update the API fixture point
    this.updateAPIFixturePointIfCurrent();
  }

  public get yOffset(): number {
    if (this._isComputed) {
      return this.getComputedPoint().y;
    }
    return this._offset.y;
  }

  public set yOffset(value: number) {
    this._offset.y = value;
    StateManager.propertyChanged(this, 'yOffset');
    // Also notify about the CNCPoint change to trigger useMemo dependencies
    StateManager.propertyChanged(this._offset, 'y');

    // If this is the current fixture, notify that currentWorkZero has changed
    this.notifyCurrentWorkZeroIfCurrent();

    // If this is the current fixture, update the API fixture point
    this.updateAPIFixturePointIfCurrent();
  }

  public get zOffset(): number {
    if (this._isComputed) {
      return this.getComputedPoint().z;
    }
    return this._offset.z;
  }

  public set zOffset(value: number) {
    this._offset.z = value;
    StateManager.propertyChanged(this, 'zOffset');
    // Also notify about the CNCPoint change to trigger useMemo dependencies
    StateManager.propertyChanged(this._offset, 'z');

    // If this is the current fixture, notify that currentWorkZero has changed
    this.notifyCurrentWorkZeroIfCurrent();

    // If this is the current fixture, update the API fixture point
    this.updateAPIFixturePointIfCurrent();
  }

  /**
   * Get the cached CNCPoint representing this fixture's offset
   * Returns the same object reference until offsets change
   */
  public get workZeroPoint(): CNCPoint {
    return this._offset;
  }

  /**
   * Read-only property indicating if this fixture is system-controlled (not user-editable)
   * Returns true for SpoilboardCorner, BedCorner, and System types
   */
  public get systemControlled(): boolean {
    return this._fixtureType === FixtureType.SpoilboardCorner ||
      this._fixtureType === FixtureType.BedCorner ||
      this._fixtureType === FixtureType.System;
  }

  public get showAsSelectable(): boolean {
    // Deprecated: All fixtures are now selectable
    return true;
  }

  public set showAsSelectable(value: boolean) {
    // Deprecated: All fixtures are now selectable
    // No-op for backward compatibility
  }

  public get used(): boolean {
    return this._used;
  }

  public set used(value: boolean) {
    this._used = value;
    StateManager.propertyChanged(this, 'used');
  }

  public get type(): FixtureType {
    return this._fixtureType;
  }

  public set type(value: FixtureType) {
    this._fixtureType = value;
    StateManager.propertyChanged(this, 'type');
  }

  public get userDefined(): boolean {
    return this._userDefined;
  }

  public set userDefined(value: boolean) {
    this._userDefined = value;
    StateManager.propertyChanged(this, 'userDefined');
  }

  /**
   * Get computed point coordinates for special computed fixtures
   */
  private getComputedPoint(): CNCPoint {
    // Import these dynamically to avoid circular dependencies
    const MachineStateData = require('../MachineStateData').MachineStateData;
    const ConfigurationState = require('../ConfigurationState').ConfigurationState;

    switch (this._name) {
      case COMPUTED_POINT_MACHINE_ZERO:
        // Machine zero is at (0, 0, 0) in MachineZero coordinates
        return new CNCPoint(0, 0, 0, CoordinateType.MachineZero);

      case COMPUTED_POINT_MACHINE_HOME:
        // Get machine home corner and convert to MachineZero
        const machineHome = CoordinateUtil.machineHomeCorner;
        return CoordinateUtil.toMachineZero(machineHome);

      case COMPUTED_POINT_CURRENT_FIXTURE:
        // Get current fixture's work zero point
        const currentFixture = ConfigurationState.Instance.currentFixture;
        if (currentFixture && !currentFixture.isComputed) {
          return new CNCPoint(currentFixture.xOffset, currentFixture.yOffset, currentFixture.zOffset, CoordinateType.MachineZero);
        }
        return new CNCPoint(0, 0, 0, CoordinateType.MachineZero);

      case COMPUTED_POINT_SPOILBOARD_CORNER:
        // Get spoilboard box and return top, front, left corner
        const machineState = MachineStateData.Instance;
        const spoilboardBox = CoordinateUtil.getSpoilboardBox(machineState);
        // Box origin is at bottom, front, left - add height for top
        return new CNCPoint(
          spoilboardBox.origin.x,  // Front-left
          spoilboardBox.origin.y,
          spoilboardBox.origin.z + spoilboardBox.height, // Top
          CoordinateType.MachineZero
        );

      case COMPUTED_POINT_BED_CORNER:
        // Get bed box and return top, front, left corner
        const machineState2 = MachineStateData.Instance;
        const bedBox = CoordinateUtil.getBedBox(machineState2);
        // Box origin is at bottom, front, left - add height for top
        return new CNCPoint(
          bedBox.origin.x,  // Front-left
          bedBox.origin.y,
          bedBox.origin.z + bedBox.height, // Top
          CoordinateType.MachineZero
        );

      default:
        return new CNCPoint(0, 0, 0, CoordinateType.MachineZero);
    }
  }

  /**
   * If this fixture is the current fixture, notify that currentWorkZero has changed
   */
  private notifyCurrentWorkZeroIfCurrent(): void {
    const MachineStateData = require('../MachineStateData').MachineStateData;
    const ConfigurationState = require('../ConfigurationState').ConfigurationState;

    // Check if this fixture is the current fixture
    if (ConfigurationState.Instance.currentFixture === this) {
      StateManager.propertyChanged(MachineStateData.Instance, 'currentWorkZero');
    }
  }

  /**
   * If this fixture is the current fixture, call the API to update the fixture point
   */
  private updateAPIFixturePointIfCurrent(): void {
    const ConfigurationState = require('../ConfigurationState').ConfigurationState;

    // Check if this fixture is the current fixture
    if (ConfigurationState.Instance.currentFixture === this) {
      // Use async IIFE to call the API method
      (async () => {
        try {
          const Machine = require('../../Machine').Machine;
          await Machine.getInstance().movement.SetCurrentFixturePoint();
        } catch (error) {
          // Silently fail - errors are already logged by the movement implementation
        }
      })();
    }
  }



  /**
   * IStorable implementation - serialize to JSON using generic DataUtilities approach
   */
  public toJSON(): object {
    // Handle CNCPoint serialization explicitly
    const baseData = DataUtilities.getStorageData(this, ['_offset']);
    return {
      ...baseData,
      _offset: this._offset.toJSON()
    };
  }

  /**
   * IStorable implementation - deserialize from JSON with CNCPoint handling
   */
  public fromJSON(data: any): void {
    if (!data) return;

    // Load basic properties automatically
    DataUtilities.loadStorageData(this, data, ['_offset']);

    // Handle CNCPoint explicitly
    if (data._offset) {
      this._offset.fromJSON(data._offset);
    }

    // Set default type if not present in data (for backwards compatibility)
    // Must check for undefined/null explicitly, not falsy check, because FixtureType.SavedPoint = 0 which is falsy!
    if (data.fixtureType === undefined || data.fixtureType === null) {
      this._fixtureType = FixtureType.SavedPoint;
    }
  }
}

/**
 * Fixture library for managing coordinate systems
 * Direct conversion from C# FixtureLibrary class
 * Implemented as singleton pattern
 */
export class FixtureLibrary extends SaveableDataBase {
  private static _instance: FixtureLibrary;

  /**
   * Filename for saving/loading fixture library data
   */
  protected get filename(): string {
    return 'fixture-library.json';
  }

  public fixtures: Fixture[];

  public static getFixtureByName(name: string): Fixture | undefined {
    return FixtureLibrary.Instance.fixtures.find(fixture => fixture.name === name);
  }

  public static getFixtureByNumber(fixtureNumber: string): Fixture | undefined {
    return FixtureLibrary.Instance.fixtures.find(fixture => fixture.fixtureNumber === fixtureNumber);
  }

  private constructor() {
    super();

    this.fixtures = [];

    // Helper method to add fixture only if it doesn't already exist
    const addFixtureIfNotExists = (name: string, fixtureNumber: string, xOffset: number, yOffset: number, zOffset: number, used: boolean = false, type: FixtureType = FixtureType.SavedPoint) => {
      const existing = this.fixtures.find(f => f.fixtureNumber === fixtureNumber);
      if (!existing) {
        this.fixtures.push(new Fixture(name, fixtureNumber, xOffset, yOffset, zOffset, used, type));
      }
    };

    // add g28
    addFixtureIfNotExists("G28", "G28", 0, 0, 0, false, FixtureType.Fixture);
    // add default fixtures from g54 to g59
    addFixtureIfNotExists("Default", "G54", 5, 5, -3, false, FixtureType.Fixture);
    addFixtureIfNotExists("G55", "G55", 6, 6, -4, false, FixtureType.Fixture);
    addFixtureIfNotExists("G56", "G56", 7, 7, -1, false, FixtureType.Fixture);
    addFixtureIfNotExists("G57", "G57", 8, 8, -5, false, FixtureType.Fixture);
    addFixtureIfNotExists("G58", "G58", 9, 9, 0, false, FixtureType.Fixture);
    addFixtureIfNotExists("Turning Center", "G59", 15, 6, -5, false, FixtureType.System);

    // add g54.1 P001 to g54.1 P012
    for (let i = 1; i <= 12; i++) {
      const paddedNumber = i.toString().padStart(3, '0');
      addFixtureIfNotExists(`G54.1 P${paddedNumber}`, `G54.1 P${paddedNumber}`, 0, 0, 0, false, FixtureType.Fixture);
    }

    // Add computed known points
    this.fixtures.push(new Fixture(COMPUTED_POINT_MACHINE_ZERO, '', 0, 0, 0, false, FixtureType.System, false, true));
    this.fixtures.push(new Fixture(COMPUTED_POINT_MACHINE_HOME, '', 0, 0, 0, false, FixtureType.System, false, true));
    this.fixtures.push(new Fixture(COMPUTED_POINT_CURRENT_FIXTURE, '', 0, 0, 0, false, FixtureType.System, false, true));
    this.fixtures.push(new Fixture(COMPUTED_POINT_SPOILBOARD_CORNER, '', 0, 0, 0, false, FixtureType.System, false, true));
    this.fixtures.push(new Fixture(COMPUTED_POINT_BED_CORNER, '', 0, 0, 0, false, FixtureType.System, false, true));

    // Note: setupAutoSave() will be called after instance creation to avoid constructor issues
  }

  /**
   * Add a new fixture to the library
   */
  public addFixture(fixture: Fixture): void {
    this.fixtures.push(fixture);
    StateManager.propertyChanged(this, 'fixtures');
  }

  /**
   * Remove a fixture from the library
   */
  public removeFixture(fixtureNumberOrName: string): boolean {
    const index = this.fixtures.findIndex(f => f.fixtureNumber === fixtureNumberOrName || f.name === fixtureNumberOrName);
    if (index >= 0) {
      this.fixtures.splice(index, 1);
      StateManager.propertyChanged(this, 'fixtures');
      return true;
    }
    return false;
  }

  /**
   * Serialize to JSON - handle fixture array explicitly
   */
  public toJSON(): any {
    const baseData = DataUtilities.getStorageData(this, ['fixtures']); // Exclude fixtures from auto-processing

    // Handle fixtures array explicitly with proper serialization
    return {
      ...baseData,
      fixtures: this.fixtures.map(fixture => fixture.toJSON())
    };
  }

  /**
   * Load from JSON - handle fixture array explicitly with factory
   */
  public fromJSON(data: any): void {
    // Load basic properties
    DataUtilities.loadStorageData(this, data, ['fixtures']); // Exclude fixtures from auto-processing

    // Handle fixtures array explicitly
    if (data.fixtures && Array.isArray(data.fixtures)) {
      this.fixtures = data.fixtures.map((fixtureData: any) => {
        // Create fixture with default constructor values, then use fromJSON
        const fixture = new Fixture('', '', 0, 0, 0, false, FixtureType.SavedPoint);
        fixture.fromJSON(fixtureData);
        return fixture;
      });
    }
  }

  /**
   * Update fixture values (fixtures are predefined, cannot add new ones)
   */
  public updateFixtureValues(fixtureNumber: string, xOffset: number, yOffset: number, zOffset: number): void {
    const fixture = this.fixtures.find(f => f.fixtureNumber === fixtureNumber);
    if (fixture) {
      fixture.xOffset = xOffset;
      fixture.yOffset = yOffset;
      fixture.zOffset = zOffset;
      StateManager.propertyChanged(this, 'fixtures');
    }
  }

  /**
   * Update a fixture in the library (only for predefined fixtures)
   */
  public updateFixture(fixtureNumberOrName: string, xOffset: number, yOffset: number, zOffset: number): void {
    const fixture = this.fixtures.find(f => f.fixtureNumber === fixtureNumberOrName || f.name === fixtureNumberOrName);
    if (fixture) {
      fixture.xOffset = xOffset;
      fixture.yOffset = yOffset;
      fixture.zOffset = zOffset;
      StateManager.propertyChanged(this, 'fixtures');
    }
  }

  /**
   * Get the singleton instance
   */
  public static get Instance(): FixtureLibrary {
    if (!FixtureLibrary._instance) {
      FixtureLibrary._instance = new FixtureLibrary();
      // Setup auto-save after instance is fully created
      FixtureLibrary._instance.setupAutoSave();
      // Trigger an immediate save to persist default fixtures
      FixtureLibrary._instance.manualSave().catch(error => {
        console.error('Failed to save default fixtures:', error);
      });
    }
    return FixtureLibrary._instance;
  }

  /**
   * Update fixture values from loaded data
   * This finds existing fixtures and updates their offset values
   * Only updates predefined fixtures, does not add new ones
   */
  public updateFromLoadedData(loadedFixtures: any[]): void {
    if (!Array.isArray(loadedFixtures)) return;

    // Update existing fixtures only
    for (const fixtureData of loadedFixtures) {
      const existingFixture = this.fixtures.find(f =>
        f.fixtureNumber === fixtureData.fixtureNumber
      );

      if (existingFixture) {
        // Update existing fixture values
        existingFixture.xOffset = fixtureData.xOffset || 0;
        existingFixture.yOffset = fixtureData.yOffset || 0;
        existingFixture.zOffset = fixtureData.zOffset || 0;
        existingFixture.used = fixtureData.used || false;
      }
      // Silently ignore fixtures that don't exist in the predefined set
    }

    StateManager.propertyChanged(this, 'fixtures');
  }
}
