import React from 'react';
import { Box } from '@react-three/drei';
import { MachineData } from '../../../data/MachineData';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';

export interface VerticalTableProps {
  simulatorView: SimulatorView;
}

export function VerticalTable({ simulatorView }: VerticalTableProps) {
  const machineData = MachineData.Instance;
  const config = ConfigurationData.Instance;

  // Don't render if vertical table is not enabled
  if (!machineData.hasVerticalTable) {
    return null;
  }

  return (
    <ObserveMultiProperties
      listenTo={[
        { object: machineData, properties: ['verticalTableWidth', 'verticalTableHeight', 'verticalTableThickness', 'verticalTableOffsetX', 'verticalTableOffsetY', 'verticalTableOffsetZ', 'verticalTableAngle', 'baseHeight', 'baseWidth', 'baseLength'] },
        { object: config, properties: ['verticalTableColor', 'verticalTableTransparency'] },
        { object: simulatorView, properties: ['verticalTable'] }
      ]}
      control={() => {
        // Calculate position relative to top of base
        // The vertical table offset represents the top-back corner of the box
        // Base top surface is at Z = baseHeight
        const baseTopZ = machineData.baseHeight;
        
        // Calculate the center position of the vertical table box
        // Offset is to the top-back corner, so we need to adjust for box center
        // For a vertical table:
        // X: offset + width/2 (box extends in positive X direction from offset)
        // Y: offset - thickness/2 (box extends in negative Y direction from offset) 
        // Z: offset - height/2 (box extends in negative Z direction from offset)
        const tableX = machineData.verticalTableOffsetX + machineData.verticalTableWidth / 2;
        const tableY = machineData.verticalTableOffsetY - machineData.verticalTableThickness / 2;
        const tableZ = baseTopZ + machineData.verticalTableOffsetZ - machineData.verticalTableHeight / 2;

        // Convert angle from degrees to radians
        const angleRadians = (machineData.verticalTableAngle * Math.PI) / 180;

        // Determine material properties based on ViewStyle
        const isTransparent = simulatorView.verticalTable === ViewStyle.SemiTransparent;
        const isWireframe = simulatorView.verticalTable === ViewStyle.Wireframe;
        const opacity = isTransparent ? (config.verticalTableTransparency || 0.8) : 1.0;

        // Create unique key for React re-rendering when material properties change
        const renderKey = `vertical-table-${ViewStyle[simulatorView.verticalTable]}-${opacity}-${config.verticalTableColor}-${Date.now()}`;

        return (
          <group>
            <Box
              key={renderKey}
              position={[tableX, tableY, tableZ]}
              args={[machineData.verticalTableWidth, machineData.verticalTableThickness, machineData.verticalTableHeight]}
              rotation={[angleRadians - Math.PI/2, 0, 0]} // Rotate from horizontal (default) to specified angle
            >
              <meshPhongMaterial 
                color={config.verticalTableColor}
                transparent={isTransparent}
                opacity={opacity}
                wireframe={isWireframe}
              />
            </Box>
          </group>
        );
      }}
    />
  );
}
