import { StateManager } from '../utils/statemanager/StateManager';
import { DataUtilities } from '../utils/storage/DataUtilities';
import { IStorable } from '../utils/storage/IStorable';

/**
 * Source of the value - either from data element or direct value input
 */
export enum ValueSource {
    DataElement = 'dataElement',
    DirectValue = 'directValue'
}

/**
 * Class for storing a number value that can come from either a data element or direct input
 */
export class FlowNumberValue implements IStorable {
    private _valueSource: ValueSource = ValueSource.DirectValue;
    private _dataPath: string = '';
    private _numberValue: number = 0;

    get valueSource(): ValueSource {
        return this._valueSource;
    }

    set valueSource(value: ValueSource) {
        this._valueSource = value;
        StateManager.propertyChanged(this, 'valueSource');
    }

    get dataPath(): string {
        return this._dataPath;
    }

    set dataPath(value: string) {
        this._dataPath = value;
        StateManager.propertyChanged(this, 'dataPath');
    }

    get numberValue(): number {
        return this._numberValue;
    }

    set numberValue(value: number) {
        this._numberValue = value;
        StateManager.propertyChanged(this, 'numberValue');
    }

    /**
     * Get allowed types for data selector
     */
    getAllowedTypes(): string[] {
        return ['number'];
    }

    public toJSON(): any {
        return DataUtilities.getStorageData(this);
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}
