import React from "react";
import { Box, Typography, Button } from '@mui/material';
import { BaseWizardStep } from "../Wizard/BaseWizardStep";
import { Wizard } from "../Wizard/Wizard";
import { WizardStep } from "../Wizard/WizardStep";
import { CNCViewType } from '../MachineViewer/CNCViewer';
import { FullSizeCNCViewer } from '../MachineViewer/FullSizeCNCViewer';
import { MachineStateData } from '../../data/MachineStateData';
import { MachineData } from '../../data/MachineData';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { ViewStyle } from '../../data/Common/ViewStyle';
import { JogControls } from '../Common/JogControls';
import { MaterialEditor } from '../Views/MaterialEditor';
import { SimulatorView } from '../../data/Common/SimulatorView';
import { Job } from '../../data/Job';

export interface SpindlePositionStepOptions {
  /** Function that returns the next step in the wizard flow */
  nextStepFactory: () => WizardStep | null;
  /** Custom title for this step */
  title: string;
  /** Custom instructions text */
  instructions: string;
}

export class SpindlePositionStep extends BaseWizardStep {
  private materialEditorOpen = false;
  private options: SpindlePositionStepOptions;

  constructor(wizard: Wizard, priorStep: WizardStep | null = null, options: SpindlePositionStepOptions) {
    super(wizard, priorStep, "Continue", "Back");
    this.options = options;
  }

  getTitle(): string {
    return this.options.title;
  }

  nextStep(): WizardStep | null {
    return this.options.nextStepFactory();
  }

  private setMaterialEditorOpen = (open: boolean) => {
    this.materialEditorOpen = open;
    // Note: State changes in wizard steps require careful handling
    // For now, we'll just update the property
  };

  private createCalibrationSimulatorView(): SimulatorView {
    const view = new SimulatorView();
    view.clamps = ViewStyle.Show; // Show clamps for positioning reference
    return view;
  }

  renderButtons(): React.ReactNode {
    const config = ConfigurationData.Instance;
    
    return (
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        marginTop: '20px',
        paddingTop: '20px',
        borderTop: `1px solid ${config.borderColor}`
      }}>
        {this.priorStep ? (
          <Button
            variant="text"
            onClick={() => this.handleBack()}
            sx={{ textDecoration: 'underline' }}
          >
            {this.backButtonText}
          </Button>
        ) : (
          <div />
        )}
        
        <Button
          variant="contained"
          color="primary"
          onClick={() => this.handleNext()}
        >
          {this.nextButtonText}
        </Button>
      </Box>
    );
  }

  render(): React.ReactNode {
    return this.renderWithButtons(
      <ObserveState
        listenTo={MachineStateData.Instance}
        properties={['currentMachinePoint']}
        control={() => {
          // Create special view for positioning with clamps visible and top view
          const view = this.createCalibrationSimulatorView();
          
          return (
            <Box sx={{ display: 'flex', height: '100%' }}>
              {/* Left panel with instructions and controls */}
              <Box sx={{ flex: 1, pr: 3, display: 'flex', flexDirection: 'column' }}>
                <Typography variant="h6" sx={{ mb: 2 }}>
                  {this.getTitle()}
                </Typography>
                
                <Typography variant="body1" sx={{ mb: 3 }}>
                  {this.options.instructions}
                </Typography>
                
                {/* Jog Controls */}
                <JogControls />
                
                {/* Material Edit Button */}
                <Box sx={{ mt: 'auto' }}>
                  <Button
                    variant="outlined"
                    onClick={() => this.setMaterialEditorOpen(true)}
                    sx={{ mb: 2 }}
                  >
                    Edit Material
                  </Button>
                </Box>
              </Box>
              
              {/* Right panel with 3D view */}
              <Box sx={{ flex: 1, minHeight: 0 }}>
                <FullSizeCNCViewer
                  enableOrbit={false}
                  enableClampDragging={false}
                  viewType={CNCViewType.DefaultTop}
                  simulatorView={view}
                  machineState={MachineStateData.Instance}
                  machineData={MachineData.Instance}
                  job={MachineStateData.Instance.currentJob || Job.createTestJob()}
                />
              </Box>
              
              {/* Material Editor Dialog */}
              <MaterialEditor
                open={this.materialEditorOpen}
                onClose={() => this.setMaterialEditorOpen(false)}
                machineState={MachineStateData.Instance}
              />
            </Box>
          );
        }}
      />
    );
  }
}
