import type { OutputWithState } from '../IOStateData';
import { DefaultOutputs } from './DefaultOutputs';
import { MachineOutput } from './MachineOutput';

/**
 * Static factory for machine output definitions
 * These are the base configurations - actual numbers and states come from API
 */
export class OutputDefinitions {
    /**
     * Get all static output definitions
     * Centroid name is the key - our custom names and text can be customized
     */
    public static getDefinitions(): MachineOutput[] {
        return [
            // Centroid-mapped outputs
            new MachineOutput('SpindleOnOutput', 'Spindle', 'Spindle On', 'Spindle Off'),
            new MachineOutput('VacuumPump', 'Vacuum Hold Down', 'Vacuum On', 'Vacuum Off'),

            // Custom machine outputs (no centroid mapping - user-defined)
            new MachineOutput('CustomOutput1', 'Dust Collector', 'Dust On', 'Dust Off'),
            new MachineOutput('CustomOutput2', 'Drive Reset', 'Reset Active', 'Normal'),
            new MachineOutput('CustomOutput3', 'Tool Clamp', 'Tool Clamp Open', 'Tool Clamp Closed'),
            new MachineOutput('CustomOutput4', 'Mist Relay', 'Mist On', 'Mist Off'),
            new MachineOutput('CustomOutput5', 'Dust Cover Relay', 'Cover On', 'Cover Off'),
            new MachineOutput('CustomOutput6', 'Laser', 'Laser On', 'Laser Off'),
            new MachineOutput('CustomOutput7', 'Push Pins', 'Pins Extended', 'Pins Retracted'),
        ];
    }

    /**
     * Get output definition by centroid name
     */
    public static getByCentroidName(centroidName: string): MachineOutput | undefined {
        return this.getDefinitions().find(output => output.centroidName === centroidName);
    }

    /**
     * Combine API output definitions with our static metadata
     * @param apiDefinitions Output definitions from API (name + number)
     * @returns Combined definitions with metadata
     */
    public static combineWithMetadata(apiMappings: Array<{ number: number; centroidName?: string }>): Array<{ number: number; centroidName: string; name: string; activeText: string; inactiveText: string }> {
        const staticDefs = this.getDefinitions();

        return apiMappings.map(apiMapping => {
            // Find matching static definition by centroid name
            const staticDef = staticDefs.find(sd => sd.centroidName === apiMapping.centroidName);

            if (staticDef) {
                // Use static definition's metadata
                return {
                    number: apiMapping.number,
                    centroidName: apiMapping.centroidName || '',
                    name: staticDef.name,
                    activeText: staticDef.activeText,
                    inactiveText: staticDef.inactiveText
                };
            } else {
                // No matching metadata - use centroid name and default text
                return {
                    number: apiMapping.number,
                    centroidName: apiMapping.centroidName || '',
                    name: apiMapping.centroidName || `Output ${apiMapping.number}`,
                    activeText: 'Active',
                    inactiveText: 'Inactive'
                };
            }
        });
    }

    /**
     * Create full output state by combining API mappings, metadata, and current state
     * @param apiMappings Output mappings from API (number + centroidName)
     * @param currentStates Current state of outputs (number -> active/inactive)
     * @returns Full output definitions with state
     */
    /**
     * Create full output state by combining all static definitions, API mappings (used list), and current state
     * @param apiMappings Output mappings from API (used list - what's actually configured)
     * @param currentStates Current state of outputs (number -> active/inactive)
     * @returns Full output definitions with state
     */
    public static createFullState(
        apiMappings: Array<{ number: number; centroidName?: string }>,
        currentStates: Record<number, boolean>
    ): OutputWithState[] {
        const allDefaultOutputs = DefaultOutputs.getDefaults(); // Full list of all defined functions
        const result: OutputWithState[] = [];

        // Process all default definitions (full list)
        allDefaultOutputs.forEach(defaultOutput => {
            // Find corresponding API mapping (from used list)
            const apiMapping = apiMappings.find(api => api.centroidName === defaultOutput.centroidName);

            if (apiMapping) {
                // This output is both defined and used - combine API number with default metadata
                const { OutputWithState } = require('../IOStateData');
                const output = new OutputWithState();
                output.number = apiMapping.number;
                output.centroidName = defaultOutput.centroidName;
                output.name = defaultOutput.name;
                output.activeText = defaultOutput.activeText;
                output.inactiveText = defaultOutput.inactiveText;
                output.isActive = currentStates[apiMapping.number] ?? false;
                // Copy M94M95 mapping if it was set in defaults
                if (defaultOutput.getM94M95Mapping() !== 100 + defaultOutput.number) {
                    output.setM94M95Mapping(defaultOutput.getM94M95Mapping());
                }
                result.push(output);
            }
            // Skip outputs that don't have API mappings (no longer add them with number = 0)
        });        // Add any API mappings that don't have default definitions (unknown outputs from used list)
        apiMappings.forEach(apiMapping => {
            const hasDefaultDef = allDefaultOutputs.some(defaultOutput => defaultOutput.centroidName === apiMapping.centroidName);
            if (!hasDefaultDef) {
                const { OutputWithState } = require('../IOStateData');
                const output = new OutputWithState();
                output.number = apiMapping.number;
                output.centroidName = apiMapping.centroidName || '';
                output.name = apiMapping.centroidName || `Output ${apiMapping.number}`;
                output.activeText = 'Active';
                output.inactiveText = 'Inactive';
                output.isActive = currentStates[apiMapping.number] ?? false;
                result.push(output);
            }
        });

        // Filter out outputs with number = 0 (unmapped/unused outputs)
        return result.filter(output => output.number > 0);
    }
}
