export interface ApiTestResult {
  successCount: number;
  errorCount: number;
  lastExecuted?: Date;
}

export interface ApiTestStatsData {
  [methodName: string]: ApiTestResult;
}

export class ApiTestStats {
  private static readonly STORAGE_KEY = 'havencnc-api-test-stats';
  
  private static instance: ApiTestStats;
  private stats: ApiTestStatsData = {};

  private constructor() {
    this.loadFromStorage();
  }

  public static getInstance(): ApiTestStats {
    if (!ApiTestStats.instance) {
      ApiTestStats.instance = new ApiTestStats();
    }
    return ApiTestStats.instance;
  }

  public recordSuccess(methodName: string): void {
    if (!this.stats[methodName]) {
      this.stats[methodName] = { successCount: 0, errorCount: 0 };
    }
    this.stats[methodName].successCount++;
    this.stats[methodName].lastExecuted = new Date();
    this.saveToStorage();
  }

  public recordError(methodName: string): void {
    if (!this.stats[methodName]) {
      this.stats[methodName] = { successCount: 0, errorCount: 0 };
    }
    this.stats[methodName].errorCount++;
    this.stats[methodName].lastExecuted = new Date();
    this.saveToStorage();
  }

  public getStats(methodName: string): ApiTestResult {
    return this.stats[methodName] || { successCount: 0, errorCount: 0 };
  }

  public getAllStats(): ApiTestStatsData {
    return { ...this.stats };
  }

  public resetStats(methodName?: string): void {
    if (methodName) {
      // Reset specific method
      delete this.stats[methodName];
    } else {
      // Reset all stats
      this.stats = {};
    }
    this.saveToStorage();
  }

  public getTotalStats(): { totalSuccess: number; totalErrors: number; totalMethods: number } {
    let totalSuccess = 0;
    let totalErrors = 0;
    const totalMethods = Object.keys(this.stats).length;

    Object.values(this.stats).forEach(stat => {
      totalSuccess += stat.successCount;
      totalErrors += stat.errorCount;
    });

    return { totalSuccess, totalErrors, totalMethods };
  }

  private loadFromStorage(): void {
    try {
      const stored = localStorage.getItem(ApiTestStats.STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        // Convert date strings back to Date objects
        Object.keys(parsed).forEach(key => {
          if (parsed[key].lastExecuted) {
            parsed[key].lastExecuted = new Date(parsed[key].lastExecuted);
          }
        });
        this.stats = parsed;
      }
    } catch (error) {
      console.error('Failed to load API test stats from storage:', error);
      this.stats = {};
    }
  }

  private saveToStorage(): void {
    try {
      localStorage.setItem(ApiTestStats.STORAGE_KEY, JSON.stringify(this.stats));
    } catch (error) {
      console.error('Failed to save API test stats to storage:', error);
    }
  }
}