import { Wizard } from "../../../Wizard";
import { WizardManager } from "../../../Wizard/WizardManager";
import { ZAxisMethodSelectionStep } from "../steps/ZAxisMethodSelectionStep";
import { ZAxisReferenceType } from "./types";

export class SpoilboardSetupWizard extends Wizard {
  constructor() {
    const initialState = {
      method: null,
      referenceType: ZAxisReferenceType.SPOILBOARD,
      isProcessing: false,
      finalZPosition: null,
      jogAmount: 0.1,
      touchplateDetected: false,
    };

    super(
      null as any, // Temporary - will be set below
      initialState
    );

    // Now create the step with proper wizard reference - start with method selection
    const firstStep = new ZAxisMethodSelectionStep(this);
    this.firstStep = firstStep;
    this.currentStep = firstStep;
  }

  static show(): void {
    const wizard = new SpoilboardSetupWizard();
    WizardManager.Instance.start(wizard);
  }
}
