import { Wizard } from "../../../Wizard";
import { WizardManager } from "../../../Wizard/WizardManager";
import { ZAxisMethodSelectionStep } from "../steps/ZAxisMethodSelectionStep";
import { ZAxisReferenceType } from "./types";

export class BedSetupWizard extends Wizard {
  constructor() {
    const initialState = {
      method: null,
      referenceType: ZAxisReferenceType.BED,
      isProcessing: false,
      finalZPosition: null,
      jogAmount: 0.1,
      touchplateDetected: false,
    };

    // We'll create the step after super() so we can pass 'this'
    let firstStep: ZAxisMethodSelectionStep;
    
    super(
      null as any, // Temporary - will be set below
      initialState
    );

    // Now create the step with proper wizard reference
    firstStep = new ZAxisMethodSelectionStep(this);
    this.firstStep = firstStep;
    this.currentStep = firstStep;
  }

  static show(): void {
    const wizard = new BedSetupWizard();
    WizardManager.Instance.start(wizard);
  }
}
