import { IStorable } from '../../common/IStorable';
import { DataUtilities } from '../../utils/storage/DataUtilities';

/**
 * PIN for accessing system configuration
 * TODO: In production, this should be stored securely and masked
 * For now, using a simple constant for development
 */
export const SYSTEM_CONFIG_PIN = '5555';

/**
 * System configuration class for debugging and development settings
 * Implements IStorable for proper serialization/deserialization
 * 
 * IMPORTANT: When creating UI components for system configuration features,
 * always use colors from ConfigurationData.Instance for consistent theming:
 * - primaryColor, secondaryColor, backgroundColor, textColor, borderColor, etc.
 * - This ensures proper Material-UI theme integration and user customization
 */
export class SystemConfiguration implements IStorable {
  // Auto-Save Settings
  public showAutoSaveMessages: boolean = false;
  
  // Debug & Logging Settings
  public enableDebugLogging: boolean = false;
  public showTimingInfo: boolean = false;
  public showStateManagerEvents: boolean = false;
  
  // Performance & Validation Settings
  public enableValidationChecks: boolean = true;
  public showRenderingStats: boolean = false;

  constructor(data?: Partial<SystemConfiguration>) {
    if (data) {
      Object.assign(this, data);
    }
  }

  /**
   * IStorable implementation - serialize to JSON
   */
  public toJSON(): object {
    return DataUtilities.getStorageData(this, []);
  }

  /**
   * IStorable implementation - deserialize from JSON
   */
  public fromJSON(data: any): void {
    if (!data) return;
    DataUtilities.loadStorageData(this, data, []);
  }
}

/**
 * Default system configuration values
 */
export const DEFAULT_SYSTEM_CONFIG = new SystemConfiguration({
  showAutoSaveMessages: false,
  enableDebugLogging: false,
  showTimingInfo: false,
  showStateManagerEvents: false,
  enableValidationChecks: true,
  showRenderingStats: false,
});
